// 题目：序号巡检轨迹
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(n)；空间 O(n)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        // 条件判断
        int n = nextInt();
        int[] pos = new int[n + 1];
        // 枚举位置 i
        for (int i = 1; i <= n; i++) pos[nextInt()] = i;
        int left = 0;
        // 循环处理
        for (int v = 1; v < n; v++) if (pos[v + 1] < pos[v]) left++;
        System.out.println(left + " " + (n - 1 - left));
    }
}

// 题目：监测样本偏离判定
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）
// 复杂度：时间 补全和标准化为 O((n+m)d)； svd_solver="full" 对 n d 训练矩阵做完整 SVD，复杂度为 O(nd(n,d))；训练集与测试集投影、重建为 O((n+m)dk)；空间 O((n+m)d+d k)，用于保存两组数据、标准化与重建结果以及 PCA 主成分

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static String nextLine() throws IOException { return br.readLine(); }

    static class Json {
        private final String s; private int i;
        Json(String s) { this.s = s; }
        // 核心方法：parse
        static Object parse(String s) { Json j = new Json(s); j.ws(); return j.value(); }
        private void ws() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }
        private Object value() {
            ws(); char c = s.charAt(i);
            // 条件判断
            if (c == '{') return object();
            // 条件判断
            if (c == '[') return array();
            // 条件判断
            if (c == '"') return string();
            // 条件判断
            if (c == 't') { i += 4; return Boolean.TRUE; }
            // 条件判断
            if (c == 'f') { i += 5; return Boolean.FALSE; }
            // 条件判断
            if (c == 'n') { i += 4; return null; }
            // 返回结果
            return number();
        }
        private Map<String,Object> object() {
            Map<String,Object> m = new LinkedHashMap<>();
            i++; ws();
            // 条件判断
            if (s.charAt(i) == '}') { i++; return m; }
            // 循环处理
            while (true) {
                ws(); String k = string(); ws(); i++;
                Object v = value(); m.put(k, v); ws();
                char c = s.charAt(i++); if (c == '}') break;
            }
            // 返回结果
            return m;
        }
        private List<Object> array() {
            List<Object> a = new ArrayList<>();
            i++; ws();
            // 条件判断
            if (s.charAt(i) == ']') { i++; return a; }
            // 循环处理
            while (true) {
                a.add(value()); ws();
                char c = s.charAt(i++); if (c == ']') break;
            }
            // 返回结果
            return a;
        }
        private String string() {
            StringBuilder b = new StringBuilder(); i++;
            // 循环处理
            while (true) {
                char c = s.charAt(i++);
                // 条件判断
                if (c == '"') break;
                // 条件判断
                if (c == (char)92) {
                    char e = s.charAt(i++);
                    // 条件判断
                    if (e == 'n') b.append((char)10);
                    else if (e == 't') b.append((char)9);
                    else if (e == 'r') b.append((char)13);
                    else if (e == 'b') b.append((char)8);
                    else if (e == 'f') b.append((char)12);
                    else if (e == 'u') { b.append((char)Integer.parseInt(s.substring(i, i + 4), 16)); i += 4; }
                    else b.append(e);
                } else b.append(c);
            }
            // 返回结果
            return b.toString();
        }
        private Object number() {
            int start = i;
            // 循环处理
            while (i < s.length() && "+-0123456789.eE".indexOf(s.charAt(i)) >= 0) i++;
            // 返回结果
            return Double.parseDouble(s.substring(start, i));
        }
    }
    // 核心方法：toMatrix
    static double[][] toMatrix(List<Object> rows) {
        int n = rows.size();
        int d = n > 0 ? ((List<Object>) rows.get(0)).size() : 0;
        double[][] m = new double[n][d];
        // 循环处理
        for (int r = 0; r < n; r++) {
            List<Object> row = (List<Object>) rows.get(r);
            // 循环处理
            for (int c = 0; c < d; c++) {
                Object v = row.get(c);
                m[r][c] = (v == null) ? Double.NaN : ((Number) v).doubleValue();
            }
        }
        // 返回结果
        return m;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        StringBuilder inp = new StringBuilder(); String line;
        // 循环处理
        while ((line = nextLine()) != null) inp.append(line).append((char)10);
        Map<String,Object> root = (Map<String,Object>) Json.parse(inp.toString());
        double[][] train = toMatrix((List<Object>) root.get("train"));
        double[][] test = toMatrix((List<Object>) root.get("test"));
        int n = train.length, p = n > 0 ? train[0].length : 0;
        double[] mean = new double[p];
        // 枚举阶段 j
        for (int j = 0; j < p; j++) {
            double s = 0; int cnt = 0;
            // 枚举位置 i
            for (int i = 0; i < n; i++) if (!Double.isNaN(train[i][j])) { s += train[i][j]; cnt++; }
            mean[j] = cnt > 0 ? s / cnt : 0.0;
        }
        // 枚举位置 i
        for (int i = 0; i < n; i++) for (int j = 0; j < p; j++) if (Double.isNaN(train[i][j])) train[i][j] = mean[j];
        int nt = test.length;
        // 枚举位置 i
        for (int i = 0; i < nt; i++) for (int j = 0; j < p; j++) if (Double.isNaN(test[i][j])) test[i][j] = mean[j];
        double[] mu = new double[p], scale = new double[p];
        // 枚举阶段 j
        for (int j = 0; j < p; j++) {
            double s = 0;
            // 枚举位置 i
            for (int i = 0; i < n; i++) s += train[i][j];
            mu[j] = s / n;
            double v = 0;
            // 枚举位置 i
            for (int i = 0; i < n; i++) { double d = train[i][j] - mu[j]; v += d * d; }
            v /= n;
            scale[j] = Math.sqrt(v);
            // 条件判断
            if (scale[j] == 0.0) scale[j] = 1.0;
        }
        double[][] tr = new double[n][p];
        // 枚举位置 i
        for (int i = 0; i < n; i++) for (int j = 0; j < p; j++) tr[i][j] = (train[i][j] - mu[j]) / scale[j];
        double[][] te = new double[nt][p];
        // 枚举位置 i
        for (int i = 0; i < nt; i++) for (int j = 0; j < p; j++) te[i][j] = (test[i][j] - mu[j]) / scale[j];
        double[][] cov = new double[p][p];
        // 循环处理
        for (int a = 0; a < p; a++) for (int b = 0; b < p; b++) {
            double s = 0;
            // 枚举位置 i
            for (int i = 0; i < n; i++) s += tr[i][a] * tr[i][b];
            cov[a][b] = n > 1 ? s / (n - 1) : 0.0;
        }
        double[][] vec = new double[p][p];
        double[] val = new double[p];
        jacobi(cov, val, vec, p);
        Integer[] order = new Integer[p];
        // 枚举位置 i
        for (int i = 0; i < p; i++) order[i] = i;
        final double[] vv = val;
        Arrays.sort(order, (x, y) -> Double.compare(vv[y], vv[x]));
        double total = 0;
        // 枚举位置 i
        for (int i = 0; i < p; i++) total += Math.max(val[i], 0.0);
        int k = p;
        // 条件判断
        if (total > 0) {
            double cum = 0;
            // 枚举位置 i
            for (int i = 0; i < p; i++) {
                cum += Math.max(val[order[i]], 0.0) / total;
                // 条件判断
                if (cum > 0.95) { k = i + 1; break; }
            }
        }
        double[][] comp = new double[k][p];
        // 循环处理
        for (int c = 0; c < k; c++) for (int j = 0; j < p; j++) comp[c][j] = vec[j][order[c]];
        double[] trainScores = new double[n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) trainScores[i] = residual2(tr[i], comp, k, p);
        double[] testScores = new double[nt];
        // 枚举位置 i
        for (int i = 0; i < nt; i++) testScores[i] = residual2(te[i], comp, k, p);
        double threshold = percentile(trainScores, 95.0);
        StringBuilder out = new StringBuilder("[");
        // 枚举位置 i
        for (int i = 0; i < nt; i++) {
            // 条件判断
            if (i > 0) out.append(", ");
            out.append(testScores[i] > threshold ? 1 : 0);
        }
        out.append("]");
        System.out.println(out);
    }
    // 核心方法：residual2
    static double residual2(double[] x, double[][] comp, int k, int p) {
        double s = 0;
        // 循环处理
        for (int c = 0; c < k; c++) {
            double dot = 0;
            // 枚举阶段 j
            for (int j = 0; j < p; j++) dot += comp[c][j] * x[j];
            s += dot * dot;
        }
        double norm2 = 0;
        // 枚举阶段 j
        for (int j = 0; j < p; j++) norm2 += x[j] * x[j];
        double resid = norm2 - s;
        // 条件判断
        if (resid < 0 && resid > -1e-9) resid = 0;
        // 返回结果
        return resid;
    }
    // 核心方法：percentile
    static double percentile(double[] arr, double q) {
        double[] a = arr.clone();
        Arrays.sort(a);
        int n = a.length;
        // 条件判断
        if (n == 0) return 0;
        double rank = (n - 1) * q / 100.0;
        int lo = (int) Math.floor(rank);
        int hi = (int) Math.ceil(rank);
        // 条件判断
        if (lo == hi) return a[lo];
        double frac = rank - lo;
        // 返回结果
        return a[lo] + (a[hi] - a[lo]) * frac;
    }
    // 核心方法：jacobi
    static void jacobi(double[][] a0, double[] eval, double[][] evec, int n) {
        double[][] a = new double[n][n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) a[i] = a0[i].clone();
        // 枚举位置 i
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) evec[i][j] = (i == j) ? 1.0 : 0.0;
        // 循环处理
        for (int sweep = 0; sweep < 100; sweep++) {
            double off = 0;
            // 枚举位置 i
            for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) off += a[i][j] * a[i][j];
            // 条件判断
            if (off < 1e-22) break;
            // 循环处理
            for (int p1 = 0; p1 < n; p1++) {
                // 循环处理
                for (int q1 = p1 + 1; q1 < n; q1++) {
                    // 条件判断
                    if (Math.abs(a[p1][q1]) < 1e-18) continue;
                    double theta = (a[q1][q1] - a[p1][p1]) / (2.0 * a[p1][q1]);
                    double t = Math.signum(theta) / (Math.abs(theta) + Math.sqrt(theta * theta + 1.0));
                    // 条件判断
                    if (theta == 0) t = 1.0;
                    double c = 1.0 / Math.sqrt(t * t + 1.0);
                    double s = t * c;
                    // 枚举位置 i
                    for (int i = 0; i < n; i++) {
                        double aip = a[i][p1], aiq = a[i][q1];
                        a[i][p1] = c * aip - s * aiq;
                        a[i][q1] = s * aip + c * aiq;
                    }
                    // 枚举位置 i
                    for (int i = 0; i < n; i++) {
                        double api = a[p1][i], aqi = a[q1][i];
                        a[p1][i] = c * api - s * aqi;
                        a[q1][i] = s * api + c * aqi;
                    }
                    // 枚举位置 i
                    for (int i = 0; i < n; i++) {
                        double vip = evec[i][p1], viq = evec[i][q1];
                        evec[i][p1] = c * vip - s * viq;
                        evec[i][q1] = s * vip + c * viq;
                    }
                }
            }
        }
        // 枚举位置 i
        for (int i = 0; i < n; i++) eval[i] = a[i][i];
    }
}

