// 题目：防风核心
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(N)；空间 算法本身的额外空间为 O(1)；若计入一次性读入的整数数组和输出缓冲区，则为 O(N+T)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        // 条件判断
        int t = nextInt();
        StringBuilder sb = new StringBuilder();
        // 循环处理
        for (int k = 0; k < t; k++) {
            int n = nextInt();
            long rightMax = Long.MIN_VALUE / 4, leftMax = Long.MIN_VALUE / 4;
            // 枚举位置 i
            for (int i = 1; i <= n; i++) {
                long v = nextLong();
                rightMax = Math.max(rightMax, v + i);
                leftMax = Math.max(leftMax, v - i);
            }
            long best = Long.MAX_VALUE / 4;
            // 循环处理
            for (int p = 1; p <= n; p++) {
                long need = Math.max(rightMax - p, leftMax + p);
                best = Math.min(best, need);
            }
            // 条件判断
            if (k > 0) sb.append((char)10);
            sb.append(best);
        }
        System.out.print(sb);
    }
}

