// 题目：抽检共现项集
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static String nextLine() throws IOException { return br.readLine(); }

    static class Json {
        private final String s; private int i;
        Json(String s) { this.s = s; }
        // 核心方法：parse
        static Object parse(String s) { Json j = new Json(s); j.ws(); return j.value(); }
        private void ws() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }
        private Object value() {
            ws(); char c = s.charAt(i);
            // 条件判断
            if (c == '{') return object();
            // 条件判断
            if (c == '[') return array();
            // 条件判断
            if (c == '"') return string();
            // 条件判断
            if (c == 't') { i += 4; return Boolean.TRUE; }
            // 条件判断
            if (c == 'f') { i += 5; return Boolean.FALSE; }
            // 条件判断
            if (c == 'n') { i += 4; return null; }
            // 返回结果
            return number();
        }
        private Map<String,Object> object() {
            Map<String,Object> m = new LinkedHashMap<>();
            i++; ws();
            // 条件判断
            if (s.charAt(i) == '}') { i++; return m; }
            // 循环处理
            while (true) {
                ws(); String k = string(); ws(); i++;
                Object v = value(); m.put(k, v); ws();
                char c = s.charAt(i++); if (c == '}') break;
            }
            // 返回结果
            return m;
        }
        private List<Object> array() {
            List<Object> a = new ArrayList<>();
            i++; ws();
            // 条件判断
            if (s.charAt(i) == ']') { i++; return a; }
            // 循环处理
            while (true) {
                a.add(value()); ws();
                char c = s.charAt(i++); if (c == ']') break;
            }
            // 返回结果
            return a;
        }
        private String string() {
            StringBuilder b = new StringBuilder(); i++;
            // 循环处理
            while (true) {
                char c = s.charAt(i++);
                // 条件判断
                if (c == '"') break;
                // 条件判断
                if (c == (char)92) { char e = s.charAt(i++); if (e == 'n') b.append((char)10); else b.append(e); }
                else b.append(c);
            }
            // 返回结果
            return b.toString();
        }
        private Object number() {
            int start = i;
            // 循环处理
            while (i < s.length() && "+-0123456789.eE".indexOf(s.charAt(i)) >= 0) i++;
            // 返回结果
            return Double.parseDouble(s.substring(start, i));
        }
    }
    // 核心方法：generateCandidates
    static List<List<Integer>> generateCandidates(List<List<Integer>> previous) {
        List<List<Integer>> prev = new ArrayList<>(previous);
        prev.sort((x, y) -> { for (int i = 0; i < x.size(); i++) { int c = x.get(i).compareTo(y.get(i)); if (c != 0) return c; } return 0; });
        Set<List<Integer>> known = new HashSet<>(prev);
        Set<List<Integer>> cand = new HashSet<>();
        // 枚举位置 i
        for (int i = 0; i < prev.size(); i++) for (int j = i + 1; j < prev.size(); j++) {
            List<Integer> left = prev.get(i), right = prev.get(j);
            boolean samePrefix = true;
            // 循环处理
            for (int t = 0; t < left.size() - 1; t++) if (!left.get(t).equals(right.get(t))) { samePrefix = false; break; }
            // 条件判断
            if (!samePrefix) continue;
            List<Integer> candidate = new ArrayList<>(left); candidate.add(right.get(right.size() - 1));
            boolean okAll = true;
            // 循环处理
            for (int p = 0; p < candidate.size(); p++) {
                List<Integer> sub = new ArrayList<>(candidate); sub.remove(p);
                // 条件判断
                if (!known.contains(sub)) { okAll = false; break; }
            }
            // 条件判断
            if (okAll) cand.add(candidate);
        }
        List<List<Integer>> res = new ArrayList<>(cand);
        res.sort((x, y) -> { for (int i = 0; i < x.size(); i++) { int c = x.get(i).compareTo(y.get(i)); if (c != 0) return c; } return 0; });
        // 返回结果
        return res;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String line = nextLine();
        Map<String,Object> root = (Map<String,Object>) Json.parse(line);
        List<Object> recsObj = (List<Object>) root.get("records");
        List<Set<Integer>> records = new ArrayList<>();
        // 循环处理
        for (Object o : recsObj) { Set<Integer> set = new HashSet<>(); for (Object v : (List<Object>) o) set.add((int) Math.round(((Number) v).doubleValue())); records.add(set); }
        int minCnt = ((Number) root.get("min_cnt")).intValue();
        Map<Integer,Integer> singleton = new HashMap<>();
        // 循环处理
        for (Set<Integer> rec : records) for (int v : rec) singleton.merge(v, 1, Integer::sum);
        Map<List<Integer>, Integer> support = new HashMap<>();
        List<List<Integer>> level = new ArrayList<>();
        Integer[] keys = singleton.keySet().toArray(new Integer[0]);
        Arrays.sort(keys);
        // 循环处理
        for (int v : keys) { int cnt = singleton.get(v); if (cnt >= minCnt) { List<Integer> is = new ArrayList<>(); is.add(v); level.add(is); support.put(is, cnt); } }
        List<List<Integer>> allFrequent = new ArrayList<>();
        // 循环处理
        while (!level.isEmpty()) {
            allFrequent.addAll(level);
            List<List<Integer>> candidates = generateCandidates(level);
            List<List<Integer>> next = new ArrayList<>();
            // 循环处理
            for (List<Integer> cand : candidates) {
                int cnt = 0;
                // 循环处理
                for (Set<Integer> rec : records) { boolean all = true; for (int v : cand) if (!rec.contains(v)) { all = false; break; } if (all) cnt++; }
                // 条件判断
                if (cnt >= minCnt) { next.add(cand); support.put(cand, cnt); }
            }
            level = next;
        }
        allFrequent.sort((x, y) -> { if (x.size() != y.size()) return x.size() - y.size(); for (int i = 0; i < x.size(); i++) { int c = x.get(i).compareTo(y.get(i)); if (c != 0) return c; } return 0; });
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        // 循环处理
        for (int idx = 0; idx < allFrequent.size(); idx++) {
            // 条件判断
            if (idx > 0) sb.append(',');
            List<Integer> is = allFrequent.get(idx);
            sb.append('[');
            // 枚举阶段 j
            for (int j = 0; j < is.size(); j++) { if (j > 0) sb.append(','); sb.append(is.get(j)); }
            sb.append(']').append(',').append(support.get(is));
            sb.append(']');
        }
        sb.append(']');
        System.out.println(sb);
    }
}

