            // 返回结果
            return Double.parseDouble(s.substring(start, i));
        }
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String line = nextLine();
        Map<String,Object> data = (Map<String,Object>) Json.parse(line);
        List<Object> calObj = (List<Object>) data.get("cal_y");
        List<Object> cp1Obj = (List<Object>) data.get("cal_p1");
        List<Object> tp1Obj = (List<Object>) data.get("test_p1");
        int n = calObj.size();
        double[] scores = new double[n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            int y = (int) Math.round(((Number) calObj.get(i)).doubleValue());
            double p = ((Number) cp1Obj.get(i)).doubleValue();
            scores[i] = (y == 1) ? 1.0 - p : p;
        }
        Arrays.sort(scores);
        int k = (int) Math.ceil((n + 1) * (1.0 - 0.2)) - 1;
        // 条件判断
        if (k >= n) k = n - 1;
        double q = scores[k];
        int m = tp1Obj.size();
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        // 枚举位置 i
        for (int i = 0; i < m; i++) {
            double p = ((Number) tp1Obj.get(i)).doubleValue();
            boolean take0 = p <= q;
            boolean take1 = p >= 1.0 - q;
            int r = (take0 && take1) ? -1 : (take1 ? 1 : (take0 ? 0 : -2));
            // 条件判断
            if (i > 0) sb.append(',');
            sb.append(r);
        }
        sb.append(']');
        System.out.println(sb);
    }
}

