// 题目：感知机二分类
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(End+md)；由于 E 为常数，也可写作 O(nd+md)；空间 O(nd+md)，主要用于增广后的训练和测试矩阵；额外权重空间为 O(d)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static String nextLine() throws IOException { return br.readLine(); }

    static class Json {
        private final String s; private int i;
        Json(String s) { this.s = s; }
        // 核心方法：parse
        static Object parse(String s) { Json j = new Json(s); j.ws(); return j.value(); }
        private void ws() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }
        private Object value() {
            ws(); char c = s.charAt(i);
            // 条件判断
            if (c == '{') return object();
            // 条件判断
            if (c == '[') return array();
            // 条件判断
            if (c == '"') return string();
            // 条件判断
            if (c == 't') { i += 4; return Boolean.TRUE; }
            // 条件判断
            if (c == 'f') { i += 5; return Boolean.FALSE; }
            // 条件判断
            if (c == 'n') { i += 4; return null; }
            // 返回结果
            return number();
        }
        private Map<String,Object> object() {
            Map<String,Object> m = new LinkedHashMap<>();
            i++; ws();
            // 条件判断
            if (s.charAt(i) == '}') { i++; return m; }
            // 循环处理
            while (true) {
                ws(); String k = string(); ws(); i++;
                Object v = value(); m.put(k, v); ws();
                char c = s.charAt(i++); if (c == '}') break;
            }
            // 返回结果
            return m;
        }
        private List<Object> array() {
            List<Object> a = new ArrayList<>();
            i++; ws();
            // 条件判断
            if (s.charAt(i) == ']') { i++; return a; }
            // 循环处理
            while (true) {
                a.add(value()); ws();
                char c = s.charAt(i++); if (c == ']') break;
            }
            // 返回结果
            return a;
        }
        private String string() {
            StringBuilder b = new StringBuilder(); i++;
            // 循环处理
            while (true) {
                char c = s.charAt(i++);
                // 条件判断
                if (c == '"') break;
                // 条件判断
                if (c == (char)92) { char e = s.charAt(i++); if (e == 'n') b.append((char)10); else b.append(e); }
                else b.append(c);
            }
            // 返回结果
            return b.toString();
        }
        private Object number() {
            int start = i;
            // 循环处理
            while (i < s.length() && "+-0123456789.eE".indexOf(s.charAt(i)) >= 0) i++;
            // 返回结果
            return Double.parseDouble(s.substring(start, i));
        }
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        StringBuilder inp = new StringBuilder(); String line;
        // 循环处理
        while ((line = nextLine()) != null) inp.append(line).append((char)10);
        Map<String,Object> data = (Map<String,Object>) Json.parse(inp.toString());
        List<Object> train = (List<Object>) data.get("train");
        List<Object> test = (List<Object>) data.get("test");
        int sampleCount = train.size();
        int dimension = ((List<Object>) ((List<Object>) train.get(0)).get(0)).size();
        double[][] trainX = new double[sampleCount][dimension];
        double[] targets = new double[sampleCount];
        // 枚举位置 i
        for (int i = 0; i < sampleCount; i++) {
            List<Object> row = (List<Object>) train.get(i);
            List<Object> feats = (List<Object>) row.get(0);
            // 枚举阶段 j
            for (int j = 0; j < dimension; j++) trainX[i][j] = ((Number) feats.get(j)).doubleValue();
            int label = (int) Math.round(((Number) row.get(1)).doubleValue());
            targets[i] = 2.0 * label - 1.0;
        }
        double[] weights = new double[dimension + 1];
        int epochs = 10; double lr = 1.0;
        // 循环处理
        for (int ep = 0; ep < epochs; ep++) {
            // 枚举位置 i
            for (int i = 0; i < sampleCount; i++) {
                double score = weights[0];
                // 枚举阶段 j
                for (int j = 0; j < dimension; j++) score += weights[j + 1] * trainX[i][j];
                double prediction = score >= 0.0 ? 1.0 : -1.0;
                // 条件判断
                if (prediction != targets[i]) {
                    weights[0] += lr * targets[i];
                    // 枚举阶段 j
                    for (int j = 0; j < dimension; j++) weights[j + 1] += lr * targets[i] * trainX[i][j];
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        // 条件判断
        if (test != null && !test.isEmpty()) {
            // 枚举位置 i
            for (int i = 0; i < test.size(); i++) {
                List<Object> feats = (List<Object>) test.get(i);
                double score = weights[0];
                // 枚举阶段 j
                for (int j = 0; j < dimension; j++) score += weights[j + 1] * ((Number) feats.get(j)).doubleValue();
                int pred = score >= 0.0 ? 1 : 0;
                // 条件判断
                if (i > 0) sb.append(", ");
                sb.append(pred);
            }
        }
        sb.append(']');
        System.out.println(sb);
    }
}

