// 题目：镜子实验室
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(nm)，各条链互不相交，总访问次数不超过 4nm，建立网格也为线性开销；空间 O(nm)，保存带边框的网格；入口和输入行均逐个产生

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        // 条件判断
        int t = nextInt();
        int[][] TURN = {{0,1,2,3},{1,0,3,2},{3,2,1,0}};
        StringBuilder out = new StringBuilder();
        // 循环处理
        for (int tc = 0; tc < t; tc++) {
            int n = nextInt();
            int m = nextInt();
            int width = m + 2;
            byte[] grid = new byte[(n + 2) * width];
            Arrays.fill(grid, (byte)3);
            // 循环处理
            for (int r = 1; r <= n; r++) {
                String row = next();
                // 循环处理
                for (int c = 1; c <= m; c++) {
                    char ch = row.charAt(c - 1);
                    int v = ch == '.' ? 0 : (ch == '/' ? 1 : 2);
                    grid[r * width + c] = (byte) v;
                }
            }
            int[] steps = {-width, 1, width, -1};
            long total = 0;
            // 循环处理
            for (int col = 1; col <= m; col++) {
                total += escape(grid, width + col, 2, TURN, steps);
                total += escape(grid, n * width + col, 0, TURN, steps);
            }
            // 循环处理
            for (int row = 1; row <= n; row++) {
                total += escape(grid, row * width + 1, 1, TURN, steps);
                total += escape(grid, row * width + m, 3, TURN, steps);
            }
            // 条件判断
            if (tc > 0) out.append((char)10);
            out.append(total);
        }
        System.out.print(out);
    }
    // 核心方法：escape
    static long escape(byte[] grid, int pos, int direction, int[][] TURN, int[] steps) {
        long count = 0;
        // 循环处理
        while (grid[pos] != 3) {
            direction = TURN[grid[pos]][direction];
            pos += steps[direction];
            count++;
        }
        // 返回结果
        return count;
    }
}

// 题目：回归任务反向传播机理
