        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        int din = nextInt(), dhid = nextInt(), dout = nextInt();
        double[][] W1 = new double[dhid][din];
        // 枚举位置 i
        for (int i = 0; i < dhid; i++) for (int j = 0; j < din; j++) W1[i][j] = Double.parseDouble(next());
        double[] b1 = new double[dhid];
        // 枚举位置 i
        for (int i = 0; i < dhid; i++) b1[i] = Double.parseDouble(next());
        double[][] W2 = new double[dout][dhid];
        // 枚举位置 i
        for (int i = 0; i < dout; i++) for (int j = 0; j < dhid; j++) W2[i][j] = Double.parseDouble(next());
        double[] b2 = new double[dout];
        // 枚举位置 i
        for (int i = 0; i < dout; i++) b2[i] = Double.parseDouble(next());
        double[] x = new double[din];
        // 枚举位置 i
        for (int i = 0; i < din; i++) x[i] = Double.parseDouble(next());
        double[] ytrue = new double[dout];
        // 枚举位置 i
        for (int i = 0; i < dout; i++) ytrue[i] = Double.parseDouble(next());
        double eta = Double.parseDouble(next());
        double[] z1 = new double[dhid];
        // 枚举位置 i
        for (int i = 0; i < dhid; i++) { double s = b1[i]; for (int j = 0; j < din; j++) s += W1[i][j] * x[j]; z1[i] = s; }
        double[] a1 = new double[dhid];
        // 枚举位置 i
        for (int i = 0; i < dhid; i++) a1[i] = Math.max(z1[i], 0.0);
        double[] ypred = new double[dout];
        // 枚举位置 i
        for (int i = 0; i < dout; i++) { double s = b2[i]; for (int j = 0; j < dhid; j++) s += W2[i][j] * a1[j]; ypred[i] = s; }
        double[] delta2 = new double[dout];
        // 枚举位置 i
        for (int i = 0; i < dout; i++) delta2[i] = ypred[i] - ytrue[i];
        double[][] gradW2 = new double[dout][dhid];
        // 枚举位置 i
        for (int i = 0; i < dout; i++) for (int j = 0; j < dhid; j++) gradW2[i][j] = delta2[i] * a1[j];
        double[] delta1 = new double[dhid];
        // 枚举阶段 j
        for (int j = 0; j < dhid; j++) { double s = 0; for (int i = 0; i < dout; i++) s += W2[i][j] * delta2[i]; delta1[j] = s * (z1[j] > 0 ? 1.0 : 0.0); }
        double[][] gradW1 = new double[dhid][din];
        // 枚举位置 i
        for (int i = 0; i < dhid; i++) for (int j = 0; j < din; j++) gradW1[i][j] = delta1[i] * x[j];
        // 枚举位置 i
        for (int i = 0; i < dhid; i++) { for (int j = 0; j < din; j++) W1[i][j] -= eta * gradW1[i][j]; b1[i] -= eta * delta1[i]; }
        // 枚举位置 i
        for (int i = 0; i < dout; i++) { for (int j = 0; j < dhid; j++) W2[i][j] -= eta * gradW2[i][j]; b2[i] -= eta * delta2[i]; }
        StringBuilder sb = new StringBuilder();
        // 枚举位置 i
        for (int i = 0; i < dhid; i++) { if (sb.length() > 0) sb.append((char)10); sb.append(fmtRow(W1[i])); }
        sb.append((char)10).append(fmtRow(b1));
        // 枚举位置 i
        for (int i = 0; i < dout; i++) sb.append((char)10).append(fmtRow(W2[i]));
        sb.append((char)10).append(fmtRow(b2));
        sb.append((char)10).append(fmtRow(ypred));
        System.out.println(sb);
    }
    // 核心方法：fmtRow
    static String fmtRow(double[] row) {
        StringBuilder b = new StringBuilder();
        // 枚举位置 i
        for (int i = 0; i < row.length; i++) { if (i > 0) b.append(' '); b.append(String.format(Locale.US, "%.6f", row[i])); }
        // 返回结果
        return b.toString();
    }
}

