// 题目：智能物流定价引擎
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(q)，ADD 和 QUERY 均为 O(1) 空间复杂度 ：O(1)，只维护五个累加量与一个退化标志；空间 O(1)，只维护五个累加量与一个退化标志

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        // 条件判断
        int q = nextInt();
        long n = 0;
        double Sx = 0, Sy = 0, Sxx = 0, Sxy = 0;
        long firstX = 0; boolean haveFirst = false; boolean sameX = true;
        StringBuilder sb = new StringBuilder(); boolean firstOut = true;
        // 枚举位置 i
        for (int i = 0; i < q; i++) {
            String op = next();
            // 条件判断
            if (op.equals("ADD")) {
                long x = nextLong(); long y = nextLong();
                // 条件判断
                if (!haveFirst) { firstX = x; haveFirst = true; } else if (x != firstX) sameX = false;
                n++; Sx += x; Sy += y; Sxx += (double) x * x; Sxy += (double) x * y;
            } else {
                long x0 = nextLong();
                double val;
                // 条件判断
                if (n == 0) val = 0.0;
                else if (sameX) val = Sy / n;
                else {
                    double num = n * Sxy - Sx * Sy;
                    double den = n * Sxx - Sx * Sx;
                    double a = num / den;
                    double b = (Sy - a * Sx) / n;
                    val = a * x0 + b;
                }
                // 条件判断
                if (!firstOut) sb.append((char)10);
                firstOut = false;
                sb.append(String.format(Locale.US, "%.6f", val));
            }
        }
        System.out.print(sb);
    }
}

items.books/ai-exam/ai-2026/华为/017-Expert-Choi:
// 题目：Expert Choice Routing
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(N d E + E S d^2)，门控分数 O(N d E)，聚合阶段共 E S 次 token 变换、每次 O(d^2) 空间复杂度 ：O(N E + E d^2)，分别存储权重矩阵和所有专家变换矩阵；空间 O(N E + E d^2)，分别存储权重矩阵和所有专家变换矩阵

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 核心方法：fmt2
    static String fmt2(double v) { String t = String.format(Locale.US, "%.2f", v); return t.equals("-0.00") ? "0.00" : t; }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        int n = nextInt(), d = nextInt(), e = nextInt(), s = nextInt();
        // 条件判断
        if (n < 1 || d < 1 || e < 1 || s < 1 || s > n) { System.out.println("0"); return; }
        double[][] X = new double[n][d];
        // 枚举位置 i
        for (int i = 0; i < n; i++) for (int j = 0; j < d; j++) X[i][j] = Double.parseDouble(next());
        double[][] Wg = new double[d][e];
        // 枚举位置 i
        for (int i = 0; i < d; i++) for (int j = 0; j < e; j++) Wg[i][j] = Double.parseDouble(next());
        double[][][] We = new double[e][d][d];
        // 循环处理
        for (int ee = 0; ee < e; ee++) for (int i = 0; i < d; i++) for (int j = 0; j < d; j++) We[ee][i][j] = Double.parseDouble(next());
        double[][] scores = new double[n][e];
        // 枚举位置 i
        for (int i = 0; i < n; i++) for (int ee = 0; ee < e; ee++) { double sum = 0; for (int k = 0; k < d; k++) sum += X[i][k] * Wg[k][ee]; scores[i][ee] = sum; }
        double[][] W = new double[n][e];
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            double mx = Double.NEGATIVE_INFINITY;
            // 循环处理
            for (int ee = 0; ee < e; ee++) if (scores[i][ee] > mx) mx = scores[i][ee];
            double sum = 0;
            // 循环处理
            for (int ee = 0; ee < e; ee++) { double v = Math.exp(scores[i][ee] - mx); W[i][ee] = v; sum += v; }
            // 循环处理
            for (int ee = 0; ee < e; ee++) W[i][ee] /= sum;
        }
        double[][] Y = new double[n][d];
        // 循环处理
        for (int ee = 0; ee < e; ee++) {
            Integer[] idx = new Integer[n];
            // 枚举位置 i
            for (int i = 0; i < n; i++) idx[i] = i;
            final double[][] Wf = W; final int col = ee;
            Arrays.sort(idx, (a, b) -> { int c = Double.compare(Wf[b][col], Wf[a][col]); if (c != 0) return c; return Integer.compare(a, b); });
            // 循环处理
            for (int t = 0; t < s; t++) {
                int i = idx[t]; double coef = W[i][ee];
                double[] xw = new double[d];
                // 循环处理
                for (int k = 0; k < d; k++) { double sum = 0; for (int j = 0; j < d; j++) sum += X[i][j] * We[ee][j][k]; xw[k] = sum; }
                // 循环处理
                for (int k = 0; k < d; k++) Y[i][k] += coef * xw[k];
            }
        }
        StringBuilder sb = new StringBuilder();
        // 枚举位置 i
        for (int i = 0; i < n; i++) { if (i > 0) sb.append((char)10); for (int k = 0; k < d; k++) { if (k > 0) sb.append(' '); sb.append(fmt2(Y[i][k])); } }
        System.out.println(sb);
    }
}

