// 题目：自动驾驶障碍物检测
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(T N K)，其中 T 为迭代轮数（上限 100），每轮对 N 个点各算 K 个常数维距离 空间复杂度 ：O(N K)，主要是每轮的距离矩阵；空间 O(N K)，主要是每轮的距离矩阵

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        double[][] pts = new double[n][3];
        // 枚举位置 i
        for (int i = 0; i < n; i++) for (int j = 0; j < 3; j++) pts[i][j] = Double.parseDouble(next());
        double[][] centroids = new double[k][3];
        // 循环处理
        for (int c = 0; c < k; c++) centroids[c] = pts[c].clone();
        int[] labels = new int[n];
        // 循环处理
        for (int iter = 0; iter < 100; iter++) {
            // 枚举位置 i
            for (int i = 0; i < n; i++) {
                int best = 0; double bd = Double.MAX_VALUE;
                // 循环处理
                for (int c = 0; c < k; c++) { double dd = 0; for (int j = 0; j < 3; j++) { double df = pts[i][j] - centroids[c][j]; dd += df * df; } if (dd < bd) { bd = dd; best = c; } }
                labels[i] = best;
            }
            double[][] nc = new double[k][3];
            // 循环处理
            for (int c = 0; c < k; c++) nc[c] = centroids[c].clone();
            // 循环处理
            for (int c = 0; c < k; c++) { int cnt = 0; double[] sum = new double[3]; for (int i = 0; i < n; i++) if (labels[i] == c) { cnt++; for (int j = 0; j < 3; j++) sum[j] += pts[i][j]; } if (cnt > 0) for (int j = 0; j < 3; j++) nc[c][j] = sum[j] / cnt; }
            double maxd = 0;
            // 循环处理
            for (int c = 0; c < k; c++) for (int j = 0; j < 3; j++) maxd = Math.max(maxd, Math.abs(nc[c][j] - centroids[c][j]));
            // 条件判断
            if (maxd < 1e-6) break;
            centroids = nc;
        }
        StringBuilder sb = new StringBuilder();
        // 枚举位置 i
        for (int i = 0; i < n; i++) { if (i > 0) sb.append((char)10); sb.append(labels[i]); }
        System.out.println(sb);
    }
}

