// 题目：流水线并行最优配置
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(C)，枚举一遍 PP 即可；空间 O(1)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    static String nextLine() throws IOException { return br.readLine(); }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String line = nextLine();
        List<String> toks = new ArrayList<>();
        // 条件判断
        if (line != null) {
            int i = 0; int L = line.length();
            // 循环处理
            while (i < L) {
                // 循环处理
                while (i < L && Character.isWhitespace(line.charAt(i))) i++;
                int st = i;
                // 循环处理
                while (i < L && !Character.isWhitespace(line.charAt(i))) i++;
                // 条件判断
                if (i > st) toks.add(line.substring(st, i));
            }
        }
        // 条件判断
        if (toks.size() != 4) { System.out.println("-1 -1"); return; }
        // 循环处理
        for (String t : toks) {
            // 条件判断
            if (t.isEmpty()) { System.out.println("-1 -1"); return; }
            // 枚举位置 i
            for (int i = 0; i < t.length(); i++) { char c = t.charAt(i); if (c < '0' || c > '9') { System.out.println("-1 -1"); return; } }
        }
        long layers = Long.parseLong(toks.get(0)), maxLoad = Long.parseLong(toks.get(1)), m = Long.parseLong(toks.get(2)), cards = Long.parseLong(toks.get(3));
        // 条件判断
        if (Math.min(Math.min(layers, maxLoad), Math.min(m, cards)) < 1) { System.out.println("-1 -1"); return; }
        long bestPp = -1;
        // 循环处理
        for (long pp = 1; pp <= cards; pp++) { if (layers % pp == 0 && layers / pp <= maxLoad) { bestPp = pp; break; } }
        // 条件判断
        if (bestPp == -1) { System.out.println("-1 -1"); return; }
        long num = (bestPp - 1) * 10000; long den = m + bestPp - 1;
        long q = num / den; long r = num % den;
        // 条件判断
        if (2 * r >= den) q += 1;
        String out = bestPp + " " + (q / 10000) + "." + String.format(Locale.US, "%04d", q % 10000);
        System.out.println(out);
    }
}

items.books/ai-exam/ai-2026/华为/020-频域特征信号聚类.md:
// 题目：频域特征信号聚类
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）
// 复杂度：时间 DFT 为 O(N L^2)，K-Means 每轮 O(N K) 最多 100 轮，总计 O(N L^2 + 100 N K)；空间 O(N L) 存信号和角度矩阵

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 核心方法：featureOf
    static int[] featureOf(double[] signal, int L) {
        int m = L / 2 - 1;
        int[] ks = new int[m];
        double[] mag = new double[m];
        // 循环处理
        for (int idx = 0; idx < m; idx++) {
            int kk = idx + 1; ks[idx] = kk;
            double re = 0, im = 0;
            // 循环处理
            for (int nn = 0; nn < L; nn++) { double ang = 2.0 * Math.PI * kk * nn / L; re += signal[nn] * Math.cos(ang); im += -signal[nn] * Math.sin(ang); }
            mag[idx] = Math.sqrt(re * re + im * im);
        }
        Integer[] ord = new Integer[m];
        // 枚举位置 i
        for (int i = 0; i < m; i++) ord[i] = i;
        final double[] mg = mag; final int[] kks = ks;
        Arrays.sort(ord, (a, b) -> { int c = Double.compare(mg[b], mg[a]); if (c != 0) return c; return Integer.compare(kks[a], kks[b]); });
        // 返回结果
        return new int[]{ks[ord[0]], ks[ord[1]], ks[ord[2]]};
    }
    // 核心方法：sq
    static long sq(int[] a, int[] b) { long s = 0; for (int t = 0; t < 3; t++) { long d = (long) a[t] - b[t]; s += d * d; } return s; }
    // 核心方法：bankerRound
    static long bankerRound(long num, long den) { long q = num / den; long r = num % den; long twice = 2 * r; if (twice < den) return q; if (twice > den) return q + 1; return (q % 2 == 0) ? q : q + 1; }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        int N = nextInt(), L = nextInt(), K = nextInt();
        double[][] signals = new double[N][L];
        // 枚举位置 i
        for (int i = 0; i < N; i++) for (int j = 0; j < L; j++) signals[i][j] = Double.parseDouble(next());
        int[] init = new int[K];
        // 枚举位置 i
        for (int i = 0; i < K; i++) init[i] = nextInt();
        int[][] features = new int[N][3];
        // 枚举位置 i
        for (int i = 0; i < N; i++) features[i] = featureOf(signals[i], L);
        int[][] centers = new int[K][3];
        // 循环处理
        for (int c = 0; c < K; c++) centers[c] = features[init[c]].clone();
        // 循环处理
        for (int iter = 0; iter < 100; iter++) {
            List<List<Integer>> clusters = new ArrayList<>();
            // 循环处理
            for (int c = 0; c < K; c++) clusters.add(new ArrayList<>());
            // 枚举位置 i
            for (int i = 0; i < N; i++) { int best = 0; long bd = Long.MAX_VALUE; for (int c = 0; c < K; c++) { long d = sq(features[i], centers[c]); if (d < bd) { bd = d; best = c; } } clusters.get(best).add(i); }
            int[][] nc = new int[K][3];
            // 循环处理
            for (int c = 0; c < K; c++) {
                List<Integer> cl = clusters.get(c);
                // 条件判断
                if (cl.isEmpty()) { nc[c] = centers[c].clone(); continue; }
                long cnt = cl.size();
                // 循环处理
                for (int t = 0; t < 3; t++) { long sum = 0; for (int idx : cl) sum += features[idx][t]; nc[c][t] = (int) bankerRound(sum, cnt); }
            }
            boolean same = true;
            // 循环处理
            for (int c = 0; c < K; c++) for (int t = 0; t < 3; t++) if (nc[c][t] != centers[c][t]) same = false;
            // 条件判断
            if (same) break;
            centers = nc;
        }
        int[][] sorted = centers.clone();
        Arrays.sort(sorted, (x, y) -> { if (x[0] != y[0]) return Integer.compare(x[0], y[0]); if (x[1] != y[1]) return Integer.compare(x[1], y[1]); return Integer.compare(x[2], y[2]); });
        StringBuilder sb = new StringBuilder();
        // 循环处理
        for (int c = 0; c < K; c++) { if (c > 0) sb.append((char)10); sb.append(sorted[c][0]).append(' ').append(sorted[c][1]).append(' ').append(sorted[c][2]); }
        System.out.println(sb);
    }
}

items.books/ai-exam/ai-2026/华为/021-动态旋转位置编码.md:
// 题目：动态旋转位置编码
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(D)，遍历 D/2 对维度；空间 O(D)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    // 核心方法：fmt
    static String fmt(double v) { String t = String.format(Locale.US, "%.4f", v); return t.equals("-0.0000") ? "0.0000" : t; }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        int T = nextInt(), L = nextInt(), D = nextInt();
        double b = Double.parseDouble(next());
        int m = nextInt();
        double[] x = new double[D];
        // 枚举位置 i
        for (int i = 0; i < D; i++) x[i] = Double.parseDouble(next());
        double s = Math.max(1.0, (double) T / L);
        double base = b * Math.pow(s, (double) D / (D - 2));
        double[] out = new double[D];
        // 枚举位置 i
        for (int i = 0; i < D / 2; i++) {
            double theta = m * Math.pow(base, -2.0 * i / D);
            double c = Math.cos(theta), sn = Math.sin(theta);
            int p = 2 * i;
            out[p] = x[p] * c - x[p + 1] * sn;
            out[p + 1] = x[p] * sn + x[p + 1] * c;
        }
        StringBuilder sb = new StringBuilder();
        // 枚举位置 i
        for (int i = 0; i < D; i++) { if (i > 0) sb.append(' '); sb.append(fmt(out[i])); }
        System.out.println(sb);
    }
}

