// 题目：最优分段常数量化
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(K N N)，每层分治 O(N N)，共 K 层；空间 O(N)，前缀和加滚动 DP 数组

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    static int N; static int K;
    static long[] a; static long[] pre; static long[] f; static long[] g;
    // 核心方法：cost
    static long cost(int l, int r) {
        int mid = (l + r) / 2;
        long rep = a[mid - 1];
        // 返回结果
        return rep * (mid - l + 1) - (pre[mid] - pre[l - 1]) + (pre[r] - pre[mid]) - rep * (r - mid);
    }
    // 核心方法：solve
    static void solve(int iL, int iR, int jL, int jR, int k) {
        // 条件判断
        if (iL > iR) return;
        int mid = (iL + iR) / 2;
        long best = Long.MAX_VALUE / 4;
        int bestj = Math.max(jL, k - 1);
        int lo = Math.max(jL, k - 1);
        int hi = Math.min(jR, mid - 1);
        // 枚举阶段 j
        for (int j = lo; j <= hi; j++) { long v = f[j] + cost(j + 1, mid); if (v < best) { best = v; bestj = j; } }
        g[mid] = best;
        solve(iL, mid - 1, jL, bestj, k);
        solve(mid + 1, iR, bestj, jR, k);
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        N = nextInt(); K = nextInt();
        a = new long[N];
        // 枚举位置 i
        for (int i = 0; i < N; i++) a[i] = nextLong();
        pre = new long[N + 1];
        // 枚举位置 i
        for (int i = 1; i <= N; i++) pre[i] = pre[i - 1] + a[i - 1];
        f = new long[N + 1];
        // 枚举位置 i
        for (int i = 1; i <= N; i++) f[i] = cost(1, i);
        int kUse = Math.min(K, N);
        // 循环处理
        for (int k = 2; k <= kUse; k++) {
            g = new long[N + 1];
            Arrays.fill(g, Long.MAX_VALUE / 4);
            solve(k, N, k - 1, N - 1, k);
            f = g;
        }
        System.out.println(f[N]);
    }
}

