// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(ND + N N)，计算全部距离 O(ND)，排序 O(N N)；空间 O(N)，存储 N 个二元组

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        int N = nextInt(), D = nextInt(), K = nextInt();
        long[] W = new long[D];
        long[] T = new long[D];
        // 枚举阶段 j
        for (int j = 0; j < D; j++) W[j] = nextLong();
        // 枚举阶段 j
        for (int j = 0; j < D; j++) T[j] = nextLong();
        long[][] arr = new long[N][2];
        // 枚举位置 i
        for (int i = 0; i < N; i++) {
            long iid = nextLong();
            long score = 0;
            // 枚举阶段 j
            for (int j = 0; j < D; j++) { long diff = T[j] - nextLong(); score += W[j] * diff * diff; }
            arr[i][0] = score; arr[i][1] = iid;
        }
        Integer[] idx = new Integer[N];
        // 枚举位置 i
        for (int i = 0; i < N; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> { if (arr[a][0] != arr[b][0]) return Long.compare(arr[a][0], arr[b][0]); return Long.compare(arr[a][1], arr[b][1]); });
        StringBuilder sb = new StringBuilder();
        // 循环处理
        for (int k = 0; k < K; k++) { if (k > 0) sb.append(' '); sb.append(arr[idx[k]][1]); }
