    }
}

items.books/ai-exam/ai-2026/华为/025-Agent-执行轨迹压:
// 题目：Agent 执行轨迹压缩
// 算法：BFS / 队列
// 模式：ACM（stdin/stdout）
// 复杂度：时间 模拟原轨迹为 O(K)；BFS 最多访问 n m2^t 个状态，每个状态扩展四个方向，总复杂度为 O(K+n m 2^t)；空间 访问标记和队列最多保存 O(n m 2^t) 个状态

import java.io.*;
import java.util.*;

public class Main {
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        int stepCount = sc.nextInt();
        int startRow = n / 2, startCol = m / 2;
        int row = startRow, col = startCol;
        Map<Integer,Integer> delta = new HashMap<>();
        Map<String,int[]> dirs = new HashMap<>();
        dirs.put("U", new int[]{-1, 0}); dirs.put("D", new int[]{1, 0}); dirs.put("L", new int[]{0, -1}); dirs.put("R", new int[]{0, 1});
        // 枚举位置 i
        for (int i = 0; i < stepCount; i++) {
            String move = sc.next(); String op = sc.next(); int param = sc.nextInt();
            int[] d = dirs.get(move);
            int nr = row + d[0], nc = col + d[1];
            // 条件判断
            if (nr >= 0 && nr < n && nc >= 0 && nc < m) { row = nr; col = nc; }
            // 条件判断
            if (op.equals("I")) { int key = row * m + col; delta.put(key, delta.getOrDefault(key, 0) + param); }
            else if (op.equals("D")) { int key = row * m + col; delta.put(key, delta.getOrDefault(key, 0) - param); }
        }
        int endId = row * m + col;
        List<Integer> targets = new ArrayList<>();
        // 循环处理
        for (Map.Entry<Integer,Integer> en : delta.entrySet()) if (en.getValue() != 0) targets.add(en.getKey());
        Map<Integer,Integer> targetIndex = new HashMap<>();
        // 枚举位置 i
        for (int i = 0; i < targets.size(); i++) targetIndex.put(targets.get(i), i);
        int stateCount = 1 << targets.size();
        int fullMask = stateCount - 1;
        int startId = startRow * m + startCol;
        boolean[][] visited = new boolean[n * m][stateCount];
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        visited[startId][0] = true;
        queue.add(new int[]{startId, 0});
        int distance = 0; int answer = -1;
        int[][] dirList = {{-1,0},{1,0},{0,-1},{0,1}};
        // 循环处理
        while (!queue.isEmpty()) {
            int size = queue.size();
            // 循环处理
            for (int q = 0; q < size; q++) {
                int[] cur = queue.poll();
                int cellId = cur[0], mask = cur[1];
                // 条件判断
                if (cellId == endId && mask == fullMask) { answer = distance; System.out.println(answer); return; }
                int cr = cellId / m, cc = cellId % m;
                // 循环处理
                for (int[] d : dirList) {
                    int nr = cr + d[0], nc = cc + d[1];
                    // 条件判断
                    if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                    int nextMask = mask;
                    Integer bi = targetIndex.get(nr * m + nc);
                    // 条件判断
                    if (bi != null) nextMask |= 1 << bi;
                    int nid = nr * m + nc;
                    // 条件判断
                    if (!visited[nid][nextMask]) { visited[nid][nextMask] = true; queue.add(new int[]{nid, nextMask}); }
                }
            }
            distance++;
        }
        System.out.println(-1);
    }
}

items.books/ai-exam/ai-2026/华为/026-KV-Cache-稀疏:
// 题目：KV Cache 稀疏化管理器
// 算法：堆 / 优先队列
// 模式：ACM（stdin/stdout）
// 复杂度：时间 每次 ADD 和淘汰均为 O( K)，每次 QUERY 为 O(M)，总时间复杂度为 O(N K+S)；空间 字典、最小堆与单次查询的输出缓冲区均为 O(K)

import java.io.*;
import java.math.BigDecimal;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static String nextLine() throws IOException { return br.readLine(); }
    static final char NL = (char) 10;
    static class Entry {
        BigDecimal score;
        int pos;
        Entry(BigDecimal score, int pos) {
            this.score = score;
            this.pos = pos;
        }
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        StringBuilder sb = new StringBuilder();
        String first = nextLine();
        // 条件判断
        if (first == null) return;
        st = new StringTokenizer(first);
        int capacity = nextInt();
        int operationCount = nextInt();
        LinkedHashMap<Integer, String[]> cache = new LinkedHashMap<>();
        PriorityQueue<Entry> heap = new PriorityQueue<>(new Comparator<Entry>() {
            public int compare(Entry a, Entry b) {
                int c = a.score.compareTo(b.score);
                // 条件判断
                if (c != 0) return c;
                // 返回结果
                return Integer.compare(a.pos, b.pos);
            }
        });
        // 循环处理
        for (int op = 0; op < operationCount; op++) {
            String line = nextLine();
            // 条件判断
            if (line == null) break;
            st = new StringTokenizer(line);
            // 条件判断
            if (!st.hasMoreTokens()) continue;
            String command = next();
            // 条件判断
            if (command.equals("ADD")) {
                int pos = nextInt();
                String scoreText = next();
                String keyText = nextLine();
                String valueText = nextLine();
                // 条件判断
                if (keyText == null) keyText = "";
                // 条件判断
                if (valueText == null) valueText = "";
                cache.put(pos, new String[]{scoreText, keyText, valueText});
                heap.add(new Entry(new BigDecimal(scoreText), pos));
                // 条件判断
                if (cache.size() > capacity) {
                    Entry pruned = heap.poll();
                    int prunedPos = pruned.pos;
                    cache.remove(prunedPos);
                    sb.append("PRUNED ").append(prunedPos).append(NL);
                }
            } else {
                sb.append(cache.size()).append(NL);
                // 循环处理
                for (Map.Entry<Integer, String[]> e : cache.entrySet()) {
                    String[] v = e.getValue();
                    sb.append(e.getKey()).append(' ').append(v[0]).append(NL);
                    sb.append(v[1]).append(NL);
                    sb.append(v[2]).append(NL);
                }
            }
        }
        System.out.print(sb);
    }
}

