// 题目：MoE 动态路由
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）
// 复杂度：时间 完整排序方案中，每个 token 对 E 个专家排序，复杂度为 O(NE E)；容量模拟为 O(NK)；空间 除输入的一行分数和排序结果外，只维护负载数组，额外空间复杂度为 O(E)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    static final char NL = (char) 10;

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String t = next();
        // 条件判断
        if (t == null) return;
        int n = Integer.parseInt(t);
        int expertCount = nextInt();
        int topK = nextInt();
        int capacity = nextInt();
        long[] loads = new long[expertCount];
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            final int[] scores = new int[expertCount];
            // 循环处理
            for (int e = 0; e < expertCount; e++) scores[e] = nextInt();
            Integer[] experts = new Integer[expertCount];
            // 循环处理
            for (int e = 0; e < expertCount; e++) experts[e] = e;
            Arrays.sort(experts, new Comparator<Integer>() {
                public int compare(Integer a, Integer b) {
                    // 条件判断
                    if (scores[a] != scores[b]) return Integer.compare(scores[b], scores[a]);
                    // 返回结果
                    return Integer.compare(a, b);
                }
            });
            int limit = Math.min(topK, expertCount);
            // 循环处理
            for (int k = 0; k < limit; k++) {
                int e = experts[k];
                // 条件判断
                if (loads[e] < capacity) loads[e]++;
            }
        }
        long penalty = 0;
        // 循环处理
        for (long l : loads) penalty += l * l;
        StringBuilder sb = new StringBuilder();
        sb.append(penalty).append(NL);
        // 循环处理
        for (int e = 0; e < expertCount; e++) {
            // 条件判断
            if (e > 0) sb.append(' ');
            sb.append(loads[e]);
        }
        sb.append(NL);
        System.out.print(sb);
    }
}

items.books/ai-exam/ai-2026/华为/028-流水线连续划分.md:
// 题目：流水线连续划分
// 算法：动态规划（前缀和 + 滚动数组）
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(pn n)；空间 滚动数组、前缀和与最小堆均为 O(n)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    // 核心方法：lowerBound
    static int lowerBound(long[] arr, long target, int from, int to) {
        int lo = from;
        int hi = to;
        // 循环处理
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            // 条件判断
            if (arr[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        // 返回结果
        return lo;
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String t = next();
        // 条件判断
        if (t == null) return;
        int n = Integer.parseInt(t);
        int stageCount = nextInt();
        long limit = nextLong();
        long[] times = new long[n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) times[i] = nextLong();
        long[] comm = new long[Math.max(n - 1, 0)];
        // 条件判断
        if (n > 1) {
            // 枚举位置 i
            for (int i = 0; i < n - 1; i++) comm[i] = nextLong();
        }
        long maxTime = 0;
        // 循环处理
        for (long v : times) maxTime = Math.max(maxTime, v);
        // 条件判断
        if (maxTime > limit) {
            System.out.println(-1);
            // 返回结果
            return;
        }
        long[] prefix = new long[n + 1];
        // 枚举位置 i
        for (int i = 1; i <= n; i++) prefix[i] = prefix[i - 1] + times[i - 1];
        final long INF = (long) 1e18;
        long[] dpPrev = new long[n + 1];
        Arrays.fill(dpPrev, INF);
        // 枚举位置 i
        for (int i = 1; i <= n; i++) {
            // 条件判断
            if (prefix[i] <= limit) dpPrev[i] = 0;
        }
        // 循环处理
        for (int stages = 2; stages <= stageCount; stages++) {
            long[] dpCur = new long[n + 1];
            Arrays.fill(dpCur, INF);
            PriorityQueue<long[]> heap = new PriorityQueue<>(new Comparator<long[]>() {
                public int compare(long[] a, long[] b) {
                    // 条件判断
                    if (a[0] != b[0]) return Long.compare(a[0], b[0]);
                    // 返回结果
                    return Long.compare(a[1], b[1]);
                }
            });
            // 枚举位置 i
            for (int i = stages; i <= n; i++) {
                int k = i - 1;
                // 条件判断
                if (dpPrev[k] < INF) {
                    long candidateCost = dpPrev[k] + comm[k - 1];
                    heap.add(new long[]{candidateCost, k});
                }
                int lower = lowerBound(prefix, prefix[i] - limit, 0, i);
                // 循环处理
                while (!heap.isEmpty() && heap.peek()[1] < lower) heap.poll();
                // 条件判断
                if (!heap.isEmpty()) dpCur[i] = heap.peek()[0];
            }
            dpPrev = dpCur;
        }
        long answer = dpPrev[n];
        System.out.println(answer == INF ? -1 : answer);
    }
}

// 题目：基站空间重叠区域识别
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(N^2)；空间 O(N)，用于保存坐标、邻域计数、核心点标记和答案

import java.io.*;
import java.util.*;

public class Main {
    static final char NL = (char) 10;

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        String t = sc.next();
        // 条件判断
        if (t == null) return;
        int n = Integer.parseInt(t);
        long eps = sc.nextLong();
        int minPts = sc.nextInt();
        long[] xs = new long[n];
        long[] ys = new long[n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            xs[i] = sc.nextLong();
            ys[i] = sc.nextLong();
        }
        long[] count = new long[n];
        Arrays.fill(count, 1);
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            // 枚举阶段 j
            for (int j = i + 1; j < n; j++) {
                // 条件判断
                if (Math.abs(xs[i] - xs[j]) + Math.abs(ys[i] - ys[j]) <= eps) {
                    count[i]++;
                    count[j]++;
                }
            }
        }
        boolean[] isCore = new boolean[n];
        List<Integer> coreIndices = new ArrayList<>();
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            isCore[i] = count[i] >= minPts;
            // 条件判断
            if (isCore[i]) coreIndices.add(i);
        }
        int[] answer = new int[n];
        Arrays.fill(answer, 2);
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            // 条件判断
            if (isCore[i]) {
                answer[i] = 0;
                continue;
            }
            // 枚举阶段 j
            for (int j : coreIndices) {
                // 条件判断
                if (Math.abs(xs[i] - xs[j]) + Math.abs(ys[i] - ys[j]) <= eps) {
                    answer[i] = 1;
                    break;
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            // 条件判断
            if (i > 0) sb.append(NL);
            sb.append(answer[i]);
        }
        System.out.print(sb);
    }
}

