// 题目：多 Agent 协作任务调度
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(100N)；空间 O(N)，用于保存所有 p_i,c_i；DP 数组长度固定为 100

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String t = next();
        // 条件判断
        if (t == null) return;
        int n = Integer.parseInt(t);
        long[] progress = new long[n];
        long[] cost = new long[n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            progress[i] = nextLong();
            cost[i] = nextLong();
        }
        long INF = Long.MAX_VALUE / 4;
        long[] best = new long[100];
        long[] second = new long[100];
        int[] bestLast = new int[100];
        Arrays.fill(best, INF);
        Arrays.fill(second, INF);
        Arrays.fill(bestLast, -1);
        best[0] = 0;
        second[0] = 0;
        long answer = INF;
        // 循环处理
        for (int current = 0; current < 100; current++) {
            // 条件判断
            if (best[current] == INF) continue;
            // 循环处理
            for (int agent = 0; agent < n; agent++) {
                long base;
                // 条件判断
                if (agent == bestLast[current]) base = second[current];
                else base = best[current];
                // 条件判断
                if (base == INF) continue;
                long newCost = base + cost[agent];
                long nextProgress = current + progress[agent];
                // 条件判断
                if (nextProgress >= 100) {
                    answer = Math.min(answer, newCost);
                    continue;
                }
                int np = (int) nextProgress;
                // 条件判断
                if (newCost < best[np]) {
                    // 条件判断
                    if (bestLast[np] == agent) {
                        best[np] = newCost;
                    } else {
                        second[np] = best[np];
                        best[np] = newCost;
                        bestLast[np] = agent;
                    }
                } else if (bestLast[np] != agent && newCost < second[np]) {
                    second[np] = newCost;
                }
            }
        }
        System.out.println(answer == INF ? -1 : answer);
    }
}

items.books/ai-exam/ai-2026/华为/031-FlashAttent:
// 题目：FlashAttention 分块合并
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(B)； 每次更新或查询时间复杂度 ：O( B)； 空间复杂度 ：O(B)；空间 O(B)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    static final char NL = (char) 10;
    // 核心方法：merge
    static double[] merge(double[] left, double[] right) {
        // 条件判断
        if (left == null) return right;
        // 条件判断
        if (right == null) return left;
        double maximum = Math.max(left[0], right[0]);
        double ls = Math.exp(left[0] - maximum);
        double rs = Math.exp(right[0] - maximum);
        // 返回结果
        return new double[]{maximum, left[1] * ls + right[1] * rs, left[2] * ls + right[2] * rs};
    }

    // 核心方法：query
    static double[] query(double[][] tree, int size, int left, int right) {
        left += size;
        right += size;
        double[] lr = null;
        double[] rr = null;
        // 循环处理
        while (left < right) {
            // 条件判断
            if ((left & 1) == 1) {
                lr = merge(lr, tree[left]);
                left++;
            }
            // 条件判断
            if ((right & 1) == 1) {
                right--;
                rr = merge(tree[right], rr);
            }
            left >>= 1;
            right >>= 1;
        }
        // 返回结果
        return merge(lr, rr);
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String t = next();
        // 条件判断
        if (t == null) return;
        int blockCount = Integer.parseInt(t);
        int queryCount = nextInt();
        double[][] blocks = new double[blockCount][];
        // 枚举位置 i
        for (int i = 0; i < blockCount; i++) {
            blocks[i] = new double[]{Double.parseDouble(next()), Double.parseDouble(next()), Double.parseDouble(next())};
        }
        int size = 1;
        // 循环处理
        while (size < blockCount) size <<= 1;
        double[][] tree = new double[2 * size][];
        // 枚举位置 i
        for (int i = 0; i < blockCount; i++) tree[size + i] = blocks[i];
        // 枚举位置 i
        for (int i = size - 1; i >= 1; i--) tree[i] = merge(tree[2 * i], tree[2 * i + 1]);
        StringBuilder sb = new StringBuilder();
        boolean firstOut = true;
        // 循环处理
        for (int q = 0; q < queryCount; q++) {
            String op = next();
            // 条件判断
            if (op.equals("1")) {
                int position = nextInt() - 1;
                double m = Double.parseDouble(next());
                double d = Double.parseDouble(next());
                double v = Double.parseDouble(next());
                int idx = size + position;
                tree[idx] = new double[]{m, d, v};
                idx >>= 1;
                // 循环处理
                while (idx >= 1) {
                    tree[idx] = merge(tree[2 * idx], tree[2 * idx + 1]);
                    idx >>= 1;
                }
            } else {
                int left = nextInt() - 1;
                int right = nextInt();
                double[] res = query(tree, size, left, right);
                double denom = res[1];
                double numer = res[2];
                // 条件判断
                if (!firstOut) sb.append(NL);
                firstOut = false;
                sb.append(String.format(Locale.US, "%.6f", numer / denom));
            }
        }
        System.out.print(sb);
    }
}

