// 题目：流水线并行最小瓶颈
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(n W)； 空间复杂度 ：除输入数组外为 O(1)；空间 除输入数组外为 O(1)

import java.io.*;
import java.util.*;

public class Main {
    // 核心方法：feasible
    static boolean feasible(long[] weights, long cap, int k) {
        int segments = 1;
        long current = 0;
        // 循环处理
        for (long w : weights) {
            // 条件判断
            if (current + w <= cap) {
                current += w;
            } else {
                segments++;
                current = w;
                // 条件判断
                if (segments > k) return false;
            }
        }
        // 返回结果
        return true;
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        String t = sc.next();
        // 条件判断
        if (t == null) return;
        int n = Integer.parseInt(t);
        long[] weights = new long[n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) weights[i] = sc.nextLong();
        int k = sc.nextInt();
        long left = 0;
        long right = 0;
        // 循环处理
        for (long w : weights) {
            left = Math.max(left, w);
            right += w;
        }
        // 循环处理
        while (left < right) {
            long mid = (left + right) / 2;
            // 条件判断
            if (feasible(weights, mid, k)) right = mid;
            else left = mid + 1;
        }
        System.out.println(left);
    }
}

// 题目：全整型量化的矩阵乘法
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 量化 B 需要 O(nk+31n)，全部整数点积需要 O(mnk)，总时间复杂度为 O(mnk)；空间 保存量化后的 A 与 B 需要 O(mk+nk)；逐行生成输出时，除输入存储外的输出暂存为 O(n)

import java.io.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;

public class Main {
    static final char NL = (char) 10;
    static final int QMAX = 127;
    static final int MAX_B = 30;

    static class Fraction {
        BigInteger num;
        BigInteger den;
        Fraction(BigInteger n, BigInteger d) {
            // 条件判断
            if (d.signum() < 0) {
                n = n.negate();
                d = d.negate();
            }
            BigInteger g = n.gcd(d);
            // 条件判断
            if (g.signum() != 0) {
                n = n.divide(g);
                d = d.divide(g);
            }
            num = n;
            den = d;
        }
        int compareTo(Fraction o) {
            // 返回结果
            return num.multiply(o.den).compareTo(o.num.multiply(den));
        }
    }

    // 核心方法：parseFraction
    static Fraction parseFraction(String s) {
        BigDecimal bd = new BigDecimal(s.trim());
        BigInteger unscaled = bd.unscaledValue();
        int scale = bd.scale();
        BigInteger num;
        BigInteger den;
        // 条件判断
        if (scale >= 0) {
            num = unscaled;
            den = BigInteger.TEN.pow(scale);
        } else {
            num = unscaled.multiply(BigInteger.TEN.pow(-scale));
            den = BigInteger.ONE;
        }
        // 返回结果
        return new Fraction(num, den);
    }

    // 核心方法：divide
    static Fraction divide(Fraction a, Fraction b) {
        // 返回结果
        return new Fraction(a.num.multiply(b.den), a.den.multiply(b.num));
    }

    // 核心方法：roundHalfAway
    static BigInteger roundHalfAway(Fraction f) {
        BigInteger n = f.num;
        BigInteger d = f.den;
        boolean neg = n.signum() < 0;
        BigInteger absN = n.abs();
        BigInteger[] qr = absN.divideAndRemainder(d);
        BigInteger q = qr[0];
        // 条件判断
        if (qr[1].shiftLeft(1).compareTo(d) >= 0) {
            q = q.add(BigInteger.ONE);
        }
        // 返回结果
        return neg ? q.negate() : q;
    }

    static class ColumnResult {
        long[] quantized;
        long a;
        long b;
        ColumnResult(long[] quantized, long a, long b) {
            this.quantized = quantized;
            this.a = a;
            this.b = b;
        }
    }

    // 核心方法：quantizeColumn
    static ColumnResult quantizeColumn(String[] tokens) {
        int len = tokens.length;
        Fraction[] column = new Fraction[len];
        // 枚举位置 i
        for (int i = 0; i < len; i++) column[i] = parseFraction(tokens[i]);
        Fraction maximum = null;
        // 循环处理
        for (Fraction f : column) {
            Fraction abs = new Fraction(f.num.abs(), f.den);
            // 条件判断
            if (maximum == null || abs.compareTo(maximum) > 0) maximum = abs;
        }
        // 条件判断
        if (maximum.num.signum() == 0) {
            long[] zeros = new long[len];
            // 返回结果
            return new ColumnResult(zeros, 0, MAX_B);
        }
        Fraction scale = new Fraction(maximum.num, maximum.den.multiply(BigInteger.valueOf(QMAX)));
        long[] quantized = new long[len];
        // 枚举位置 i
        for (int i = 0; i < len; i++) {
            quantized[i] = roundHalfAway(divide(column[i], scale)).longValue();
        }
        Long chosenB = null;
        Long chosenA = null;
        // 枚举分割点 b
        for (int b = MAX_B; b >= 0; b--) {
            Fraction scaled = new Fraction(scale.num.shiftLeft(b), scale.den);
            BigInteger av = roundHalfAway(scaled);
            // 条件判断
            if (av.signum() >= 0 && av.compareTo(BigInteger.valueOf(QMAX)) <= 0) {
                chosenB = (long) b;
                chosenA = av.longValue();
                break;
            }
        }
        // 条件判断
        if (chosenB == null) throw new RuntimeException("unrepresentable");
        // 返回结果
        return new ColumnResult(quantized, chosenA, chosenB);
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        String t = sc.next();
        // 条件判断
        if (t == null) return;
        int m = Integer.parseInt(t);
        int k = sc.nextInt();
        int n = sc.nextInt();
        long[][] qa = new long[m][k];
        long[] aa = new long[m];
        long[] ba = new long[m];
        // 枚举位置 i
        for (int i = 0; i < m; i++) {
            // 枚举阶段 j
            for (int j = 0; j < k; j++) qa[i][j] = sc.nextInt();
            aa[i] = sc.nextInt();
            ba[i] = sc.nextInt();
        }
        ColumnResult[] cols = new ColumnResult[n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            String[] toks = new String[k];
            // 枚举阶段 j
            for (int j = 0; j < k; j++) toks[j] = sc.next();
            cols[i] = quantizeColumn(toks);
        }
        StringBuilder sb = new StringBuilder();
        // 枚举位置 i
        for (int i = 0; i < m; i++) {
            StringBuilder line = new StringBuilder();
            boolean first = true;
            // 枚举阶段 j
            for (int j = 0; j < n; j++) {
                ColumnResult col = cols[j];
                long qc = 0;
                // 循环处理
                for (int x = 0; x < k; x++) qc += qa[i][x] * col.quantized[x];
                long ab = aa[i] * col.a;
                long bb = ba[i] + col.b;
                // 条件判断
                if (!first) line.append(' ');
                first = false;
                line.append(qc).append(' ').append(ab).append(' ').append(bb);
            }
            // 条件判断
            if (i > 0) sb.append(NL);
            sb.append(line);
        }
        System.out.print(sb);
    }
}

items.books/ai-exam/ai-2026/华为/034-滑动窗口注意力机制.m:
// 题目：滑动窗口注意力机制
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O!(BN(N,2+1)d_k)，其中 B 为 batch_size；空间 输入矩阵和当前组输出计算占 O(Nd_k)，单行分数与权重占 O((N,2+1))；不构造 N^2 注意力矩阵

import java.io.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class Main {
    static final char NL = (char) 10;
    // 核心方法：formatTwoDigits
    static String formatTwoDigits(double x) {
        BigDecimal value = BigDecimal.valueOf(x).setScale(2, RoundingMode.HALF_UP);
        // 条件判断
        if (value.compareTo(BigDecimal.ZERO) == 0) value = new BigDecimal("0.00");
        // 返回结果
        return value.toPlainString();
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        String t = sc.next();
        // 条件判断
        if (t == null) return;
        int batchSize = Integer.parseInt(t);
        int n = sc.nextInt();
        int d = sc.nextInt();
        int window = sc.nextInt();
        // 条件判断
        if (batchSize < 1 || n < 1 || d < 1 || !(window >= 1 && window <= n)) {
            System.out.println(0);
            // 返回结果
            return;
        }
        double scale = Math.sqrt(d);
        StringBuilder sb = new StringBuilder();
        boolean firstLine = true;
        // 循环处理
        for (int bi = 0; bi < batchSize; bi++) {
            double[][] q = new double[n][d];
            double[][] kk = new double[n][d];
            double[][] v = new double[n][d];
            // 枚举位置 i
            for (int i = 0; i < n; i++) for (int j = 0; j < d; j++) q[i][j] = Double.parseDouble(sc.next());
            // 枚举位置 i
            for (int i = 0; i < n; i++) for (int j = 0; j < d; j++) kk[i][j] = Double.parseDouble(sc.next());
            // 枚举位置 i
            for (int i = 0; i < n; i++) for (int j = 0; j < d; j++) v[i][j] = Double.parseDouble(sc.next());
            // 条件判断
            if (bi > 0) sb.append(NL);
            // 枚举位置 i
            for (int i = 0; i < n; i++) {
                int left = Math.max(0, i - window);
                int right = Math.min(n, i + window + 1);
                int len = right - left;
                double[] scores = new double[len];
                double maximum = Double.NEGATIVE_INFINITY;
                // 枚举阶段 j
                for (int j = left; j < right; j++) {
                    double dot = 0.0;
                    // 循环处理
                    for (int tt = 0; tt < d; tt++) dot += q[i][tt] * kk[j][tt];
                    scores[j - left] = dot / scale;
                    // 条件判断
                    if (scores[j - left] > maximum) maximum = scores[j - left];
                }
                double[] exps = new double[len];
                double denom = 0.0;
                // 枚举阶段 j
                for (int j = 0; j < len; j++) {
                    exps[j] = Math.exp(scores[j] - maximum);
                    denom += exps[j];
                }
                // 条件判断
                if (!firstLine) sb.append(NL);
                firstLine = false;
                StringBuilder row = new StringBuilder();
                // 循环处理
                for (int tt = 0; tt < d; tt++) {
                    double numerator = 0.0;
                    // 枚举阶段 j
                    for (int j = left; j < right; j++) numerator += exps[j - left] * v[j][tt];
                    double val = numerator / denom;
                    // 条件判断
                    if (tt > 0) row.append(' ');
                    row.append(formatTwoDigits(val));
                }
                sb.append(row);
            }
        }
        System.out.print(sb);
    }
}

items.books/ai-exam/ai-2026/华为/035-时间序列数据清洗与特征:
// 题目：时间序列数据清洗与特征评分
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(n n)；插值、建块、标准化和评分为 O(n)，n 个窗口查询各为 O( n)；空间 O(n)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    // 核心方法：isqrt
    static int isqrt(int n) {
        int r = (int) Math.sqrt((double) n);
        // 循环处理
        while ((long) (r + 1) * (r + 1) <= n) r++;
        // 循环处理
        while ((long) r * r > n) r--;
        // 返回结果
        return r;
    }

    // 核心方法：mergeStats
    static double[] mergeStats(double[] a, double[] b) {
        double na = a[0], ma = a[1], m2a = a[2];
        double nb = b[0], mb = b[1], m2b = b[2];
        // 条件判断
        if (na == 0) return b;
        // 条件判断
        if (nb == 0) return a;
        double delta = mb - ma;
        double n = na + nb;
        double mean = ma + delta * nb / n;
        double m2 = m2a + m2b + delta * delta * na * nb / n;
        // 返回结果
        return new double[]{n, mean, m2};
    }

    // 核心方法：addValue
    static double[] addValue(double[] stat, double x) {
        double n = stat[0];
        double mean = stat[1];
        double m2 = stat[2];
        double n2 = n + 1;
        double delta = x - mean;
        double mean2 = mean + delta / n2;
        // 返回结果
        return new double[]{n2, mean2, m2 + delta * (x - mean2)};
    }

    // 核心方法：cleanValues
    static double[] cleanValues(int[] ts, int[] raw, int[] quality) {
        int n = raw.length;
        int[] previous = new int[n];
        int[] following = new int[n];
        int last = -1;
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            previous[i] = last;
            // 条件判断
            if (quality[i] == 0) last = i;
        }
        last = -1;
        // 枚举位置 i
        for (int i = n - 1; i >= 0; i--) {
            following[i] = last;
            // 条件判断
            if (quality[i] == 0) last = i;
        }
        double[] values = new double[n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) values[i] = (double) raw[i];
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            // 条件判断
            if (quality[i] != 2) continue;
            int left = previous[i];
            int right = following[i];
            // 条件判断
            if (left != -1 && right != -1) {
                double ratio = (double) (ts[i] - ts[left]) / (ts[right] - ts[left]);
                values[i] = raw[left] + (raw[right] - raw[left]) * ratio;
            } else if (left != -1) {
                values[i] = (double) raw[left];
            } else if (right != -1) {
                values[i] = (double) raw[right];
            }
        }
        // 返回结果
        return values;
    }

    // 核心方法：rangeStats
    static double[] rangeStats(double[] values, double[][] blockStats, int blockSize, int left, int right) {
        double[] stat = new double[]{0, 0.0, 0.0};
        // 循环处理
        while (left <= right && left % blockSize != 0) {
            stat = addValue(stat, values[left]);
            left++;
        }
        // 循环处理
        while (left + blockSize - 1 <= right) {
            stat = mergeStats(stat, blockStats[left / blockSize]);
            left += blockSize;
        }
        // 循环处理
        while (left <= right) {
            stat = addValue(stat, values[left]);
            left++;
        }
        // 返回结果
        return stat;
    }

    // 核心方法：smoothValues
    static double[] smoothValues(double[] values, int window, double threshold) {
        int n = values.length;
        int blockSize = Math.max(1, isqrt(n));
        int blockCount = (n + blockSize - 1) / blockSize;
        double[][] blockStats = new double[blockCount][];
        // 循环处理
        for (int s = 0; s < n; s += blockSize) {
            double[] stat = new double[]{0, 0.0, 0.0};
            // 枚举位置 i
            for (int i = s; i < Math.min(n, s + blockSize); i++) stat = addValue(stat, values[i]);
            blockStats[s / blockSize] = stat;
        }
        int half = (window - 1) / 2;
        double[] result = values.clone();
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            int left = Math.max(0, i - half);
            int right = Math.min(n - 1, i + half);
            double[] st = rangeStats(values, blockStats, blockSize, left, right);
            double count = st[0];
            double mean = st[1];
            double m2 = st[2];
            double variance = Math.max(0.0, m2 / count);
            // 条件判断
            if (Math.abs(values[i] - mean) > threshold * Math.sqrt(variance)) {
                result[i] = mean;
            }
        }
        // 返回结果
        return result;
    }

    // 核心方法：score
    static long score(double[] values, int[] quality) {
        double[] stat = new double[]{0, 0.0, 0.0};
        // 循环处理
        for (double x : values) stat = addValue(stat, x);
        double n = stat[0];
        double mean = stat[1];
        double m2 = stat[2];
        double sd = Math.sqrt(Math.max(0.0, m2 / n));
        double[] qw = new double[]{1.0, 0.5, 0.25};
        double denominator = 0.0;
        // 枚举位置 i
        for (int i = 0; i < values.length; i++) denominator += qw[quality[i]] * Math.abs(values[i]);
        // 条件判断
        if (denominator == 0.0 || sd == 0.0) return 0;
        double total = 0.0;
        // 枚举位置 i
        for (int i = 0; i < values.length; i++) {
            double weight = qw[quality[i]] * Math.abs(values[i]) / denominator;
            total += weight * Math.abs((values[i] - mean) / sd);
        }
        // 返回结果
        return (long) Math.floor(total * 100 + 0.5);
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String t = next();
        // 条件判断
        if (t == null) return;
        int n = Integer.parseInt(t);
        int window = nextInt();
        int threshold = nextInt();
        int[] ts = new int[n];
        int[] raw = new int[n];
        int[] quality = new int[n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            ts[i] = nextInt();
            raw[i] = nextInt();
            quality[i] = nextInt();
        }
        double[] cleaned = cleanValues(ts, raw, quality);
        double[] smoothed = smoothValues(cleaned, window, (double) threshold);
        System.out.println(score(smoothed, quality));
    }
}

// 题目：模型训练任务资源分配
// 算法：动态规划
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(nC)；空间 O(C)

import java.io.*;
import java.util.*;

public class Main {
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        String t = sc.next();
        // 条件判断
        if (t == null) return;
        int n = Integer.parseInt(t);
        int capacity = sc.nextInt();
        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[capacity + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            long c1 = sc.nextLong();
            long t1 = sc.nextLong();
            long c2 = sc.nextLong();
            long t2 = sc.nextLong();
            long[] next = new long[capacity + 1];
            Arrays.fill(next, INF);
            // 循环处理
            for (int used = 0; used <= capacity; used++) {
                long cur = dp[used];
                // 条件判断
                if (cur == INF) continue;
                // 条件判断
                if (used + c1 <= capacity) {
                    int idx = (int) (used + c1);
                    next[idx] = Math.min(next[idx], cur + t1);
                }
                // 条件判断
                if (used + c2 <= capacity) {
                    int idx = (int) (used + c2);
                    next[idx] = Math.min(next[idx], cur + t2);
                }
            }
            dp = next;
        }
        long bestTime = INF;
        // 循环处理
        for (long v : dp) bestTime = Math.min(bestTime, v);
        int bestCost = 0;
        // 枚举位置 i
        for (int i = 0; i <= capacity; i++) {
            // 条件判断
            if (dp[i] == bestTime) {
                bestCost = i;
                break;
            }
        }
        StringBuilder sb = new StringBuilder();
        sb.append(bestTime).append(' ').append(bestCost).append(' ').append(capacity - bestCost);
        System.out.println(sb);
    }
}

// 题目：CDN分发服务器选址
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(Tp²+q log q)，T 为到固定点或重复配置前的轮数，不预设为常数；空间 O(p+Tq)，包含城市、分簇及用于循环检测的中心历史

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static String nextLine() throws IOException { return br.readLine(); }
    static final char NL = (char) 10;
    static final double EPS = 1e-9;

    // 核心方法：dist
    static double dist(double[] a, double[] b) {
        // 返回结果
        return Math.sqrt((a[0] - b[0]) * (a[0] - b[0]) + (a[1] - b[1]) * (a[1] - b[1]));
    }

    // 核心方法：assign
    static List<List<Integer>> assign(double[][] cs, int[] centers) {
        int m = centers.length;
        List<List<Integer>> cluster = new ArrayList<>();
        // 枚举阶段 j
        for (int j = 0; j < m; j++) cluster.add(new ArrayList<Integer>());
        // 枚举位置 i
        for (int i = 0; i < cs.length; i++) {
            int bestJ = 0;
            double bestD = dist(cs[i], cs[centers[0]]);
            // 枚举阶段 j
            for (int j = 1; j < m; j++) {
                double d = dist(cs[i], cs[centers[j]]);
                // 条件判断
                if (d < bestD - EPS) {
                    bestD = d;
                    bestJ = j;
                }
            }
            cluster.get(bestJ).add(i);
        }
        // 返回结果
        return cluster;
    }

    // 核心方法：relocate
    static int[] relocate(double[][] cs, int[] centers, List<List<Integer>> cluster) {
        int m = centers.length;
        int[] nxt = centers.clone();
        // 枚举阶段 j
        for (int j = 0; j < m; j++) {
            List<Integer> mem = cluster.get(j);
            // 条件判断
            if (mem.isEmpty()) continue;
            int bestC = -1;
            double bestCost = 0.0;
            // 循环处理
            for (int ci = 0; ci < mem.size(); ci++) {
                int c = mem.get(ci);
                double cost = 0.0;
                // 循环处理
                for (int ii = 0; ii < mem.size(); ii++) {
                    int i = mem.get(ii);
                    cost += cs[i][2] * dist(cs[i], cs[c]);
                }
                // 条件判断
                if (bestC < 0 || cost < bestCost - EPS) {
                    bestCost = cost;
                    bestC = c;
                }
            }
            nxt[j] = bestC;
        }
        // 返回结果
        return nxt;
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String line = nextLine();
        // 条件判断
        if (line == null) return;
        int p = Integer.parseInt(line.trim());
        double[][] cs = new double[p][3];
        // 枚举位置 i
        for (int i = 0; i < p; i++) {
            String[] parts = nextLine().trim().split(",");
            cs[i][0] = Double.parseDouble(parts[0]);
            cs[i][1] = Double.parseDouble(parts[1]);
            cs[i][2] = Double.parseDouble(parts[2]);
        }
        int q = Integer.parseInt(nextLine().trim());
        int[] centers = new int[q];
        // 枚举位置 i
        for (int i = 0; i < q; i++) centers[i] = i;
        List<List<Integer>> cluster = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        // 循环处理
        while (true) {
            String key = Arrays.toString(centers);
            // 条件判断
            if (seen.contains(key)) throw new RuntimeException();
            seen.add(key);
            cluster = assign(cs, centers);
            int[] nxt = relocate(cs, centers, cluster);
            // 条件判断
            if (Arrays.equals(nxt, centers)) {
                centers = nxt;
                break;
            }
            centers = nxt;
        }
        double[][] rows = new double[q][3];
        // 枚举阶段 j
        for (int j = 0; j < q; j++) {
            double cov = 0.0;
            // 枚举位置 i
            for (int i : cluster.get(j)) cov += cs[i][2];
            rows[j][0] = cs[centers[j]][0];
            rows[j][1] = cs[centers[j]][1];
            rows[j][2] = cov;
        }
        Arrays.sort(rows, new Comparator<double[]>() {
            public int compare(double[] a, double[] b) {
                int c = Double.compare(a[0], b[0]);
                // 条件判断
                if (c != 0) return c;
                // 返回结果
                return Double.compare(a[1], b[1]);
            }
        });
        StringBuilder sb = new StringBuilder();
        // 枚举位置 i
        for (int i = 0; i < rows.length; i++) {
            // 条件判断
            if (i > 0) sb.append(NL);
            sb.append(String.format(Locale.US, "%.2f,%.2f,%.2f", rows[i][0], rows[i][1], rows[i][2]));
        }
        System.out.print(sb);
    }
}

// 题目：动态KV缓存稀疏优化
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {
    static final char NL = (char) 10;

    static class Candidate {
        double negScore;
        int l;
        int h;
        int t;
        Candidate(double negScore, int l, int h, int t) {
            this.negScore = negScore;
            this.l = l;
            this.h = h;
            this.t = t;
        }
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        String first = sc.next();
        // 条件判断
        if (first == null) return;
        int L = Integer.parseInt(first);
        int H = sc.nextInt();
        int N = sc.nextInt();
        int M = sc.nextInt();
        double[][][] scores = new double[L][H][N];
        // 循环处理
        for (int l = 0; l < L; l++) {
            // 循环处理
            for (int h = 0; h < H; h++) {
                // 循环处理
                for (int t = 0; t < N; t++) scores[l][h][t] = Double.parseDouble(sc.next());
            }
        }
        int C = sc.nextInt();
        ArrayList<Candidate> cands = new ArrayList<>();
        // 循环处理
        for (int l = 0; l < L; l++) {
            // 循环处理
            for (int h = 0; h < H; h++) {
                // 循环处理
                for (int t = 0; t < N; t++) {
                    // 条件判断
                    if (t == C) continue;
                    cands.add(new Candidate(-scores[l][h][t], l, h, t));
                }
            }
        }
        cands.sort(new Comparator<Candidate>() {
            public int compare(Candidate x, Candidate y) {
                int c = Double.compare(x.negScore, y.negScore);
                // 条件判断
                if (c != 0) return c;
                // 条件判断
                if (x.l != y.l) return Integer.compare(x.l, y.l);
                // 条件判断
                if (x.h != y.h) return Integer.compare(x.h, y.h);
                // 返回结果
                return Integer.compare(x.t, y.t);
            }
        });
        long remaining = (long) M - (long) L * H;
        int take = (int) Math.min(Math.max(remaining, 0L), (long) cands.size());
        List<List<Integer>> kept = new ArrayList<>();
        // 循环处理
        for (int l = 0; l < L; l++) {
            // 循环处理
            for (int h = 0; h < H; h++) {
                List<Integer> list = new ArrayList<>();
                list.add(C);
                kept.add(list);
            }
        }
        // 枚举位置 i
        for (int i = 0; i < take; i++) {
            Candidate cd = cands.get(i);
            kept.get(cd.l * H + cd.h).add(cd.t);
        }
        StringBuilder sb = new StringBuilder();
        // 循环处理
        for (int l = 0; l < L; l++) {
            // 条件判断
            if (l > 0) sb.append(NL);
            // 循环处理
            for (int h = 0; h < H; h++) {
                // 条件判断
                if (h > 0) sb.append(' ');
                List<Integer> list = kept.get(l * H + h);
                Collections.sort(list);
                // 循环处理
                for (int idx = 0; idx < list.size(); idx++) {
                    // 条件判断
                    if (idx > 0) sb.append(',');
                    sb.append(list.get(idx));
                }
            }
        }
        System.out.print(sb);
    }
}

