// 题目：端侧大模型动态权重剪枝管理器
// 算法：动态规划
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(n)；空间 O(n)，包含输入数组和单调队列

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    // 核心方法：maximize
    static long[] maximize(long[] a, long[] b, long budget) {
        int n = a.length;
        int left = 0;
        long memory = 0;
        long score = 0;
        long ordinary = 0;
        // 循环处理
        for (int right = 0; right < n; right++) {
            memory += b[right];
            score += a[right];
            // 循环处理
            while (left <= right && memory > budget) {
                memory -= b[left];
                score -= a[left];
                left++;
            }
            ordinary = Math.max(ordinary, score);
        }
        left = 0;
        memory = 0;
        score = 0;
        long compressed = ordinary;
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        // 循环处理
        for (int right = 0; right < n; right++) {
            memory += b[right];
            score += a[right];
            // 循环处理
            while (!queue.isEmpty()) {
                int last = queue.peekLast();
                boolean ge;
                // 条件判断
                if (a[last] != a[right]) {
                    ge = a[last] > a[right];
                } else {
                    ge = b[last] <= b[right];
                }
                // 条件判断
                if (ge) queue.pollLast();
                else break;
            }
            queue.addLast(right);
            // 循环处理
            while (!queue.isEmpty() && memory - (b[queue.peekFirst()] + 1) / 2 > budget) {
                // 条件判断
                if (queue.peekFirst() == left) queue.pollFirst();
                memory -= b[left];
                score -= a[left];
                left++;
            }
            // 条件判断
            if (!queue.isEmpty()) {
                compressed = Math.max(compressed, score - a[queue.peekFirst()]);
            }
        }
        // 返回结果
        return new long[]{ordinary, compressed};
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String t = next();
        // 条件判断
        if (t == null) return;
        int n = Integer.parseInt(t);
        long budget = nextLong();
        long[] a = new long[n];
        long[] b = new long[n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // 枚举位置 i
        for (int i = 0; i < n; i++) b[i] = nextLong();
        long[] result = maximize(a, b, budget);
        StringBuilder sb = new StringBuilder();
        sb.append(result[0]).append(' ').append(result[1]);
        System.out.println(sb);
    }
}

items.books/ai-exam/ai-2026/华为/041-实现-Transfor:
// 题目：实现 Transformer 编码器层
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 一般序列长度为 T、模型维度为 d 时，注意力为 O(T^2d)，线性层为 O(Td^2)；本题 T=2,d=4，实际为常数量级；空间 一般为 O(T^2h+Td)；本题参数固定，实际为 O(1)

import java.io.*;
import java.util.*;

public class Main {

    static final int D_MODEL = 4;
    static final int D_K = 2;
    static final double EPS = 1e-5;
    // 核心方法：layerNorm
    static double[] layerNorm(double[] values) {
        double mean = 0.0;
        // 循环处理
        for (double v : values) mean += v;
        mean /= D_MODEL;
        double variance = 0.0;
        // 循环处理
        for (double v : values) variance += (v - mean) * (v - mean);
        variance /= D_MODEL;
        double scale = Math.sqrt(variance + EPS);
        double[] out = new double[D_MODEL];
        // 枚举位置 i
        for (int i = 0; i < D_MODEL; i++) out[i] = (values[i] - mean) / scale;
        // 返回结果
        return out;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        double[] values = new double[2 * D_MODEL];
        // 枚举位置 i
        for (int i = 0; i < values.length; i++) values[i] = Double.parseDouble(sc.next());
        double[][] x = new double[2][D_MODEL];
        // 枚举位置 i
        for (int i = 0; i < D_MODEL; i++) x[0][i] = values[i];
        // 枚举位置 i
        for (int i = 0; i < D_MODEL; i++) x[1][i] = values[D_MODEL + i];
        double[][][] headOut = new double[2][2][D_K];
        // 循环处理
        for (int hi = 0; hi < 2; hi++) {
            int start = hi * D_K;
            double[][] headValues = new double[2][D_K];
            // 循环处理
            for (int tok = 0; tok < 2; tok++) for (int d = 0; d < D_K; d++) headValues[tok][d] = x[tok][start + d];
            // 循环处理
            for (int qi = 0; qi < 2; qi++) {
                double[] scores = new double[2];
                // 循环处理
                for (int kj = 0; kj < 2; kj++) {
                    double dot = 0.0;
                    // 循环处理
                    for (int d = 0; d < D_K; d++) dot += headValues[qi][d] * headValues[kj][d];
                    scores[kj] = dot / Math.sqrt(D_K);
                }
                double maximum = scores[0];
                // 循环处理
                for (int kj = 1; kj < 2; kj++) if (scores[kj] > maximum) maximum = scores[kj];
                double[] w = new double[2];
                double total = 0.0;
                // 循环处理
                for (int kj = 0; kj < 2; kj++) { w[kj] = Math.exp(scores[kj] - maximum); total += w[kj]; }
                // 循环处理
                for (int d = 0; d < D_K; d++) {
                    double sum = 0.0;
                    // 循环处理
                    for (int kj = 0; kj < 2; kj++) sum += w[kj] * headValues[kj][d];
                    headOut[hi][qi][d] = sum / total;
                }
            }
        }
        double[][] attention = new double[2][D_MODEL];
        // 循环处理
        for (int tok = 0; tok < 2; tok++) {
            // 循环处理
            for (int d = 0; d < D_K; d++) {
                attention[tok][d] = headOut[0][tok][d];
                attention[tok][D_K + d] = headOut[1][tok][d];
            }
        }
        double[][] hidden = new double[2][D_MODEL];
        // 循环处理
        for (int tok = 0; tok < 2; tok++) {
            double[] pre = new double[D_MODEL];
            // 循环处理
            for (int d = 0; d < D_MODEL; d++) pre[d] = x[tok][d] + attention[tok][d];
            hidden[tok] = layerNorm(pre);
        }
        double[][] output = new double[2][D_MODEL];
        // 循环处理
        for (int tok = 0; tok < 2; tok++) {
            double[] pre = new double[D_MODEL];
            // 循环处理
            for (int d = 0; d < D_MODEL; d++) pre[d] = hidden[tok][d] + Math.max(0.0, hidden[tok][d]);
            output[tok] = layerNorm(pre);
        }
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        // 循环处理
        for (int tok = 0; tok < 2; tok++) {
            // 循环处理
            for (int d = 0; d < D_MODEL; d++) {
                String text = String.format(Locale.US, "%.2f", output[tok][d]);
                // 条件判断
                if (text.equals("-0.00")) text = "0.00";
                // 条件判断
                if (!first) sb.append(' ');
                first = false;
                sb.append(text);
            }
        }
        System.out.println(sb.toString());
    }
}

// 题目：核心路由器管理域规划
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(NLI)，其中 I 是一次二分 K-Means 的迭代轮数；空间 O(L)，不计输入与输出之外，每个点只属于当前簇列表中的一个簇

import java.io.*;
import java.util.*;

public class Main {

    static final double EPS = 1e-6;
    // 核心方法：Choice
    static class Choice { int index; List<double[]> first, second; Choice(int i, List<double[]> a, List<double[]> b) { index=i; first=a; second=b; } }
    // 核心方法：sse
    static double sse(List<double[]> pts) {
        int n = pts.size();
        double mx = 0.0, my = 0.0;
        // 循环处理
        for (double[] p : pts) { mx += p[0]; my += p[1]; }
        mx /= n; my /= n;
        double s = 0.0;
        // 循环处理
        for (double[] p : pts) { double dx = p[0] - mx, dy = p[1] - my; s += dx*dx + dy*dy; }
        // 返回结果
        return s;
    }
    // 核心方法：splitTwo
    static List<List<double[]>> splitTwo(List<double[]> pts) {
        double[] left = pts.get(0);
        // 循环处理
        for (double[] p : pts) if (p[0] < left[0]) left = p;
        double[] right = pts.get(0);
        // 循环处理
        for (double[] p : pts) if (p[0] > right[0]) right = p;
        double[][] centers = {{left[0], left[1]}, {right[0], right[1]}};
        int[] labels = null;
        // 循环处理
        while (true) {
            int m = pts.size();
            int[] newLabels = new int[m];
            // 枚举位置 i
            for (int i = 0; i < m; i++) {
                double[] p = pts.get(i);
                double d0 = (p[0]-centers[0][0])*(p[0]-centers[0][0]) + (p[1]-centers[0][1])*(p[1]-centers[0][1]);
                double d1 = (p[0]-centers[1][0])*(p[0]-centers[1][0]) + (p[1]-centers[1][1])*(p[1]-centers[1][1]);
                newLabels[i] = d0 < d1 ? 0 : 1;
            }
            // 条件判断
            if (labels != null && Arrays.equals(newLabels, labels)) break;
            labels = newLabels;
            double[] sums0 = {0,0}; int c0 = 0;
            double[] sums1 = {0,0}; int c1 = 0;
            // 枚举位置 i
            for (int i = 0; i < m; i++) { double[] p = pts.get(i); if (labels[i] == 0) { sums0[0]+=p[0]; sums0[1]+=p[1]; c0++; } else { sums1[0]+=p[0]; sums1[1]+=p[1]; c1++; } }
            double cx0 = sums0[0]/c0, cy0 = sums0[1]/c0, cx1 = sums1[0]/c1, cy1 = sums1[1]/c1;
            double move = Math.max(Math.hypot(cx0-centers[0][0], cy0-centers[0][1]), Math.hypot(cx1-centers[1][0], cy1-centers[1][1]));
            centers = new double[][]{{cx0,cy0},{cx1,cy1}};
            // 条件判断
            if (move < EPS) break;
        }
        List<double[]> first = new ArrayList<>();
        List<double[]> second = new ArrayList<>();
        // 枚举位置 i
        for (int i = 0; i < pts.size(); i++) { if (labels[i] == 0) first.add(pts.get(i)); else second.add(pts.get(i)); }
        List<List<double[]>> res = new ArrayList<>(); res.add(first); res.add(second);
        // 返回结果
        return res;
    }
    // 核心方法：chooseCluster
    static Choice chooseCluster(List<List<double[]>> clusters) {
        int bestIndex = -1;
        double bestGradient = 0.0;
        List<double[]> bestFirst = null, bestSecond = null;
        // 循环处理
        for (int idx = 0; idx < clusters.size(); idx++) {
            List<double[]> cluster = clusters.get(idx);
            // 条件判断
            if (cluster.size() < 2) continue;
            List<List<double[]>> children = splitTwo(cluster);
            double gradient = sse(cluster) - sse(children.get(0)) - sse(children.get(1));
            boolean better = gradient > bestGradient + EPS;
            boolean tied = Math.abs(gradient - bestGradient) <= EPS;
            boolean larger = bestIndex == -1 || cluster.size() > clusters.get(bestIndex).size();
            // 条件判断
            if (bestIndex == -1 || better || (tied && larger)) { bestIndex = idx; bestGradient = gradient; bestFirst = children.get(0); bestSecond = children.get(1); }
        }
        // 返回结果
        return new Choice(bestIndex, bestFirst, bestSecond);
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int target = sc.nextInt();
        int pointCount = sc.nextInt();
        List<double[]> points = new ArrayList<>();
        // 枚举位置 i
        for (int i = 0; i < pointCount; i++) { double x = (double) sc.nextInt(); double y = (double) sc.nextInt(); points.add(new double[]{x, y}); }
        List<List<double[]>> clusters = new ArrayList<>();
        clusters.add(points);
        StringBuilder out = new StringBuilder();
        out.append(pointCount).append((char)10);
        // 循环处理
        for (int step = 0; step < target - 1; step++) {
            Choice ch = chooseCluster(clusters);
            clusters.remove(ch.index);
            clusters.add(ch.first);
            clusters.add(ch.second);
            List<Integer> sizes = new ArrayList<>();
            // 循环处理
            for (List<double[]> c : clusters) sizes.add(c.size());
            sizes.sort(Collections.reverseOrder());
            StringBuilder line = new StringBuilder();
            // 枚举位置 i
            for (int i = 0; i < sizes.size(); i++) { if (i > 0) line.append(' '); line.append(sizes.get(i)); }
            out.append(line).append((char)10);
        }
        System.out.print(out.toString());
    }
}

