// 题目：流水线并行最小化最大 Stage 负载
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(N f)；空间 O(N)，存下每层的前向传播时间，判定过程只用常数个变量

import java.io.*;
import java.util.*;

public class Main {

    static long[] f;
    // 核心方法：countStages
    static long countStages(long cap) {
        long stages = 1;
        long load = 0;
        // 循环处理
        for (long x : f) {
            // 条件判断
            if (load + x > cap) { stages++; load = 0; }
            load += x;
        }
        // 返回结果
        return stages;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        f = new long[n];
        long lo = Long.MIN_VALUE, hi = 0;
        // 枚举位置 i
        for (int i = 0; i < n; i++) { f[i] = sc.nextLong(); if (f[i] > lo) lo = f[i]; hi += f[i]; }
        // 循环处理
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            // 条件判断
            if (countStages(mid) <= k) hi = mid; else lo = mid + 1;
        }
        System.out.println(lo);
    }
}

items.books/ai-exam/ai-2026/华为/044-稀疏局部注意力机制.m:
// 题目：稀疏局部注意力机制
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O((L(2W+1+G)+G L) D)；空间 O(L D)，存下三个矩阵；每行的候选与分数另占 O(L)，可以随用随弃

import java.io.*;
import java.util.*;

public class Main {

    // 核心方法：Cand
    static class Cand { int idx; long score; Cand(int i, long s) { idx=i; score=s; } }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int L = sc.nextInt(), D = sc.nextInt(), G = sc.nextInt(), W = sc.nextInt(), T = sc.nextInt();
        int[] globalList = new int[G];
        // 枚举位置 i
        for (int i = 0; i < G; i++) globalList[i] = sc.nextInt();
        boolean[] isGlobal = new boolean[L];
        // 循环处理
        for (int p : globalList) isGlobal[p] = true;
        int size = L * D;
        long[] q = new long[size];
        long[] k = new long[size];
        long[] v = new long[size];
        // 枚举位置 i
        for (int i = 0; i < size; i++) q[i] = sc.nextLong();
        // 枚举位置 i
        for (int i = 0; i < size; i++) k[i] = sc.nextLong();
        // 枚举位置 i
        for (int i = 0; i < size; i++) v[i] = sc.nextLong();
        StringBuilder out = new StringBuilder();
        // 枚举位置 i
        for (int i = 0; i < L; i++) {
            int[] cand;
            // 条件判断
            if (isGlobal[i]) {
                cand = new int[L];
                // 枚举阶段 j
                for (int j = 0; j < L; j++) cand[j] = j;
            } else {
                int lo = Math.max(0, i - W), hi = Math.min(L - 1, i + W);
                List<Integer> list = new ArrayList<>();
                // 枚举阶段 j
                for (int j = lo; j <= hi; j++) list.add(j);
                // 循环处理
                for (int p : globalList) if (p < lo || p > hi) list.add(p);
                cand = new int[list.size()];
                // 枚举阶段 j
                for (int j = 0; j < cand.length; j++) cand[j] = list.get(j);
            }
            List<Cand> kept = new ArrayList<>();
            // 循环处理
            for (int c : cand) {
                long s = 0;
                int base = c * D, qbase = i * D;
                // 循环处理
                for (int d = 0; d < D; d++) s += k[base + d] * q[qbase + d];
                // 条件判断
                if (s > 0) kept.add(new Cand(c, s));
            }
            kept.sort(new Comparator<Cand>() {
                public int compare(Cand a, Cand b) { if (a.score != b.score) return Long.compare(b.score, a.score); return Integer.compare(a.idx, b.idx); }
            });
            int take = Math.min(T, kept.size());
            // 条件判断
            if (take <= 0) {
                // 循环处理
                for (int d = 0; d < D; d++) { if (d > 0) out.append(' '); out.append(0); }
                out.append((char)10);
                continue;
            }
            long[] res = new long[D];
            // 循环处理
            for (int t = 0; t < take; t++) { Cand c = kept.get(t); int base = c.idx * D; for (int d = 0; d < D; d++) res[d] += c.score * v[base + d]; }
            // 循环处理
            for (int d = 0; d < D; d++) { if (d > 0) out.append(' '); out.append(res[d]); }
            out.append((char)10);
        }
        System.out.print(out.toString());
    }
}

