// 题目：K-Median 聚类
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(Tnkd)，T100 为实际轮数；分配需要 O(nkd)，簇筛选为 O(nk)，NumPy 中位数采用选择算法，所有簇合计处理 O(nd) 个坐标值；空间 O(nk+nd+kd)，包括距离矩阵、样本、簇成员与中心

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 核心方法：median
    static double median(double[] arr) {
        double[] c = arr.clone();
        Arrays.sort(c);
        int m = c.length;
        // 条件判断
        if (m % 2 == 1) return c[m / 2];
        // 返回结果
        return (c[m / 2 - 1] + c[m / 2]) / 2.0;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        int n = nextInt(), d = nextInt(), k = nextInt();
        double[][] points = new double[n][d];
        // 枚举位置 i
        for (int i = 0; i < n; i++) for (int j = 0; j < d; j++) points[i][j] = Double.parseDouble(next());
        double[][] centers = new double[k][d];
        // 枚举位置 i
        for (int i = 0; i < k; i++) centers[i] = points[i].clone();
        int[] labels = new int[n];
        // 循环处理
        for (int iter = 0; iter < 100; iter++) {
            // 枚举位置 i
            for (int i = 0; i < n; i++) {
                int best = -1;
                double bestD = 0;
                // 枚举阶段 j
                for (int j = 0; j < k; j++) {
                    double s = 0;
                    // 循环处理
                    for (int ax = 0; ax < d; ax++) s += Math.abs(points[i][ax] - centers[j][ax]);
                    // 条件判断
                    if (best == -1 || s < bestD) { bestD = s; best = j; }
                }
                labels[i] = best;
            }
            double[][] updated = new double[k][d];
            // 枚举阶段 j
            for (int j = 0; j < k; j++) {
                List<Integer> members = new ArrayList<>();
                // 枚举位置 i
                for (int i = 0; i < n; i++) if (labels[i] == j) members.add(i);
                // 条件判断
                if (members.isEmpty()) { updated[j] = centers[j].clone(); continue; }
                double[] vals = new double[members.size()];
                // 循环处理
                for (int ax = 0; ax < d; ax++) {
                    // 循环处理
                    for (int t = 0; t < members.size(); t++) vals[t] = points[members.get(t)][ax];
                    updated[j][ax] = median(vals);
                }
            }
            double shift = 0;
            // 枚举阶段 j
            for (int j = 0; j < k; j++) for (int ax = 0; ax < d; ax++) shift += Math.abs(updated[j][ax] - centers[j][ax]);
            centers = updated;
            // 条件判断
            if (shift < 1e-4) break;
        }
        double inertia = 0;
        // 枚举位置 i
        for (int i = 0; i < n; i++) for (int ax = 0; ax < d; ax++) inertia += Math.abs(points[i][ax] - centers[labels[i]][ax]);
        StringBuilder sb = new StringBuilder();
        // 枚举位置 i
        for (int i = 0; i < n; i++) { if (i > 0) sb.append(' '); sb.append(labels[i]); }
        sb.append((char)10);
        // 枚举阶段 j
        for (int j = 0; j < k; j++) {
            StringBuilder line = new StringBuilder();
            // 循环处理
            for (int ax = 0; ax < d; ax++) { if (ax > 0) line.append(' '); line.append(String.format(Locale.US, "%.6f", centers[j][ax])); }
            sb.append(line).append((char)10);
        }
        sb.append(String.format(Locale.US, "%.6f", inertia)).append((char)10);
        System.out.print(sb.toString());
    }
}

items.books/ai-exam/ai-2026/华为/048-分组查询注意力.md:
// 题目：分组查询注意力
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(h_qn^2(d_k+d_v))，每个头计算所有 Query/Key 点积及 V 加权和；空间 O(n^2+nh_q(d_k+d_v)+nh_kv(d_k+d_v))，包括掩码、输入及输出；单行临时缓冲仅为 O(n)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        int n = nextInt(), hq = nextInt(), hkv = nextInt(), dk = nextInt(), dv = nextInt();
        double[][] query = new double[n][hq * dk];
        double[][] key = new double[n][hkv * dk];
        double[][] value = new double[n][hkv * dv];
        int[][] mask = new int[n][n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) for (int j = 0; j < hq * dk; j++) query[i][j] = Double.parseDouble(next());
        // 枚举位置 i
        for (int i = 0; i < n; i++) for (int j = 0; j < hkv * dk; j++) key[i][j] = Double.parseDouble(next());
        // 枚举位置 i
        for (int i = 0; i < n; i++) for (int j = 0; j < hkv * dv; j++) value[i][j] = Double.parseDouble(next());
        // 枚举位置 i
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) mask[i][j] = nextInt();
        int group = hq / hkv;
        double[][] output = new double[n][hq * dv];
        double scale = Math.sqrt(dk);
        // 循环处理
        for (int head = 0; head < hq; head++) {
            int shared = head / group;
            int qStart = head * dk, kStart = shared * dk, vStart = shared * dv;
            // 枚举位置 i
            for (int i = 0; i < n; i++) {
                double[] scores = new double[n];
                // 枚举阶段 j
                for (int j = 0; j < n; j++) {
                    double s = 0;
                    // 循环处理
                    for (int t = 0; t < dk; t++) s += query[i][qStart + t] * key[j][kStart + t];
                    s /= scale;
                    scores[j] = mask[i][j] != 0 ? -1e30 : s;
                }
                double maximum = scores[0];
                // 枚举阶段 j
                for (int j = 1; j < n; j++) if (scores[j] > maximum) maximum = scores[j];
                double[] w = new double[n];
                double total = 0;
                // 枚举阶段 j
                for (int j = 0; j < n; j++) { w[j] = Math.exp(scores[j] - maximum); total += w[j]; }
                // 循环处理
                for (int t = 0; t < dv; t++) {
                    double sum = 0;
                    // 枚举阶段 j
                    for (int j = 0; j < n; j++) sum += w[j] * value[j][vStart + t];
                    output[i][head * dv + t] = sum / total;
                }
            }
        }
        StringBuilder out = new StringBuilder();
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            StringBuilder line = new StringBuilder();
            // 枚举阶段 j
            for (int j = 0; j < hq * dv; j++) { if (j > 0) line.append(' '); line.append(String.format(Locale.US, "%.2f", output[i][j])); }
            out.append(line).append((char)10);
        }
        System.out.print(out.toString());
    }
}

