// 题目：基于 CART 分类树预测客户购房选择
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;
import java.math.BigInteger;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    static class Tree {
        boolean leaf; int value; int feature; int splitValue; Tree left, right;
        Tree(int v) { leaf = true; value = v; }
        Tree(int f, int sv, Tree a, Tree b) { feature = f; splitValue = sv; left = a; right = b; }
    }
    // 核心方法：mass
    static BigInteger[] mass(long cz, long co) {
        long size = cz + co;
        // 条件判断
        if (size == 0) return new BigInteger[]{BigInteger.ZERO, BigInteger.ONE};
        // 返回结果
        return new BigInteger[]{BigInteger.valueOf(2 * cz * co), BigInteger.valueOf(size)};
    }
    // 核心方法：addF
    static BigInteger[] addF(BigInteger[] a, BigInteger[] b) {
        // 返回结果
        return new BigInteger[]{a[0].multiply(b[1]).add(b[0].multiply(a[1])), a[1].multiply(b[1])};
    }
    // 核心方法：lessF
    static boolean lessF(BigInteger[] a, BigInteger[] b) {
        // 返回结果
        return a[0].multiply(b[1]).compareTo(b[0].multiply(a[1])) < 0;
    }
    // 核心方法：build
    static Tree build(List<int[]> rows) {
        long countOne = 0;
        // 循环处理
        for (int[] r : rows) countOne += r[4];
        long countZero = rows.size() - countOne;
        int majority = countOne > countZero ? 1 : 0;
        // 条件判断
        if (countZero == 0 || countOne == 0 || rows.size() < 2) return new Tree(majority);
        BigInteger[] bestScore = mass(countZero, countOne);
        int bestFeature = -1, bestValue = 0;
        // 循环处理
        for (int feature = 0; feature < 4; feature++) {
            TreeSet<Integer> vals = new TreeSet<>();
            // 循环处理
            for (int[] r : rows) vals.add(r[feature]);
            // 循环处理
            for (int value : vals) {
                long leftOne = 0, leftSize = 0;
                // 循环处理
                for (int[] r : rows) if (r[feature] == value) { leftSize++; leftOne += r[4]; }
                long leftZero = leftSize - leftOne;
                BigInteger[] score = addF(mass(leftZero, leftOne), mass(countZero - leftZero, countOne - leftOne));
                // 条件判断
                if (lessF(score, bestScore)) { bestScore = score; bestFeature = feature; bestValue = value; }
            }
        }
        // 条件判断
        if (bestFeature == -1) return new Tree(majority);
        List<int[]> left = new ArrayList<>();
        List<int[]> right = new ArrayList<>();
        // 循环处理
        for (int[] r : rows) { if (r[bestFeature] == bestValue) left.add(r); else right.add(r); }
        // 返回结果
        return new Tree(bestFeature, bestValue, build(left), build(right));
    }
    // 核心方法：predict
    static int predict(Tree t, int[] s) {
        // 循环处理
        while (!t.leaf) { t = (s[t.feature] == t.splitValue) ? t.left : t.right; }
        // 返回结果
        return t.value;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        int n = nextInt();
        List<int[]> rows = new ArrayList<>();
        // 枚举位置 i
        for (int i = 0; i < n; i++) { int[] r = new int[5]; for (int j = 0; j < 5; j++) r[j] = nextInt(); rows.add(r); }
        Tree tree = build(rows);
        int m = nextInt();
        StringBuilder sb = new StringBuilder();
        // 枚举位置 i
        for (int i = 0; i < m; i++) {
            int[] s = new int[4];
            // 枚举阶段 j
            for (int j = 0; j < 4; j++) s[j] = nextInt();
            // 条件判断
            if (i > 0) sb.append(' ');
            sb.append(predict(tree, s));
        }
        System.out.println(sb.toString());
    }
}

items.books/ai-exam/ai-2026/华为/050-轻量化推理引擎中的-M:
// 题目：轻量化推理引擎中的 Masked Fused RMSNorm
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(mn)；空间 O(n)

import java.io.*;
import java.util.*;
import java.math.BigDecimal;
import java.math.RoundingMode;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 核心方法：formatValue
    static String formatValue(double value) {
        // 条件判断
        if (Math.abs(value) < 0.005) return "0.00";
        BigDecimal bd = new BigDecimal(value);
        bd = bd.setScale(2, RoundingMode.HALF_UP);
        // 返回结果
        return bd.toPlainString();
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        int m = nextInt();
        int n = nextInt();
        double epsilon = Double.parseDouble(next());
        double[] gamma = new double[n];
        double[] beta = new double[n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) gamma[i] = Double.parseDouble(next());
        // 枚举位置 i
        for (int i = 0; i < n; i++) beta[i] = Double.parseDouble(next());
        StringBuilder out = new StringBuilder();
        // 循环处理
        for (int row = 0; row < m; row++) {
            int length = nextInt();
            double alpha = Double.parseDouble(next());
            double[] x = new double[n];
            double[] residual = new double[n];
            // 枚举位置 i
            for (int i = 0; i < n; i++) x[i] = Double.parseDouble(next());
            // 枚举位置 i
            for (int i = 0; i < n; i++) residual[i] = Double.parseDouble(next());
            double[] fused = new double[length];
            double energy = 0.0;
            // 枚举位置 i
            for (int i = 0; i < length; i++) { fused[i] = x[i] + alpha * residual[i]; energy += fused[i] * fused[i]; }
            double rms = Math.sqrt(energy / Math.max(length, 1) + epsilon);
            double[] output = new double[n];
            // 枚举位置 i
            for (int i = 0; i < length; i++) output[i] = gamma[i] * (fused[i] / rms) + beta[i];
            StringBuilder line = new StringBuilder();
            // 枚举位置 i
            for (int i = 0; i < n; i++) { if (i > 0) line.append(' '); line.append(formatValue(output[i])); }
            line.append(" | ").append(formatValue(rms)).append(" | ").append(formatValue(energy));
            out.append(line).append((char)10);
        }
        System.out.print(out.toString());
    }
}

items.books/ai-exam/ai-2026/华为/051-X-Means-聚类算:
// 题目：X-Means 聚类算法的实现
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）
// 复杂度：时间 总时间可保守写为 O(N N+_K=K_min^K_max [T_KNKd+K^2(d+(K+1))]). 空间复杂度 ：O(Nd+K_maxd+N)=O(Nd)，因为截断后 K_max N；空间 O(Nd+K_maxd+N)=O(Nd)，因为截断后 K_max N

import java.io.*;
import java.util.*;

public class Main {

    static final double MERGE_EPS=1e-4;
    static final double BIC_EPS=1e-9;
    // 核心方法：dist2
    static double dist2(double[] a,double[] b) {
        double v=0.0;
        // 枚举位置 i
        for(int i=0;i<a.length;i++) {
            double d=a[i]-b[i];
            v+=d*d;
        }
        // 返回结果
        return v;
    }
    // 核心方法：find
    static int find(int[] p,int x) {
        // 循环处理
        while(p[x]!=x) {
            p[x]=p[p[x]];
            x=p[x];
        }
        // 返回结果
        return x;
    }
    // 核心方法：kmeans
    static double[][] kmeans(double[][] pts,int[] order,int d,int k,int[] outLab) {
        int n=pts.length;
        double[][] c=new double[k][];
        // 枚举位置 i
        for(int i=0;i<k;i++) {
            int pos=(k==1)?0:i*(n-1)/(k-1);
            c[i]=pts[order[pos]].clone();
        }
        int[] lab=new int[n];
        Arrays.fill(lab,-1);
        // 循环处理
        while(true) {
            int[] nl=new int[n];
            // 循环处理
            for(int p=0;p<n;p++) {
                int best=0;
                double bd=dist2(pts[p],c[0]);
                // 枚举阶段 j
                for(int j=1;j<k;j++) {
                    double cur=dist2(pts[p],c[j]);
                    // 条件判断
                    if(cur<bd) {
                        best=j;
                        bd=cur;
                    }
                }
                nl[p]=best;
            }
            // 条件判断
            if(Arrays.equals(nl,lab)) {
                System.arraycopy(lab,0,outLab,0,n);
                // 返回结果
                return c;
            }
            lab=nl;
            int[] cnt=new int[k];
            double[][] tot=new double[k][d];
            // 循环处理
            for(int p=0;p<n;p++) {
                int ci=lab[p];
                cnt[ci]++;
                // 枚举阶段 j
                for(int j=0;j<d;j++)tot[ci][j]+=pts[p][j];
            }
            // 循环处理
            for(int ci=0;ci<k;ci++)if(cnt[ci]!=0)for(int j=0;j<d;j++)c[ci][j]=tot[ci][j]/cnt[ci];
        }
    }
    // 核心方法：mergeCenters
    static Object[] mergeCenters(double[][] pts,double[][] c,int[] lab,int d) {
        int k=c.length;
        int[] par=new int[k];
        // 枚举位置 i
        for(int i=0;i<k;i++)par[i]=i;
        // 循环处理
        for(int a=0;a<k;a++)for(int b=a+1;b<k;b++)if(dist2(c[a],c[b])<MERGE_EPS) {
            int ra=find(par,a),rb=find(par,b);
            // 条件判断
            if(ra!=rb)par[Math.max(ra,rb)]=Math.min(ra,rb);
        }
        int[] roots=new int[k];
        TreeSet<Integer> set=new TreeSet<>();
        // 枚举位置 i
        for(int i=0;i<k;i++) {
            roots[i]=find(par,i);
            set.add(roots[i]);
        }
        List<Integer> reps=new ArrayList<>(set);
        HashMap<Integer,Integer> num=new HashMap<>();
        // 枚举位置 i
        for(int i=0;i<reps.size();i++)num.put(reps.get(i),i);
        int size=reps.size();
        int[] nl=new int[lab.length];
        // 枚举位置 i
        for(int i=0;i<lab.length;i++)nl[i]=num.get(roots[lab[i]]);
        int[] cnt=new int[size];
        double[][] tot=new double[size][d];
        // 循环处理
        for(int p=0;p<pts.length;p++) {
            int ci=nl[p];
            cnt[ci]++;
            // 枚举阶段 j
            for(int j=0;j<d;j++)tot[ci][j]+=pts[p][j];
        }
        double[][] merged=new double[size][];
        // 循环处理
        for(int ci=0;ci<size;ci++) {
            // 条件判断
            if(cnt[ci]!=0) {
                merged[ci]=new double[d];
                // 枚举阶段 j
                for(int j=0;j<d;j++)merged[ci][j]=tot[ci][j]/cnt[ci];
            } else merged[ci]=c[reps.get(ci)].clone();
        }
        // 返回结果
        return new Object[] {
            merged,nl
        }
        ;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        String first = sc.next();
        // 条件判断
        if (first == null) return;
        int n = Integer.parseInt(first);
        int d = sc.nextInt();
        // 条件判断
        if(n<=0||d<=0) {
            System.out.println(0);
            // 返回结果
            return;
        }
        double[][] pts=new double[n][d];
        // 枚举位置 i
        for(int i=0;i<n;i++)for(int j=0;j<d;j++)pts[i][j]=Double.parseDouble(sc.next());
        int kmin=sc.nextInt();
        int kmax=sc.nextInt();
        kmax=Math.min(kmax,n);
        kmin=Math.min(kmin,kmax);
        // 条件判断
        if(kmin<1) {
            System.out.println(0);
            // 返回结果
            return;
        }
        Integer[] ord=new Integer[n];
        // 枚举位置 i
        for(int i=0;i<n;i++)ord[i]=i;
        final double[][] P=pts;
        Arrays.sort(ord,(x,y)-> {
            int r=Double.compare(P[x][0],P[y][0]);return r!=0?r:Integer.compare(x,y);
        }
        );
        int[] order=new int[n];
        // 枚举位置 i
        for(int i=0;i<n;i++)order[i]=ord[i];
        double bestBic=Double.POSITIVE_INFINITY;
        double[][] bestC=null;
        int[] bestL=null;
        // 循环处理
        for(int k=kmin;k<=kmax;k++) {
            int[] lab=new int[n];
            double[][] c=kmeans(pts,order,d,k,lab);
            Object[] mr=mergeCenters(pts,c,lab,d);
            c=(double[][])mr[0];
            lab=(int[])mr[1];
            double sse=0.0;
            // 循环处理
            for(int p=0;p<n;p++)sse+=dist2(pts[p],c[lab[p]]);
            double bic=n*Math.log((sse+1e-8)/n)+c.length*(d+1)*Math.log(n);
            // 条件判断
            if(bic<bestBic-BIC_EPS) {
                bestBic=bic;
                bestC=c;
                bestL=lab;
            }
        }
        Integer[] co=new Integer[bestC.length];
        // 枚举位置 i
        for(int i=0;i<co.length;i++)co[i]=i;
        final double[][] BC=bestC;
        Arrays.sort(co,(x,y)-> {
            int r=Double.compare(BC[x][0],BC[y][0]);return r!=0?r:Integer.compare(x,y);
        }
        );
        int[] remap=new int[bestC.length];
        // 枚举位置 i
        for(int i=0;i<co.length;i++)remap[co[i]]=i;
        StringBuilder sb=new StringBuilder();
        sb.append(co.length).append((char)10);
        // 循环处理
        for(int oi=0;oi<co.length;oi++) {
            int ci=co[oi];
            StringBuilder row=new StringBuilder();
            // 枚举阶段 j
            for(int j=0;j<bestC[ci].length;j++) {
                String s=String.format(Locale.ROOT,"%.2f",bestC[ci][j]);
                // 条件判断
                if(s.equals("-0.00"))s="0.00";
                // 条件判断
                if(j>0)row.append(' ');
                row.append(s);
            }
            sb.append(row).append((char)10);
        }
        // 循环处理
        for(int p=0;p<bestL.length;p++) {
            // 条件判断
            if(p>0)sb.append(' ');
            sb.append(remap[bestL[p]]);
        }
        sb.append((char)10);
        System.out.print(sb);
    }
}

// 题目：网游皮肤智能推荐系统
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(N+M)；空间 O(N)

import java.io.*;
import java.util.*;

public class Main {

    static final double EPS=1e-9;
    // 核心方法：lg
    static double lg(double x) {
        // 返回结果
        return Math.log(x)/Math.log(2.0);
    }
    // 核心方法：ent
    static double ent(int pos,int tot) {
        // 条件判断
        if(tot==0||pos==0||pos==tot)return 0.0;
        double p=(double)pos/tot,q=(double)(tot-pos)/tot;
        // 返回结果
        return -p*lg(p)-q*lg(q);
    }
    static class Node {
        int f;
        Object l,r;
        Node(int f,Object l,Object r) {
            this.f=f;
            this.l=l;
            this.r=r;
        }
    }
    // 核心方法：build
    static Object build(List<int[]> rows,int[] feats,int fb) {
        // 条件判断
        if(rows.isEmpty())return fb;
        int n=rows.size(),pos=0;
        // 循环处理
        for(int[] r:rows)pos+=r[3];
        int lab=(pos>n-pos)?1:0;
        // 条件判断
        if(pos==0||pos==n||feats.length==0)return lab;
        double base=ent(pos,n);
        int bf=-1;
        double bg=Double.NEGATIVE_INFINITY;
        // 循环处理
        for(int f:feats) {
            int[] cnt=new int[2];
            int[] pp=new int[2];
            // 循环处理
            for(int[] r:rows) {
                int v=r[f];
                cnt[v]++;
                pp[v]+=r[3];
            }
            double cond=0;
            // 循环处理
            for(int v=0;v<2;v++)cond+=(double)cnt[v]/n*ent(pp[v],cnt[v]);
            double g=base-cond;
            // 条件判断
            if(g>bg+EPS) {
                bg=g;
                bf=f;
            }
        }
        // 条件判断
        if(bg<=EPS)return lab;
        final int bfFinal=bf;
        int[] rem=Arrays.stream(feats).filter(f->f!=bfFinal).toArray();
        List<int[]> L=new ArrayList<>();
        List<int[]> R=new ArrayList<>();
        // 循环处理
        for(int[] r:rows) {
            // 条件判断
            if(r[bf]==0)L.add(r);
            else R.add(r);
        }
        Object lc=build(L,rem,lab);
        Object rc=build(R,rem,lab);
        // 返回结果
        return new Node(bf,lc,rc);
    }
    // 核心方法：predict
    static int predict(Object t,int[] s) {
        // 循环处理
        while(t instanceof Node) {
            Node nd=(Node)t;
            t=(s[nd.f]==1)?nd.r:nd.l;
        }
        // 返回结果
        return (Integer)t;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] a) throws IOException {
        Scanner sc = new Scanner(System.in);
        String first = sc.next();
        // 条件判断
        if (first == null) return;
        int n = Integer.parseInt(first);
        int m = sc.nextInt();
        List<int[]> tr=new ArrayList<>();
        // 枚举位置 i
        for(int i=0;i<n;i++)tr.add(new int[]{ sc.nextInt(), sc.nextInt(), sc.nextInt(), sc.nextInt() });
        Object tree=build(tr,new int[] {
            0,1,2
        }
        ,0);
        StringBuilder sb=new StringBuilder();
        // 枚举位置 i
        for(int i=0;i<m;i++) {
            sb.append(predict(tree,new int[]{ sc.nextInt(), sc.nextInt(), sc.nextInt() })).append((char)10);
        }
        System.out.print(sb);
    }
}

