// 题目：最优流水线并行切分
// 算法：动态规划（前缀和 + 滚动数组）
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(KN^2)；空间 O(N)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static String nextLine() throws IOException { return br.readLine(); }

    static long INF=Long.MAX_VALUE/4;
    // 核心方法：minMax
    static long minMax(int[] t,int[] s,int k) {
        int n=t.length;
        // 前缀和：pre[i] 表示前 i 层计算耗时之和
        long[] pre=new long[n+1];
        // 枚举前 i 层
        for(int i=1;i<=n;i++)pre[i]=pre[i-1]+t[i-1];
        // prev[b]：前 b 层分成 j-1 段时的最小瓶颈
        long[] prev=new long[n+1];
        Arrays.fill(prev,INF);
        prev[0]=0;
        // 枚举阶段数 j
        for(int j=1;j<=k;j++) {
            // 当前阶段 j 的 DP 行
            long[] cur=new long[n+1];
            Arrays.fill(cur,INF);
            // 枚举前 i 层
            for(int i=j;i<=n;i++) {
                // 当前段末尾需要支付的通信耗时
                int comm=(i<n)?s[i-1]:0;
                long best=INF;
                // 枚举最后一段的起点 b
                for(int b=j-1;b<i;b++) {
                    // 条件判断
                    if(prev[b]==INF)continue;
                    long last=pre[i]-pre[b]+comm;
                    // 当前切法的瓶颈 = max(前缀瓶颈, 最后一段耗时)
                    long cand=Math.max(prev[b],last);
                    // 条件判断
                    if(cand<best)best=cand;
                }
                cur[i]=best;
            }
            prev=cur;
        }
        // 返回恰好 K 段覆盖 N 层的最优值
        return prev[n];
    }
    // 核心方法：readLine
    static int[] readLine() throws IOException {
