// 题目：密码强度字符串计数
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(n_+T)；空间 O(n_+T)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 主函数：读取输入并输出答案
    public static void main(String[] x) throws IOException {
        int t=nextInt();
        int[] len=new int[t];
        int max=0;
        // 枚举位置 i
        for(int i=0;i<t;i++) {
            len[i]=nextInt();
            // 条件判断
            if(len[i]>max)max=len[i];
        }
        long MOD=1000000007L;
        long[] ans=new long[max+1];
        long e1=26,e2=0,e3=0;
        // 条件判断
        if(max>=1)ans[1]=26;
        // 循环处理
        for(int L=2;L<=max;L++) {
            long tot=(e1+e2+e3)%MOD;
            long ne1=tot*25%MOD;
            long ne2=e1;
            long ne3=e2;
            e1=ne1;
            e2=ne2;
            e3=ne3;
            ans[L]=(e1+e2+e3)%MOD;
        }
        StringBuilder out=new StringBuilder();
        // 枚举位置 i
        for(int i=0;i<t;i++) {
            // 条件判断
            if(i>0)out.append((char)10);
            out.append(ans[len[i]]);
        }
        System.out.print(out);
    }
}

items.books/ai-exam/ai-2026/拼多多/059-CLIP-对比学习损:
// 题目：CLIP 对比学习损失
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(N^2 D)，主要开销是相似度矩阵的矩阵乘法；空间 O(N^2)，存储 logits 矩阵

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    static String nextLine() throws IOException { return br.readLine(); }

    static class Json {
        String s;
        int i=0;
        Json(String s) {
            this.s=s;
        }
        Object parse() {
            // 返回结果
            return value();
        }
        void ws() {
            // 循环处理
            while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;
        }
        Object value() {
            ws();
            char c=s.charAt(i);
            // 条件判断
            if(c=='{')return obj();
            // 条件判断
            if(c=='[')return arr();
            // 条件判断
            if(c=='"')return str();
            // 条件判断
            if(c=='t') {
                i+=4;
                // 返回结果
                return Boolean.TRUE;
            }
            // 条件判断
            if(c=='f') {
                i+=5;
                // 返回结果
                return Boolean.FALSE;
            }
            // 条件判断
            if(c=='n') {
                i+=4;
                // 返回结果
                return null;
            }
            int st=i;
            // 循环处理
            while(i<s.length()&&"-+.eE0123456789".indexOf(s.charAt(i))>=0)i++;
            // 返回结果
            return Double.parseDouble(s.substring(st,i));
        }
        Map<String,Object> obj() {
            Map<String,Object> m=new LinkedHashMap<>();
            i++;
            ws();
            // 条件判断
            if(s.charAt(i)=='}') {
                i++;
                // 返回结果
                return m;
            }
            // 循环处理
            while(true) {
                ws();
                String k=str();
                ws();
                i++;
                Object v=value();
                m.put(k,v);
                ws();
                char c=s.charAt(i);
                i++;
                // 条件判断
                if(c=='}')break;
            }
            // 返回结果
            return m;
        }
        List<Object> arr() {
            List<Object> l=new ArrayList<>();
            i++;
            ws();
            // 条件判断
            if(s.charAt(i)==']') {
                i++;
                // 返回结果
                return l;
            }
            // 循环处理
            while(true) {
                l.add(value());
                ws();
                char c=s.charAt(i);
                i++;
                // 条件判断
                if(c==']')break;
            }
            // 返回结果
            return l;
        }
        String str() {
            StringBuilder sb=new StringBuilder();
            i++;
            // 循环处理
            while(s.charAt(i)!='"') {
                sb.append(s.charAt(i));
                i++;
            }
            i++;
            // 返回结果
            return sb.toString();
        }
    }
    // 核心方法：toMat
    static double[][] toMat(List<Object> l) {
        double[][] m=new double[l.size()][];
        // 枚举位置 i
        for(int i=0;i<l.size();i++) {
            List<Object> row=(List<Object>)l.get(i);
            m[i]=new double[row.size()];
            // 枚举阶段 j
            for(int j=0;j<row.size();j++)m[i][j]=((Number)row.get(j)).doubleValue();
        }
        // 返回结果
        return m;
    }
    // 核心方法：crossEntropy
    static double crossEntropy(double[][] m) {
        int n=m.length;
        double sum=0;
        // 枚举位置 i
        for(int i=0;i<n;i++) {
            double mx=Double.NEGATIVE_INFINITY;
            // 枚举阶段 j
            for(int j=0;j<m[i].length;j++)mx=Math.max(mx,m[i][j]);
            double s=0;
            // 枚举阶段 j
            for(int j=0;j<m[i].length;j++)s+=Math.exp(m[i][j]-mx);
            sum+=(mx+Math.log(s))-m[i][i];
        }
        // 返回结果
        return sum/n;
    }
    // 核心方法：transpose
    static double[][] transpose(double[][] a) {
        int r=a.length,c=a[0].length;
        double[][] t=new double[c][r];
        // 枚举位置 i
        for(int i=0;i<r;i++)for(int j=0;j<c;j++)t[j][i]=a[i][j];
        // 返回结果
        return t;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] a) throws IOException {
        String line=nextLine();
        // 条件判断
        if(line==null)return;
        Object parsed=new Json(line).parse();
        Map<String,Object> root=(Map<String,Object>)parsed;
        double[][] img=toMat((List<Object>)root.get("image_embeds"));
        double[][] txt=toMat((List<Object>)root.get("text_embeds"));
        double temp=((Number)root.get("temperature")).doubleValue();
        int N=img.length,D=img[0].length,M=txt.length;
        double[][] logits=new double[N][M];
        // 枚举位置 i
        for(int i=0;i<N;i++)for(int j=0;j<M;j++) {
            double s=0;
            // 循环处理
            for(int k=0;k<D;k++)s+=img[i][k]*txt[j][k];
            logits[i][j]=s/temp;
        }
        double loss=(crossEntropy(logits)+crossEntropy(transpose(logits)))/2.0;
        System.out.println(String.format(Locale.ROOT,"%.6f",loss));
    }
}

