// 题目：多多捕蝇
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(n)，每个房间入队出队各一次，每个环完整遍历一次；空间 O(n)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 主函数：读取输入并输出答案
    public static void main(String[] a) throws IOException {
        int n=nextInt();
        long[] c=new long[n+1];
        int[] pa=new int[n+1];
        // 枚举位置 i
        for(int i=1;i<=n;i++)c[i]=nextLong();
        // 枚举位置 i
        for(int i=1;i<=n;i++)pa[i]=nextInt();
        int[] indeg=new int[n+1];
        // 枚举位置 i
        for(int i=1;i<=n;i++)indeg[pa[i]]++;
        boolean[] rem=new boolean[n+1];
        ArrayDeque<Integer> q=new ArrayDeque<>();
        // 枚举位置 i
        for(int i=1;i<=n;i++)if(indeg[i]==0)q.add(i);
        // 循环处理
        while(!q.isEmpty()) {
            int u=q.poll();
            rem[u]=true;
            int v=pa[u];
            indeg[v]--;
            // 条件判断
            if(indeg[v]==0&&!rem[v])q.add(v);
        }
        boolean[] vis=new boolean[n+1];
        long ans=0;
        // 枚举位置 i
        for(int i=1;i<=n;i++) {
            // 条件判断
            if(!rem[i]&&!vis[i]) {
                long mn=c[i];
                vis[i]=true;
                int x=pa[i];
                // 循环处理
                while(x!=i) {
                    vis[x]=true;
                    // 条件判断
                    if(c[x]<mn)mn=c[x];
                    x=pa[x];
                }
                ans+=mn;
            }
        }
        System.out.println(ans);
    }
}

