// 题目：多多的营救行动
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(n E)，E 为监视关系总数，每轮剥离至少消除一个守卫；空间 O(n + E)

import java.io.*;
import java.util.*;
public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    static int n;
    static ArrayList<HashSet<Integer>> mon;
    static boolean[] alive;
    static ArrayList<ArrayList<Integer>> watch;
    static int cnt;
    // 核心方法：kill
    static void kill(int i) {
        alive[i]=false;
        cnt--;
        // 循环处理
        for(int r:watch.get(i))if(r>=1&&r<=n)mon.get(r).remove(i);
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] x)throws IOException {
        n=nextInt();
        watch=new ArrayList<>();
        // 枚举位置 i
        for(int i=0;i<=n;i++)watch.add(new ArrayList<>());
        // 枚举位置 i
        for(int i=0;i<n;i++) {
            int node=nextInt();
            int m=nextInt();
            ArrayList<Integer> lst=new ArrayList<>();
            // 枚举阶段 j
            for(int j=0;j<m;j++)lst.add(nextInt());
            watch.set(node,lst);
        }
        mon=new ArrayList<>();
        // 枚举位置 i
        for(int i=0;i<=n;i++)mon.add(new HashSet<>());
        // 枚举阶段 j
        for(int j=1;j<=n;j++)for(int r:watch.get(j))if(r>=1&&r<=n&&r!=j)mon.get(r).add(j);
        alive=new boolean[n+1];
        // 枚举位置 i
        for(int i=1;i<=n;i++)alive[i]=true;
        cnt=n;
        boolean changed=true;
        // 循环处理
        while(changed) {
            changed=false;
            // 枚举位置 i
            for(int i=1;i<=n;i++) {
                // 条件判断
                if(alive[i]&&mon.get(i).isEmpty()) {
                    kill(i);
                    changed=true;
                }
            }
            // 条件判断
            if(changed)continue;
            // 枚举位置 i
            for(int i=1;i<=n;i++) {
                // 条件判断
                if(alive[i]&&mon.get(i).size()==1) {
                    int j=mon.get(i).iterator().next();
                    // 条件判断
                    if(alive[j]&&mon.get(j).size()==1&&mon.get(j).contains(i)) {
                        kill(i);
                        kill(j);
                        changed=true;
                        break;
                    }
                }
            }
        }
        // 条件判断
        if(cnt==0)System.out.println("SUCCESS");
        else System.out.println(cnt);
    }
}

