// 题目：机房维护
// 算法：动态规划
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(n n)，排序与每个任务的一次二分查找占主导；空间 O(n)，用于保存排序后的任务、结束时间数组和动态规划数组

import java.io.*;
import java.util.*;
public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    static class T {
        int end,start,value;
        T(int e,int s,int val) {
            end=e;
            start=s;
            value=val;
        }
    }
    // 核心方法：bisect
    static int bisect(long[] arr,int lo,int hi,long key) {
        // 循环处理
        while(lo<hi) {
            int mid=(lo+hi)>>>1;
            // 条件判断
            if(arr[mid]<=key)lo=mid+1;
            else hi=mid;
        }
        // 返回结果
        return lo;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] a)throws IOException {
        int n=nextInt();
        T[] ts=new T[n];
        // 枚举位置 i
        for(int i=0;i<n;i++) {
            int s=nextInt(),e=nextInt(),v=nextInt();
            ts[i]=new T(e,s,v);
        }
        Arrays.sort(ts,(x,y)->Integer.compare(x.end,y.end));
        long[] ends=new long[n];
        // 枚举位置 i
        for(int i=0;i<n;i++)ends[i]=ts[i].end;
        long[] dp=new long[n+1];
        // 枚举位置 i
        for(int i=1;i<=n;i++) {
            T t=ts[i-1];
            int cc=bisect(ends,0,i-1,t.start);
            dp[i]=Math.max(dp[i-1],dp[cc]+t.value);
        }
        System.out.println(dp[n]);
    }
}

