    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    // 核心方法：query
    static int query(int[] tree,int pos) {
        int r=0;
        // 循环处理
        while(pos>0) {
            // 条件判断
            if(tree[pos]>r)r=tree[pos];
            pos-=pos&-pos;
        }
        // 返回结果
        return r;
    }
    // 核心方法：update
    static void update(int[] tree,int pos,int val) {
        int sz=tree.length-1;
        // 循环处理
        while(pos<=sz) {
            // 条件判断
            if(val>tree[pos])tree[pos]=val;
            pos+=pos&-pos;
        }
    }
    // 核心方法：bisectLeft
    static int bisectLeft(int[] arr,int key) {
        int lo=0,hi=arr.length;
        // 循环处理
        while(lo<hi) {
            int mid=(lo+hi)>>>1;
            // 条件判断
            if(arr[mid]<key)lo=mid+1;
            else hi=mid;
        }
        // 返回结果
        return lo;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] a)throws IOException {
        int n=nextInt(),m=nextInt();
        int[] ea=new int[m],eb=new int[m],ew=new int[m];
        ArrayList<ArrayList<Integer>> vals=new ArrayList<>();
        // 枚举位置 i
        for(int i=0;i<=n;i++)vals.add(new ArrayList<>());
        // 枚举位置 i
        for(int i=0;i<m;i++) {
            ea[i]=nextInt();
            eb[i]=nextInt();
            ew[i]=nextInt();
            vals.get(ea[i]).add(ew[i]);
            vals.get(eb[i]).add(ew[i]);
        }
        int[][] values=new int[n+1][];
        // 枚举位置 i
        for(int i=0;i<=n;i++) {
            TreeSet<Integer> ts=new TreeSet<>(vals.get(i));
            values[i]=new int[ts.size()];
            int k=0;
            // 循环处理
            for(int v:ts)values[i][k++]=v;
        }
        int[][] trees=new int[n+1][];
        // 枚举位置 i
        for(int i=0;i<=n;i++)trees[i]=new int[values[i].length+1];
        int ans=0;
        // 枚举位置 i
        for(int i=0;i<m;i++) {
            int srcPos=bisectLeft(values[ea[i]],ew[i])+1;
            int cur=query(trees[ea[i]],srcPos-1)+1;
            int tgtPos=bisectLeft(values[eb[i]],ew[i])+1;
            update(trees[eb[i]],tgtPos,cur);
            // 条件判断
            if(cur>ans)ans=cur;
        }
        System.out.println(ans);
    }
}

