import java.io.*;
import java.util.*;
public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static String nextLine() throws IOException { return br.readLine(); }
    // 核心方法：stackPossible
    static boolean stackPossible(String s,String t) {
        char[] st=new char[s.length()];
        int top=0,j=0;
        // 枚举位置 i
        for(int i=0;i<s.length();i++) {
            st[top++]=s.charAt(i);
            // 循环处理
            while(top>0&&j<t.length()&&st[top-1]==t.charAt(j)) {
                top--;
                j++;
            }
        }
        // 返回结果
        return j==t.length();
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] a)throws IOException {
        String s=nextLine();
