        s=s.trim();
        String tt=nextLine();
        // 条件判断
        if(tt==null)tt="";
        tt=tt.trim();
        boolean q=s.equals(tt);
        boolean st=stackPossible(s,tt);
        // 条件判断
        if(q&&st)System.out.println("both");
        else if(q)System.out.println("queue");
        else if(st)System.out.println("stack");
        else System.out.println("neither");
    }
}

items.books/ai-exam/ai-2026/拼多多/067-和差方程最少标定.m:
// 题目：和差方程最少标定
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O((p+e)(p)), 空间复杂度：O(p)；空间 O(p)

import java.io.*;
import java.util.*;
public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    static int[] parent;
    static long[] size,potential;
    // 核心方法：find
    static int find(int x) {
        int[] path=new int[64];
        int len=0;
        int cur=x;
        // 循环处理
        while(parent[cur]!=cur) {
            // 条件判断
            if(len==path.length)path=Arrays.copyOf(path,len*2);
            path[len++]=cur;
            cur=parent[cur];
        }
        int root=cur;
        long tot=0;
        // 枚举位置 i
        for(int i=len-1;i>=0;i--) {
            int node=path[i];
            tot+=potential[node];
            potential[node]=tot;
            parent[node]=root;
        }
        // 返回结果
        return root;
    }
    // 核心方法：unite
    static boolean unite(int a,int b,long diff) {
        int ra=find(a),rb=find(b);
        // 条件判断
        if(ra==rb)return potential[a]-potential[b]==diff;
        // 条件判断
        if(size[ra]<size[rb]) {
            parent[ra]=rb;
            potential[ra]=potential[b]+diff-potential[a];
            size[rb]+=size[ra];
        } else {
            parent[rb]=ra;
            potential[rb]=potential[a]-diff-potential[b];
            size[ra]+=size[rb];
        }
        // 返回结果
        return true;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] a)throws IOException {
        int vc=nextInt(),rc=nextInt();
        int nc=2*vc;
        parent=new int[nc];
        size=new long[nc];
        potential=new long[nc];
        Arrays.fill(size,1);
        // 枚举位置 i
        for(int i=0;i<nc;i++)parent[i]=i;
        boolean consistent=true;
        // 循环处理
        for(int r=0;r<rc;r++) {
            String op=next();
            int u=nextInt()-1,v=nextInt()-1;
            long w=nextLong();
            // 条件判断
            if(!consistent)continue;
            boolean f1,f2;
            // 条件判断
            if(op.equals("D")) {
                f1=unite(u,v,w);
                f2=unite(u+vc,v+vc,-w);
            } else {
                f1=unite(u,v+vc,w);
                f2=unite(u+vc,v,-w);
            }
            consistent=f1&&f2;
        }
        // 条件判断
        if(!consistent) {
            System.out.println("NO");
            System.out.println(-1);
            // 返回结果
            return;
        }
        boolean[] pinned=new boolean[nc];
        // 枚举位置 i
        for(int i=0;i<vc;i++) {
            int root=find(i);
            int mr=find(i+vc);
            // 条件判断
            if(root!=mr)continue;
            long delta=potential[i]-potential[i+vc];
            // 条件判断
            if(delta%2!=0) {
                System.out.println("NO");
                System.out.println(-1);
                // 返回结果
                return;
            }
            pinned[root]=true;
        }
        int free=0;
        // 循环处理
        for(int node=0;node<nc;node++) {
            int root=find(node);
            // 条件判断
            if(root==node&&!pinned[root])free++;
        }
        System.out.println("YES");
        System.out.println(free/2);
    }
}

