// 题目：护栏补强
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(L(T+1))；空间 O(L)

import java.io.*;
import java.util.*;
public class Main {
    // 核心方法：feasible
    static boolean feasible(long[] h,long ops,long width,long target) {
        int n=h.length;
        long[] expire=new long[n+1];
        long active=0,used=0;
        // 枚举位置 i
        for(int i=0;i<n;i++) {
            active+=expire[i];
            long cur=h[i]+active;
            // 条件判断
            if(cur>=target)continue;
            long need=target-cur;
            used+=need;
            // 条件判断
            if(used>ops)return false;
            active+=need;
            int end=(int)Math.min((long)n,(long)i+width);
            expire[end]-=need;
        }
        // 返回结果
        return true;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] a)throws IOException {
        Scanner sc = new Scanner(System.in);
        int len=sc.nextInt();
        long ops=sc.nextLong(),width=sc.nextLong();
        long[] h=new long[len];
        long mn=Long.MAX_VALUE;
        // 枚举位置 i
        for(int i=0;i<len;i++) {
            h[i]=sc.nextLong();
            // 条件判断
            if(h[i]<mn)mn=h[i];
        }
        long low=mn,high=mn+ops;
        // 循环处理
        while(low<high) {
            long mid=(low+high+1)/2;
            // 条件判断
            if(feasible(h,ops,width,mid))low=mid;
            else high=mid-1;
        }
        System.out.println(low);
    }
}

