    static int[] par,sz;
    // 核心方法：find
    static int find(int x) {
        // 循环处理
        while(par[x]!=x) {
            par[x]=par[par[x]];
            x=par[x];
        }
        // 返回结果
        return x;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] a)throws IOException {
        int n=nextInt(),m=nextInt();
        long[] cost=new long[n];
        // 枚举位置 i
        for(int i=0;i<n;i++)cost[i]=nextLong();
        int totalEdges=n+m;
        long[][] edges=new long[totalEdges][3];
        int ei=0;
        // 枚举位置 i
        for(int i=0;i<n;i++) {
            edges[ei][0]=cost[i];
            edges[ei][1]=0;
            edges[ei][2]=i+1;
            ei++;
        }
        // 枚举位置 i
        for(int i=0;i<m;i++) {
            int u=nextInt(),v=nextInt();
            long w=nextLong();
            edges[ei][0]=w;
            edges[ei][1]=u;
            edges[ei][2]=v;
            ei++;
        }
        Arrays.sort(edges,(p,q)-> {
            // 条件判断
            if(p[0]!=q[0])return Long.compare(p[0],q[0]);if(p[1]!=q[1])return Long.compare(p[1],q[1]);return Long.compare(p[2],q[2]);
        }
        );
        par=new int[n+1];
        sz=new int[n+1];
        Arrays.fill(sz,1);
        // 枚举位置 i
        for(int i=0;i<=n;i++)par[i]=i;
        long total=0;
        int picked=0;
        // 循环处理
        for(long[] e:edges) {
            int u=find((int)e[1]),v=find((int)e[2]);
            // 条件判断
            if(u==v)continue;
            // 条件判断
            if(sz[u]<sz[v]) {
                int tmp=u;
                u=v;
                v=tmp;
            }
            par[v]=u;
            sz[u]+=sz[v];
            total+=e[0];
            picked++;
            // 条件判断
            if(picked==n)break;
        }
        System.out.println(total);
    }
}

