// 算法：堆 / 优先队列
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(n n)，每次判定做常数次堆操作，左右端点总移动次数为 O(n)；空间 O(n)，两个堆和区间数组

import java.io.*;
import java.util.*;
public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    static final long INF=Long.MAX_VALUE/4;
    // 核心方法：topTwo
    static long[] topTwo(PriorityQueue<long[]> h,long lo) {
        // 循环处理
        while(!h.isEmpty()&&h.peek()[1]<lo)h.poll();
        long[] first=h.poll();
        // 循环处理
        while(!h.isEmpty()&&h.peek()[1]<lo)h.poll();
        long second=h.isEmpty()?INF:h.peek()[0];
        h.add(first);
        // 返回结果
        return new long[] {
            first[0],first[1],second
        }
        ;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] a)throws IOException {
        int n=nextInt();
        long[][] iv=new long[n][2];
        // 枚举位置 i
        for(int i=0;i<n;i++) {
            iv[i][0]=nextLong();
            iv[i][1]=nextLong();
        }
        PriorityQueue<long[]> maxLeft=new PriorityQueue<>((p,q)-> {
            // 条件判断
            if(p[0]!=q[0])return Long.compare(p[0],q[0]);return Long.compare(p[1],q[1]);
        }
        );
        PriorityQueue<long[]> minRight=new PriorityQueue<>((p,q)-> {
            // 条件判断
            if(p[0]!=q[0])return Long.compare(p[0],q[0]);return Long.compare(p[1],q[1]);
        }
        );
        int lo=0;
        int ans=0;
        // 循环处理
        for(int hi=0;hi<n;hi++) {
            maxLeft.add(new long[] {
                -iv[hi][0],hi
            }
            );
            minRight.add(new long[] {
                iv[hi][1],hi
            }
            );
            // 循环处理
            while(lo<hi) {
                long[] r1=topTwo(maxLeft,lo);
                long negLeft=r1[0];
                long i=r1[1];
                long negSecond=r1[2];
                long[] r2=topTwo(minRight,lo);
                long smallRight=r2[0];
                long j=r2[1];
                long secondRight=r2[2];
                // 条件判断
                if(i==j||-negSecond<=smallRight||-negLeft<=secondRight)break;
                lo++;
            }
            // 条件判断
            if(hi-lo+1>ans)ans=hi-lo+1;
        }
        System.out.println(ans);
    }
}

