// 题目：环线巡游巡检全部道路的最小花费
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O((n+m)(n))，按编号读入即为处理顺序，树上两遍扫描均为 O(n)；空间 O(n+m)，重构树不超过 2n-1 个节点，另保存输入边

import java.io.*;
import java.util.*;
public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    // 核心方法：find
    static int find(int[] dsu,int x) {
        // 循环处理
        while(dsu[x]!=x) {
            dsu[x]=dsu[dsu[x]];
            x=dsu[x];
        }
        // 返回结果
        return x;
    }
    // 核心方法：minimumTour
    static long minimumTour(int n,int[][] edges) {
        int limit=2*n+1;
        long INF=Long.MAX_VALUE/4;
        int[] parent=new int[limit],left=new int[limit],right=new int[limit];
        long[] price=new long[limit];
        Arrays.fill(price,INF);
        int[] odd=new int[limit];
        int[] dsu=new int[n+1];
        // 枚举位置 i
        for(int i=0;i<=n;i++)dsu[i]=i;
        int[] size=new int[n+1];
        Arrays.fill(size,1);
        int[] nodeOf=new int[n+1];
        // 枚举位置 i
        for(int i=0;i<=n;i++)nodeOf[i]=i;
        int count=n;
        long total=0;
        // 循环处理
        for(int[] e:edges) {
            int u=e[0],v=e[1],w=e[2];
            total+=w;
            odd[u]^=1;
            odd[v]^=1;
            int aa=find(dsu,u),bb=find(dsu,v);
            // 条件判断
            if(aa==bb) {
                int node=nodeOf[aa];
                // 条件判断
                if(w<price[node])price[node]=w;
            } else {
                count++;
                int x=nodeOf[aa],y=nodeOf[bb];
                left[count]=x;
                right[count]=y;
                parent[x]=count;
                parent[y]=count;
                price[count]=w;
                // 条件判断
                if(size[aa]<size[bb]) {
                    int tmp=aa;
                    aa=bb;
                    bb=tmp;
                }
                dsu[bb]=aa;
                size[aa]+=size[bb];
                nodeOf[aa]=count;
            }
        }
        // 循环处理
        for(int node=count-1;node>=1;node--) {
            // 条件判断
            if(parent[node]!=0&&price[parent[node]]<price[node])price[node]=price[parent[node]];
        }
        // 循环处理
        for(int node=n+1;node<=count;node++) {
            int a=left[node],b=right[node];
            // 条件判断
            if(odd[a]==1&&odd[b]==1)total+=price[node];
            odd[node]=odd[a]^odd[b];
        }
        // 返回结果
        return total;
    }
    // 主函数：读取输入并输出答案
    public static void main(String[] a)throws IOException {
        int tests=nextInt();
        StringBuilder out=new StringBuilder();
        // 循环处理
        for(int t=0;t<tests;t++) {
            int n=nextInt(),m=nextInt();
            int[][] edges=new int[m][3];
            // 枚举位置 i
            for(int i=0;i<m;i++) {
                edges[i][0]=nextInt();
                edges[i][1]=nextInt();
                edges[i][2]=nextInt();
            }
            out.append(minimumTour(n,edges));
            // 条件判断
            if(t+1<tests)out.append((char)10);
        }
        System.out.print(out);
    }
}

