// 题目：格子行走翻转
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）
// 复杂度：时间 筛法与历次扩容重建合计为 O(B B)；每个人只计算至多两个新落点并执行一次翻转，合计为 O(n B)；空间 O(B+n)，用于质数标记、当前颜色、树状数组和路径数组

import java.io.*;
import java.util.*;
public class Main{
 static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
 static StringTokenizer st;
 static String next() throws IOException {
  while (st == null || !st.hasMoreTokens()) {
   String line = br.readLine();
   if (line == null) return null;
   st = new StringTokenizer(line);
  }
  return st.nextToken();
 }
 static int nextInt() throws IOException { return Integer.parseInt(next()); }
 static long nextLong() throws IOException { return Long.parseLong(next()); }
 static class DynamicBoard{
  int limit;HashSet<Integer> flipped=new HashSet<>();boolean[] isPrime;byte[] current;int[] tree;
  DynamicBoard(int initialLimit){limit=Math.max(16,initialLimit);rebuild();}
  void add(int index,int delta){while(index<=limit){tree[index]+=delta;index+=index&-index;}}
  int prefixBlack(int index){int total=0;while(index>0){total+=tree[index];index-=index&-index;}return total;}
  boolean[] sieve(int lim){boolean[] isP=new boolean[lim+1];Arrays.fill(isP,true);isP[0]=false;if(lim>=1)isP[1]=false;for(int p=2;(long)p*p<=lim;p++)if(isP[p])for(long m=(long)p*p;m<=lim;m+=p)isP[(int)m]=false;return isP;}
  void rebuild(){isPrime=sieve(limit);current=new byte[limit+1];for(int i=1;i<=limit;i++)current[i]=(byte)(isPrime[i]?1:0);for(int pos:flipped)if(pos<=limit)current[pos]^=1;tree=new int[limit+1];for(int pos=1;pos<=limit;pos++){tree[pos]+=current[pos];int parent=pos+(pos&-pos);if(parent<=limit)tree[parent]+=tree[pos];}}
  void expand(){limit*=2;rebuild();}
  void toggle(int position){byte old=current[position];current[position]^=1;add(position,old==0?1:-1);if(flipped.contains(position))flipped.remove(position);else flipped.add(position);}
  int findByOrder(int order,boolean wantBlack){int index=0,blackBefore=0;int step=Integer.highestOneBit(limit);while(step>0){int nextIndex=index+step;if(nextIndex<=limit){int nextBlack=blackBefore+tree[nextIndex];int nextCount=wantBlack?nextBlack:nextIndex-nextBlack;if(nextCount<order){index=nextIndex;blackBefore=nextBlack;}}step>>=1;}return index+1;}
  int nextPosition(int position,boolean wantBlack){while(true){int blackBefore=prefixBlack(position);int countBefore=wantBlack?blackBefore:position-blackBefore;int totalBlack=prefixBlack(limit);int totalCount=wantBlack?totalBlack:limit-totalBlack;if(totalCount>countBefore)return findByOrder(countBefore+1,wantBlack);expand();}}
 }
 // 核心方法：solveCase
 static int[] solveCase(String instructions){
  int n=instructions.length();
  DynamicBoard board=new DynamicBoard(Math.max(64,8*n+16));
  int[] path=new int[n+1];path[0]=1;
  // 循环处理
  for(int k=1;k<=n;k++){
   // 条件判断
   if(k>1)path[k-1]=board.nextPosition(path[k-2],instructions.charAt(k-2)=='1');
   path[k]=board.nextPosition(path[k-1],instructions.charAt(k-1)=='1');
   board.toggle(path[k]);
  }
  int[] answer=board.flipped.stream().mapToInt(Integer::intValue).sorted().toArray();
  // 返回结果
  return answer;
 }
 // 主函数：读取输入并输出答案
    public static void main(String[] args)throws IOException{
  int t=nextInt();
  StringBuilder out=new StringBuilder();char NL=(char)10;
  // 循环处理
  for(int tc=0;tc<t;tc++){
   int n=nextInt();
   String s=next();
   // 条件判断
   if(s.length()>n)s=s.substring(0,n);
   int[] ans=solveCase(s);
   out.append(ans.length).append(NL);
   // 枚举位置 i
   for(int i=0;i<ans.length;i++){if(i>0)out.append(' ');out.append(ans[i]);}
   // 条件判断
   if(tc<t-1)out.append(NL);
  }
  System.out.print(out);
 }
}

