 // 核心方法：minOperations
 static int minOperations(int[] hardness){
  int n=hardness.length;int[] dp=new int[n+1];
  int maxValue=Integer.MIN_VALUE,minValue=Integer.MAX_VALUE,maxPos=0,minPos=0;
  // 循环处理
  for(int k=1;k<=n;k++){
   int value=hardness[k-1];
   // 条件判断
   if(value>=maxValue){maxValue=value;maxPos=k;}
   // 条件判断
   if(value<=minValue){minValue=value;minPos=k;}
   dp[k]=1+Math.min(dp[maxPos-1],dp[minPos-1]);
  }
  // 返回结果
  return dp[n];
 }
