public class Main{
 static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
 static StringTokenizer st;
 static String next() throws IOException {
  while (st == null || !st.hasMoreTokens()) {
   String line = br.readLine();
   if (line == null) return null;
   st = new StringTokenizer(line);
  }
  return st.nextToken();
 }
 static int nextInt() throws IOException { return Integer.parseInt(next()); }
 static long nextLong() throws IOException { return Long.parseLong(next()); }
 // 核心方法：totalWalkLength
 static long totalWalkLength(int n,int modulus,int[] values){
  long[] prefix=new long[2*n];long current=0;
  // 枚举位置 i
  for(int i=1;i<2*n;i++){current=(current+values[(i-1)%n])%modulus;prefix[i]=current;}
  HashSet<Long> seen=new HashSet<>();int right=0;long total=0;
  // 循环处理
  for(int left=1;left<=n;left++){
   int limit=left+n-1;
   // 循环处理
   while(right<limit&&!seen.contains(prefix[right+1])){right++;seen.add(prefix[right]);}
   total+=right-left+1;
   seen.remove(prefix[left]);
  }
  // 返回结果
  return total;
 }
 // 主函数：读取输入并输出答案
    public static void main(String[] args)throws IOException{
  int t=nextInt();StringBuilder out=new StringBuilder();char NL=(char)10;
  // 循环处理
  for(int tc=0;tc<t;tc++){
   int n=nextInt(),modulus=nextInt();int[] values=new int[n];for(int i=0;i<n;i++)values[i]=nextInt();
   out.append(totalWalkLength(n,modulus,values));if(tc<t-1)out.append(NL);
  }
  System.out.print(out);
 }
}

