// 题目：最大乘积操作
// 算法：二分查找
// 模式：ACM（stdin/stdout）
// 复杂度：时间 排序为 O(n n)；二分水平线进行 O( V) 次检查，每次用二分查找计算代价，耗时 O( n)；最后计算未改变部分的乘积为 O(n)；空间 O(n)，用于排序后的数组和前缀和

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    static final long MOD=1000000007L;
 // 核心方法：bisectRight
 static int bisectRight(int[] a,long x){int lo=0,hi=a.length;while(lo<hi){int mid=(lo+hi)>>>1;if(a[mid]<=x)lo=mid+1;else hi=mid;}return lo;}
 // 核心方法：bisectLeft
 static int bisectLeft(int[] a,long x){int lo=0,hi=a.length;while(lo<hi){int mid=(lo+hi)>>>1;if(a[mid]<x)lo=mid+1;else hi=mid;}return lo;}
 // 核心方法：modPow
 static long modPow(long base,long exp){base%=MOD;if(base<0)base+=MOD;long r=1;while(exp>0){if((exp&1)==1)r=r*base%MOD;base=base*base%MOD;exp>>=1;}return r;}
 // 核心方法：costToLevel
 static long costToLevel(int[] values,long[] prefix,int n,long level){int fg=bisectRight(values,level);long highSum=prefix[n]-prefix[fg];long highCount=n-fg;return highSum-level*highCount;}
 // 核心方法：maxProduct
 static long maxProduct(int[] values,long operationCount){
  Arrays.sort(values);int n=values.length;
  long[] prefix=new long[n+1];for(int i=0;i<n;i++)prefix[i+1]=prefix[i]+values[i];
  // 条件判断
  if(operationCount>=prefix[n]-n)return 1;
  long low=1,high=values[n-1];
  // 循环处理
  while(low<high){long mid=(low+high)/2;if(costToLevel(values,prefix,n,mid)<=operationCount)high=mid;else low=mid+1;}
  long level=low;
  long remaining=operationCount-costToLevel(values,prefix,n,level);
  int firstLevel=bisectLeft(values,level);
  int levelCount=n-firstLevel;
  long result=1;
  // 枚举位置 i
  for(int i=0;i<firstLevel;i++)result=result*values[i]%MOD;
  result=result*modPow(level,(long)levelCount-remaining)%MOD;
  result=result*modPow(level-1,remaining)%MOD;
  // 返回结果
  return result;
 }
 // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
  int t=nextInt();StringBuilder out=new StringBuilder();char NL=(char)10;
  // 循环处理
  for(int tc=0;tc<t;tc++){
   int n=nextInt();long op=nextLong();int[] values=new int[n];for(int i=0;i<n;i++)values[i]=nextInt();
   out.append(maxProduct(values,op));if(tc<t-1)out.append(NL);
  }
  System.out.print(out);
 }
}

