        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
 // 核心方法：vanishRounds
 static int[] vanishRounds(String brackets){
  int len=brackets.length();int[] depths=new int[len];int currentDepth=0,maxDepth=0;
  // 枚举位置 i
  for(int i=0;i<len;i++){
   char ch=brackets.charAt(i);int depth;
   // 条件判断
   if(ch=='('){currentDepth++;depth=currentDepth;}else{depth=currentDepth;currentDepth--;}
   depths[i]=depth;if(depth>maxDepth)maxDepth=depth;
  }
  int[] res=new int[len];for(int i=0;i<len;i++)res[i]=maxDepth-depths[i]+1;return res;
 }
 // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
