  for(int tc=0;tc<t;tc++){
   int n=nextInt();String s=next();if(s.length()>n)s=s.substring(0,n);
   int[] ans=vanishRounds(s);
   // 枚举位置 i
   for(int i=0;i<ans.length;i++){if(i>0)out.append(' ');out.append(ans[i]);}
   // 条件判断
   if(tc<t-1)out.append(NL);
  }
  System.out.print(out);
 }
}

