            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
 static final long MOD=1000000007L;
 static final int MAXN=200000;
 static int[] SPF;
 // 核心方法：buildSPF
 static int[] buildSPF(int limit){int[] spf=new int[limit+1];for(int i=0;i<=limit;i++)spf[i]=i;if(limit>=1)spf[1]=1;for(int i=2;(long)i*i<=limit;i++)if(spf[i]==i)for(long j=(long)i*i;j<=limit;j+=i)if(spf[(int)j]==(int)j)spf[(int)j]=i;return spf;}
 // 核心方法：minimumPeriod
 static int minimumPeriod(char[] c){
  int len=c.length;int[] prefix=new int[len];
  // 枚举位置 i
  for(int i=1;i<len;i++){int matched=prefix[i-1];while(matched>0&&c[i]!=c[matched])matched=prefix[matched-1];if(c[i]==c[matched])matched++;prefix[i]=matched;}
  int candidate=len-prefix[len-1];
  // 条件判断
  if(len%candidate==0)return candidate;return len;
 }
 // 核心方法：modPow
 static long modPow(long base,long exp){base%=MOD;long r=1;while(exp>0){if((exp&1)==1)r=r*base%MOD;base=base*base%MOD;exp>>=1;}return r;}
 // 核心方法：solveCase
 static long solveCase(int n,String string,int[] permutation){
  boolean[] visited=new boolean[n];
  HashMap<Integer,Integer> maxExp=new HashMap<>();
  // 循环处理
  for(int start=0;start<n;start++){
   // 条件判断
   if(visited[start])continue;
   StringBuilder sb=new StringBuilder();
   int current=start;
   // 循环处理
   while(!visited[current]){visited[current]=true;sb.append(string.charAt(current));current=permutation[current];}
   char[] cyc=sb.toString().toCharArray();
   int period=minimumPeriod(cyc);
   // 循环处理
   while(period>1){int prime=SPF[period];int exponent=0;while(period%prime==0){period/=prime;exponent++;}if(exponent>maxExp.getOrDefault(prime,0))maxExp.put(prime,exponent);}
  }
  long answer=1;
  // 循环处理
  for(Map.Entry<Integer,Integer> e:maxExp.entrySet())answer=answer*modPow(e.getKey(),e.getValue())%MOD;
  // 返回结果
  return answer;
 }
 // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
  SPF=buildSPF(MAXN);
  int t=nextInt();StringBuilder out=new StringBuilder();char NL=(char)10;
  // 循环处理
  for(int tc=0;tc<t;tc++){
   int n=nextInt();String string=next();int[] permutation=new int[n];
   // 枚举位置 i
   for(int i=0;i<n;i++)permutation[i]=nextInt()-1;
   out.append(solveCase(n,string,permutation));if(tc<t-1)out.append(NL);
  }
  System.out.print(out);
 }
}

