// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {
 // 核心方法：shuffleTimes
 static void shuffleTimes(int[] p,long k){
  int n=p.length,i=0;long done=0;
  // 循环处理
  while(done<k){
   // 循环处理
   while(i+1<n&&p[i]<=p[i+1])i++;
   // 条件判断
   if(i+1>=n)break;
   int tmp=p[i];p[i]=p[i+1];p[i+1]=tmp;done++;
   // 条件判断
   if(i>0)i--;
  }
 }
 // 主函数：读取输入并输出答案
