public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
 // 核心方法：bestSum
 static long bestSum(int[] a){
  int n=a.length;if(n<=1)return 0;
  Integer[] arr=new Integer[n];for(int i=0;i<n;i++)arr[i]=a[i];
  Arrays.sort(arr,Collections.reverseOrder());
  long[] pref=new long[n];for(int t=1;t<n;t++)pref[t]=pref[t-1]+arr[t-1];
  int peak=1;for(int t=2;t<n;t++)if(pref[t]>pref[peak])peak=t;
  long sumPref=0,minSumPref=0;
  // 循环处理
  for(int k=1;k<peak;k++){sumPref+=pref[k];minSumPref=Math.min(minSumPref,sumPref);}
  sumPref+=pref[peak];
  long best=(sumPref-minSumPref)+(long)(n-1-peak)*pref[peak];
  // 枚举阶段 j
  for(int j=peak+1;j<n;j++)best=Math.max(best,(long)(n-j)*pref[j]);
  // 返回结果
  return best;
 }
 // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
  int t=nextInt();StringBuilder out=new StringBuilder();char NL=(char)10;
  // 循环处理
  for(int tc=0;tc<t;tc++){int n=nextInt();int[] a=new int[n];for(int i=0;i<n;i++)a[i]=nextInt();out.append(bestSum(a));if(tc<t-1)out.append(NL);}
  System.out.print(out);
 }
}

