// 复杂度：时间 左右两次单调队列扫描均为 O(n)，总计 O(n)；空间 最大值数组和队列共占用 O(n)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
 static final long NEG=Long.MIN_VALUE/4;
 // 核心方法：leftWindowMax
 static long[] leftWindowMax(long[] a,int d){
  int n=a.length;long[] result=new long[n];Arrays.fill(result,NEG);
  int[] dq=new int[n];int head=0,tail=0;
  // 枚举位置 i
  for(int i=0;i<n;i++){
   // 循环处理
   while(head<tail&&dq[head]<i-d)head++;
   // 条件判断
   if(head<tail)result[i]=a[dq[head]];
   // 循环处理
   while(head<tail&&a[dq[tail-1]]<=a[i])tail--;
   dq[tail++]=i;
  }
  // 返回结果
  return result;
 }
 // 核心方法：reverse
 static long[] reverse(long[] a){int n=a.length;long[] r=new long[n];for(int i=0;i<n;i++)r[i]=a[n-1-i];return r;}
 // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
  int t=nextInt();StringBuilder out=new StringBuilder();char NL=(char)10;
