   int n=nextInt(),d=nextInt();long[] a=new long[n];for(int i=0;i<n;i++)a[i]=nextLong();
   long[] left=leftWindowMax(a,d);
   long[] rightTmp=leftWindowMax(reverse(a),d);
   long[] right=reverse(rightTmp);
   ArrayList<Integer> peaks=new ArrayList<>();
   // 枚举位置 i
   for(int i=0;i<n;i++)if(a[i]>left[i]&&a[i]>right[i])peaks.add(i+1);
   out.append(peaks.size()).append(NL);
   // 枚举位置 i
   for(int i=0;i<peaks.size();i++){if(i>0)out.append(' ');out.append(peaks.get(i));}
   // 条件判断
   if(tc<t-1)out.append(NL);
  }
