// 复杂度：时间 单组总计 O((n+m_f+m_s)(m_f+m_s+1)), 空间复杂度 ：总计 O(n+m_f+m_s)；空间 总计 O(n+m_f+m_s)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
 // 核心方法：rangeMaximums
 static long[] rangeMaximums(int n,ArrayList<long[]> segs){
  ArrayList<ArrayList<long[]>> starts=new ArrayList<>();
  // 枚举位置 i
  for(int i=0;i<=n+1;i++)starts.add(new ArrayList<>());
  // 循环处理
  for(long[] s:segs)starts.get((int)s[0]).add(new long[]{s[2],s[1]});
  long[] result=new long[n+1];
  PriorityQueue<long[]> heap=new PriorityQueue<>((x,y)->{if(x[0]!=y[0])return Long.compare(y[0],x[0]);return Long.compare(x[1],y[1]);});
  // 枚举位置 i
  for(int i=1;i<=n;i++){
   // 循环处理
   for(long[] e:starts.get(i))heap.add(new long[]{e[0],e[1]});
   // 循环处理
   while(!heap.isEmpty()&&heap.peek()[1]<i)heap.poll();
   // 条件判断
   if(!heap.isEmpty())result[i]=heap.peek()[0];
  }
  // 返回结果
  return result;
 }
 // 核心方法：rangeMinimums
 static long[] rangeMinimums(int n,ArrayList<long[]> segs){
  ArrayList<ArrayList<long[]>> starts=new ArrayList<>();
  // 枚举位置 i
  for(int i=0;i<=n+1;i++)starts.add(new ArrayList<>());
  // 循环处理
  for(long[] s:segs)starts.get((int)s[0]).add(new long[]{s[2],s[1]});
  long[] result=new long[n+1];Arrays.fill(result,Long.MAX_VALUE/4);
  PriorityQueue<long[]> heap=new PriorityQueue<>((x,y)->{if(x[0]!=y[0])return Long.compare(x[0],y[0]);return Long.compare(x[1],y[1]);});
  // 枚举位置 i
  for(int i=1;i<=n;i++){
   // 循环处理
   for(long[] e:starts.get(i))heap.add(new long[]{e[0],e[1]});
   // 循环处理
   while(!heap.isEmpty()&&heap.peek()[1]<i)heap.poll();
   // 条件判断
   if(!heap.isEmpty())result[i]=heap.peek()[0];
  }
  // 返回结果
  return result;
 }
 // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
  int t=nextInt();StringBuilder out=new StringBuilder();char NL=(char)10;
  // 循环处理
  for(int tc=0;tc<t;tc++){
   int n=nextInt(),fogCount=nextInt(),spotCount=nextInt();
   long[] initial=new long[n];for(int i=0;i<n;i++)initial[i]=nextLong();
   ArrayList<long[]> fog=new ArrayList<>();
   // 枚举位置 i
   for(int i=0;i<fogCount;i++){long l=nextLong(),r=nextLong(),u=nextLong();fog.add(new long[]{l,r,u});}
   ArrayList<long[]> spot=new ArrayList<>();
   // 枚举位置 i
   for(int i=0;i<spotCount;i++){long l=nextLong(),r=nextLong(),lo=nextLong();spot.add(new long[]{l,r,lo});}
   long[] lowerBounds=rangeMaximums(n,spot);
   long[] upperBounds=rangeMinimums(n,fog);
   // 枚举位置 i
   for(int i=1;i<=n;i++){
    long brightness=Math.max(initial[i-1],lowerBounds[i]);
    brightness=Math.min(brightness,upperBounds[i]);
    // 条件判断
    if(i>1)out.append(' ');out.append(brightness);
   }
   // 条件判断
