// 题目：循环血量怪物最少讨伐天数
// 算法：二分查找
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(n n+(d_+m) n), 在给定范围内也可简写为 O(n n)；空间 O(n)，用于阈值数组和前缀和

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
 // 核心方法：bisectRight
 static int bisectRight(long[] a,long x){int lo=0,hi=a.length;while(lo<hi){int mid=(lo+hi)>>>1;if(a[mid]<=x)lo=mid+1;else hi=mid;}return lo;}
 // 核心方法：successfulDays
 static long successfulDays(long stage,long[] thresholds,long[] prefix){
  // 条件判断
  if(stage<0)return 0;
  int count=bisectRight(thresholds,stage);
  // 返回结果
  return (long)count*(stage+1)-prefix[count];
 }
 // 核心方法：minDays
 static long minDays(int n,int monsterCount,long initialPower,long[] health){
  long[] thresholds=new long[n];
  // 枚举位置 i
  for(int i=0;i<n;i++){long v=health[i]-initialPower;thresholds[i]=v>0?v:0;}
  Arrays.sort(thresholds);
  long[] prefix=new long[n+1];for(int i=0;i<n;i++)prefix[i+1]=prefix[i]+thresholds[i];
  long low=0,high=thresholds[0]+monsterCount-1;
  // 循环处理
  while(low<high){long mid=(low+high)/2;if(successfulDays(mid,thresholds,prefix)>=monsterCount)high=mid;else low=mid+1;}
  long stage=low;
  long remaining=monsterCount-successfulDays(stage-1,thresholds,prefix);
  long power=initialPower+stage;
  // 循环处理
  for(int index=1;index<=n;index++){if(health[index-1]<=power){remaining--;if(remaining==0)return stage*n+index;}}
  // 返回结果
  return stage*n+n;
 }
 // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
  int t=nextInt();StringBuilder out=new StringBuilder();char NL=(char)10;
  // 循环处理
  for(int tc=0;tc<t;tc++){
   int n=nextInt();int mc=nextInt();long ip=nextLong();long[] health=new long[n];for(int i=0;i<n;i++)health[i]=nextLong();
   out.append(minDays(n,mc,ip,health));if(tc<t-1)out.append(NL);
  }
  System.out.print(out);
 }
}

