// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 每组为 O( n)，全部测试为 O(T n)；空间 除输入和输出缓冲区外为 O(1)；计入缓冲区为 O(T)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
 static final long MOD=1000000007L;
 // 核心方法：pathWeightSum
 static long pathWeightSum(long n){
  long last=n-1;long answer=0;
  // 循环处理
  for(int t=0;t<=60;t++){
   long first=(1L<<t)-1;
   // 条件判断
   if(first>last)break;
   long step=1L<<(t+1);
   long count=(last-first)/step+1;
   // 条件判断
   if(t==0)count-=1;
   answer=(answer+(count%MOD)*((step-1)%MOD))%MOD;
  }
  // 返回结果
  return answer;
 }
 // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
  int t=nextInt();StringBuilder out=new StringBuilder();char NL=(char)10;
