// 题目：定长区间加一最大化最小值
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(n log(k+2))，包含 k=0 时的输入和最小值扫描；空间 O(n)

import java.io.*;
import java.util.*;

public class Main {
 // 核心方法：check
 static boolean check(long[] a,int n,int w,long k,long target){
  long[] expire=new long[n+1];int last=n-w;long add=0;long used=0;
  // 枚举位置 i
  for(int i=0;i<n;i++){
   add-=expire[i];
   long need=target-a[i]-add;
   // 条件判断
   if(need>0){used+=need;if(used>k)return false;add+=need;int start=i<last?i:last;expire[start+w]+=need;}
  }
  // 返回结果
  return true;
 }
 // 核心方法：maxMinValue
 static long maxMinValue(long[] a,int n,int w,long k){
  long lo=a[0];for(int i=1;i<n;i++)if(a[i]<lo)lo=a[i];
  long hi=lo+k;
  // 循环处理
  while(lo<hi){long mid=lo+(hi-lo+1)/2;if(check(a,n,w,k,mid))lo=mid;else hi=mid-1;}
  // 返回结果
  return lo;
 }
 // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
  int n=sc.nextInt(),w=sc.nextInt();long k=sc.nextLong();
  long[] a=new long[n];for(int i=0;i<n;i++)a[i]=sc.nextLong();
  System.out.print(maxMinValue(a,n,w,k));
 }
}

// 题目：区间异或和最小右端点
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(1)；空间 O(1)

import java.io.*;
import java.util.*;

public class Main {

    // 核心方法：prefixXor
    static long prefixXor(long n) {
        // 条件判断
        if (n < 0) return 0;
        long r = n % 4;
        // 条件判断
        if (r == 0) return n;
        // 条件判断
        if (r == 1) return 1;
        // 条件判断
        if (r == 2) return n + 1;
        // 返回结果
        return 0;
    }

    // 核心方法：minRight
    static long minRight(long x, long z) {
        long target = z ^ prefixXor(x - 1);
        long best = -1;
        long[] cand = {x, x + 1, x + 2, x + 3, target - 1, target};
        // 循环处理
        for (long y : cand) {
            // 条件判断
            if (y >= x && prefixXor(y) == target) {
                // 条件判断
                if (best == -1 || y < best) best = y;
            }
        }
        // 返回结果
        return best;
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long z = sc.nextLong();
        System.out.println(minRight(x, z));
    }
}

