// 题目：拆除炸弹的最少按钮次数
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 期望 O(n+d)，即期望 O(n)；空间 O(d)

import java.io.*;
import java.util.*;

public class Main {

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long target = sc.nextLong();
        HashMap<Long, Integer> count = new HashMap<>();
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            long v = sc.nextLong();
            count.put(v, count.getOrDefault(v, 0) + 1);
        }
        long answer = 0;
        // 循环处理
        for (Map.Entry<Long, Integer> e : count.entrySet()) {
            long value = e.getKey();
            int frequency = e.getValue();
            long other = target - value;
            // 条件判断
            if (!count.containsKey(other)) continue;
            // 条件判断
            if (value == other) answer += frequency - 1;
            else if (value < other) answer += Math.min(frequency, count.get(other));
        }
        System.out.println(answer);
    }
}

