// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {

    static final long MOD = 1000000007L;

    // 核心方法：buildAnswers
    static long[] buildAnswers(int maxn) {
        long[][] f = new long[4][maxn + 1];
        long[] res = new long[maxn + 1];
        f[1][1] = 26 % MOD;
        res[1] = f[1][1];
        // 枚举位置 i
        for (int i = 2; i <= maxn; i++) {
            f[1][i] = 25 * ((f[1][i - 1] + f[2][i - 1] + f[3][i - 1]) % MOD) % MOD;
            f[2][i] = f[1][i - 1];
            f[3][i] = f[2][i - 1];
            res[i] = (f[1][i] + f[2][i] + f[3][i]) % MOD;
        }
        // 返回结果
        return res;
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        int[] queries = new int[t];
        int maxn = 1;
        // 枚举位置 i
        for (int i = 0; i < t; i++) {
            queries[i] = sc.nextInt();
            // 条件判断
            if (queries[i] > maxn) maxn = queries[i];
        }
        long[] answers = buildAnswers(maxn);
        // 循环处理
        for (int n : queries) System.out.println(answers[n]);
    }
}

