items.books/ai-exam/ai-2026/科大讯飞/111-窗口内互异的重排序:
// 题目：窗口内互异的重排序列
// 算法：堆 / 优先队列
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(n n)，排序与堆调度均在此上界内，分行填充为线性；空间 O(n)

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    static class Group implements Comparable<Group> {
        int value, count;
        Group(int v, int c) { value = v; count = c; }
        public int compareTo(Group o) {
            // 条件判断
            if (count != o.count) return Integer.compare(o.count, count);
            // 返回结果
            return Integer.compare(value, o.value);
        }
    }

    // 核心方法：rearrange
    static int[] rearrange(int[] a, int k) {
        int n = a.length;
        HashMap<Integer, Integer> counter = new HashMap<>();
        // 循环处理
        for (int v : a) counter.put(v, counter.getOrDefault(v, 0) + 1);
        ArrayList<Group> groups = new ArrayList<>();
        // 循环处理
        for (Map.Entry<Integer, Integer> e : counter.entrySet())
            groups.add(new Group(e.getKey(), e.getValue()));
        Collections.sort(groups);
        int frequency = groups.get(0).count;
        int tied = 0;
        // 循环处理
        for (Group g : groups) if (g.count == frequency) tied++;
        // 条件判断
        if ((long) (frequency - 1) * k + tied > n) return null;
        // 条件判断
        if (frequency == 1) {
            int[] sorted = a.clone();
            Arrays.sort(sorted);
            // 返回结果
            return sorted;
        }
        PriorityQueue<int[]> available = new PriorityQueue<>(new Comparator<int[]>() {
            public int compare(int[] x, int[] y) {
                // 条件判断
                if (x[0] != y[0]) return Integer.compare(x[0], y[0]);
                // 返回结果
                return Integer.compare(x[1], y[1]);
            }
        });
        // 循环处理
        for (Group g : groups) available.add(new int[]{-g.count, g.value});
        ArrayDeque<int[]> cooling = new ArrayDeque<>();
        ArrayList<Integer> candidate = new ArrayList<>();
        // 枚举位置 i
        for (int i = 0; i < n; i++) {
            // 条件判断
            if (!cooling.isEmpty() && cooling.peekFirst()[0] <= i) {
                int[] c = cooling.pollFirst();
                available.add(new int[]{c[1], c[2]});
            }
            // 条件判断
            if (available.isEmpty()) break;
            int[] top = available.poll();
            int count = top[0];
            int value = top[1];
            candidate.add(value);
            // 条件判断
            if (count + 1 < 0) cooling.addLast(new int[]{i + k, count + 1, value});
        }
        // 条件判断
        if (candidate.size() == n) {
            int[] res = new int[n];
            // 枚举位置 i
            for (int i = 0; i < n; i++) res[i] = candidate.get(i);
            // 返回结果
            return res;
        }
        ArrayList<ArrayList<Integer>> rows = new ArrayList<>();
        // 枚举位置 i
        for (int i = 0; i < frequency; i++) rows.add(new ArrayList<>());
        // 循环处理
        for (int gi = 0; gi < tied; gi++) {
            int value = groups.get(gi).value;
            // 循环处理
            for (ArrayList<Integer> row : rows) row.add(value);
        }
        int rowIndex = 0;
        // 循环处理
        for (int gi = tied; gi < groups.size(); gi++) {
            int value = groups.get(gi).value;
            int count = groups.get(gi).count;
            // 循环处理
            for (int c = 0; c < count; c++) {
                rows.get(rowIndex).add(value);
                rowIndex = (rowIndex + 1) % (frequency - 1);
            }
        }
        int[] res = new int[n];
        int p = 0;
        // 循环处理
        for (ArrayList<Integer> row : rows) for (int v : row) res[p++] = v;
        // 返回结果
        return res;
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int k = nextInt();
        int[] a = new int[n];
        // 枚举位置 i
        for (int i = 0; i < n; i++) a[i] = nextInt();
        int[] result = rearrange(a, k);
        // 条件判断
        if (result == null) {
            System.out.println(-1);
        } else {
            StringBuilder sb = new StringBuilder();
            // 枚举位置 i
            for (int i = 0; i < result.length; i++) {
                // 条件判断
                if (i > 0) sb.append(' ');
                sb.append(result[i]);
            }
            System.out.println(sb.toString());
        }
    }
}

// 题目：TF-IDF 值计算
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(L)，其中 L 是全部语句的总词数；空间 O(L)，存放切分后的词列表与用于判重的集合

import java.io.*;
import java.util.*;
import java.math.BigDecimal;
import java.math.RoundingMode;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static String nextLine() throws IOException { return br.readLine(); }

    // 核心方法：extractQuoted
    static List<String> extractQuoted(String s) {
        List<String> res = new ArrayList<>();
        int i = 0;
        // 循环处理
        while (i < s.length()) {
            char c = s.charAt(i);
            // 条件判断
            if (c == (char) 39 || c == (char) 34) {
                char q = c;
                int j = i + 1;
                StringBuilder sb = new StringBuilder();
                // 循环处理
                while (j < s.length() && s.charAt(j) != q) { sb.append(s.charAt(j)); j++; }
                res.add(sb.toString());
                i = j + 1;
            } else {
                i++;
            }
        }
        // 返回结果
        return res;
    }

    // 核心方法：format3
    static String format3(double v) {
        BigDecimal bd = new BigDecimal(v).setScale(3, RoundingMode.HALF_EVEN);
        String s = bd.stripTrailingZeros().toPlainString();
        // 条件判断
        if (s.indexOf('.') < 0) s += ".0";
        // 返回结果
        return s;
    }

    // 核心方法：splitWords
    static String[] splitWords(String s) {
        s = s.trim();
        // 条件判断
        if (s.isEmpty()) return new String[0];
        StringTokenizer sw = new StringTokenizer(s);
        String[] arr = new String[sw.countTokens()];
        // 枚举位置 i
        for (int i = 0; i < arr.length; i++) arr[i] = sw.nextToken();
        // 返回结果
        return arr;
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String sentencesLine = nextLine();
        String queryLine = nextLine();
        List<String> sentences = extractQuoted(sentencesLine);
        List<String> q = extractQuoted(queryLine);
        String word = q.get(0);
        StringBuilder rest = new StringBuilder();
        boolean inQuote = false;
        char qc = 0;
        // 枚举位置 i
        for (int i = 0; i < queryLine.length(); i++) {
            char c = queryLine.charAt(i);
            // 条件判断
            if (inQuote) { if (c == qc) inQuote = false; continue; }
            // 条件判断
            if (c == (char) 39 || c == (char) 34) { inQuote = true; qc = c; continue; }
            rest.append(c);
        }
        int idx = 0;
        StringTokenizer qt = new StringTokenizer(rest.toString(), "[],() ");
        // 条件判断
        if (qt.hasMoreTokens()) idx = Integer.parseInt(qt.nextToken());
        int n = sentences.size();
        String[][] docs = new String[n][];
        // 枚举位置 i
        for (int i = 0; i < n; i++) docs[i] = splitWords(sentences.get(i));
        String[] target = docs[idx];
        int occurrences = 0;
        // 循环处理
        for (String w : target) if (w.equals(word)) occurrences++;
        double tf = (double) occurrences / target.length;
        int nw = 0;
        // 循环处理
        for (String[] d : docs) {
            // 循环处理
            for (String w : d) if (w.equals(word)) { nw++; break; }
        }
        double idf = Math.log((double) n / (nw + 1) + 1.0);
        System.out.println(format3(tf * idf));
    }
}

items.books/ai-exam/ai-2026/网易/113-二层感知机前向传播损失:
// 题目：二层感知机前向传播损失
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(hd+oh)，两次矩阵乘向量是全部开销，sigmoid 与损失都只是逐元素 O(h+o) 的运算；空间 O(hd+oh)，存放两个权重矩阵；中间结果 Z_1 与 h 只占 O(h+o)

import java.io.*;
import java.util.*;
import java.math.BigDecimal;
import java.math.RoundingMode;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static String nextLine() throws IOException { return br.readLine(); }

    static int pos = 0;
    static String src;

    // 核心方法：skipWs
    static void skipWs() { while (pos < src.length() && Character.isWhitespace(src.charAt(pos))) pos++; }

    // 核心方法：parseValue
    static Object parseValue() {
        skipWs();
        char c = src.charAt(pos);
        // 条件判断
        if (c == '(') return parseSeq(')');
        // 条件判断
        if (c == '[') return parseSeq(']');
        // 返回结果
        return parseNumber();
    }

    // 核心方法：parseSeq
    static List<Object> parseSeq(char close) {
        List<Object> list = new ArrayList<>();
        pos++;
        skipWs();
        // 条件判断
        if (src.charAt(pos) == close) { pos++; return list; }
        // 循环处理
        while (true) {
            list.add(parseValue());
            skipWs();
            char c = src.charAt(pos);
            // 条件判断
            if (c == ',') { pos++; continue; }
            // 条件判断
            if (c == close) { pos++; break; }
        }
        // 返回结果
        return list;
    }

    // 核心方法：parseNumber
    static Double parseNumber() {
        skipWs();
        int start = pos;
        // 条件判断
        if (src.charAt(pos) == '+' || src.charAt(pos) == '-') pos++;
        // 循环处理
        while (pos < src.length()) {
            char c = src.charAt(pos);
            // 条件判断
            if (Character.isDigit(c) || c == '.' || c == 'e' || c == 'E') pos++;
            else if ((c == '+' || c == '-') && pos > start && (src.charAt(pos - 1) == 'e' || src.charAt(pos - 1) == 'E')) pos++;
            else break;
        }
        // 返回结果
        return Double.parseDouble(src.substring(start, pos));
    }

    // 核心方法：toMatrix
    static double[][] toMatrix(Object o) {
        List<Object> rows = (List<Object>) o;
        double[][] m = new double[rows.size()][];
        // 枚举位置 i
        for (int i = 0; i < rows.size(); i++) {
            List<Object> row = (List<Object>) rows.get(i);
            m[i] = new double[row.size()];
            // 枚举阶段 j
            for (int j = 0; j < row.size(); j++) m[i][j] = (Double) row.get(j);
        }
        // 返回结果
        return m;
    }

    // 核心方法：toVector
    static double[] toVector(Object o) {
        List<Object> v = (List<Object>) o;
        double[] a = new double[v.size()];
        // 枚举位置 i
        for (int i = 0; i < v.size(); i++) a[i] = (Double) v.get(i);
        // 返回结果
        return a;
    }

    // 核心方法：matMul
    static double[][] matMul(double[][] A, double[][] B) {
        int n = A.length, p = B.length, m = B[0].length;
        double[][] C = new double[n][m];
        // 枚举位置 i
        for (int i = 0; i < n; i++)
            // 枚举阶段 j
            for (int j = 0; j < m; j++) {
                double s = 0;
                // 循环处理
                for (int k = 0; k < p; k++) s += A[i][k] * B[k][j];
                C[i][j] = s;
            }
        // 返回结果
        return C;
    }

    // 核心方法：addBias
    static double[][] addBias(double[][] M, Object b) {
        double[][] R = new double[M.length][];
        // 条件判断
        if (b instanceof Double) {
            double s = (Double) b;
            // 枚举位置 i
            for (int i = 0; i < M.length; i++) {
                R[i] = new double[M[i].length];
                // 枚举阶段 j
                for (int j = 0; j < M[i].length; j++) R[i][j] = M[i][j] + s;
            }
        } else {
            List<Object> bl = (List<Object>) b;
            // 条件判断
            if (!bl.isEmpty() && bl.get(0) instanceof List) {
                double[][] bm = toMatrix(b);
                // 枚举位置 i
                for (int i = 0; i < M.length; i++) {
                    R[i] = new double[M[i].length];
                    // 枚举阶段 j
                    for (int j = 0; j < M[i].length; j++) R[i][j] = M[i][j] + bm[i % bm.length][0];
                }
            } else {
                double[] bv = toVector(b);
                // 枚举位置 i
                for (int i = 0; i < M.length; i++) {
                    R[i] = new double[M[i].length];
                    // 枚举阶段 j
                    for (int j = 0; j < M[i].length; j++) R[i][j] = M[i][j] + bv[j % bv.length];
                }
            }
        }
        // 返回结果
        return R;
    }

    // 核心方法：sigmoid
    static double sigmoid(double z) { return 1.0 / (1.0 + Math.exp(-z)); }

    // 核心方法：format3
    static String format3(double v) {
        BigDecimal bd = new BigDecimal(v).setScale(3, RoundingMode.HALF_EVEN);
        String s = bd.stripTrailingZeros().toPlainString();
        // 条件判断
        if (s.indexOf('.') < 0) s += ".0";
        // 返回结果
        return s;
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        StringBuilder all = new StringBuilder();
        String l;
        // 循环处理
        while ((l = nextLine()) != null) all.append(l);
        src = all.toString();
        Object root = parseValue();
        List<Object> parts = (List<Object>) root;
        double[][] W1 = toMatrix(parts.get(0));
        double[][] W2 = toMatrix(parts.get(1));
        Object b = parts.get(2);
        double[][] X = toMatrix(parts.get(3));
        double[][] Y = toMatrix(parts.get(4));
        double[][] Z1 = addBias(matMul(W1, X), b);
        // 枚举位置 i
        for (int i = 0; i < Z1.length; i++) for (int j = 0; j < Z1[i].length; j++) Z1[i][j] = sigmoid(Z1[i][j]);
        double[][] H = addBias(matMul(W2, Z1), b);
        // 枚举位置 i
        for (int i = 0; i < H.length; i++) for (int j = 0; j < H[i].length; j++) H[i][j] = sigmoid(H[i][j]);
        double loss = 0;
        // 枚举位置 i
        for (int i = 0; i < H.length; i++)
            // 枚举阶段 j
            for (int j = 0; j < H[i].length; j++) {
                double h = H[i][j];
                double y = Y[i][j];
                loss += -y * Math.log(h) - (1 - y) * Math.log(1 - h);
            }
        System.out.println(format3(loss));
    }
}

// 题目：卷积结果与特征图维度
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O(C(n+2p)^2+C k^2)；空间 O(C(n+2p)^2)，存放填充后的图像；卷积核与参数都是常数规模

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static String nextLine() throws IOException { return br.readLine(); }

    static int pos = 0;
    static String src;

    // 核心方法：skipWs
    static void skipWs() { while (pos < src.length() && Character.isWhitespace(src.charAt(pos))) pos++; }

    // 核心方法：parseValue
    static Object parseValue() {
        skipWs();
        char c = src.charAt(pos);
        // 条件判断
        if (c == '(') return parseSeq(')');
        // 条件判断
        if (c == '[') return parseSeq(']');
        // 返回结果
        return parseNumber();
    }

    // 核心方法：parseSeq
    static List<Object> parseSeq(char close) {
        List<Object> list = new ArrayList<>();
        pos++;
        skipWs();
        // 条件判断
        if (src.charAt(pos) == close) { pos++; return list; }
        // 循环处理
        while (true) {
            list.add(parseValue());
            skipWs();
            char c = src.charAt(pos);
            // 条件判断
            if (c == ',') { pos++; continue; }
            // 条件判断
            if (c == close) { pos++; break; }
        }
        // 返回结果
        return list;
    }

    // 核心方法：parseNumber
    static Double parseNumber() {
        skipWs();
        int start = pos;
        // 条件判断
        if (src.charAt(pos) == '+' || src.charAt(pos) == '-') pos++;
        // 循环处理
        while (pos < src.length()) {
            char c = src.charAt(pos);
            // 条件判断
            if (Character.isDigit(c) || c == '.' || c == 'e' || c == 'E') pos++;
            else if ((c == '+' || c == '-') && pos > start && (src.charAt(pos - 1) == 'e' || src.charAt(pos - 1) == 'E')) pos++;
            else break;
        }
        // 返回结果
        return Double.parseDouble(src.substring(start, pos));
    }

    // 核心方法：toInt3D
    static int[][][] toInt3D(Object o) {
        List<Object> c = (List<Object>) o;
        boolean three = false;
        // 条件判断
        if (!c.isEmpty()) {
            List<Object> first = (List<Object>) c.get(0);
            // 条件判断
            if (!first.isEmpty() && first.get(0) instanceof List) three = true;
        }
        int[][][] arr;
        // 条件判断
        if (three) {
            arr = new int[c.size()][][];
            // 枚举位置 i
            for (int i = 0; i < c.size(); i++) {
                List<Object> plane = (List<Object>) c.get(i);
                arr[i] = new int[plane.size()][];
                // 循环处理
                for (int r = 0; r < plane.size(); r++) {
                    List<Object> row = (List<Object>) plane.get(r);
                    arr[i][r] = new int[row.size()];
                    // 循环处理
                    for (int col = 0; col < row.size(); col++) arr[i][r][col] = (int) Math.round((Double) row.get(col));
                }
            }
        } else {
            int[][] plane = new int[c.size()][];
            // 循环处理
            for (int r = 0; r < c.size(); r++) {
                List<Object> row = (List<Object>) c.get(r);
                plane[r] = new int[row.size()];
                // 循环处理
                for (int col = 0; col < row.size(); col++) plane[r][col] = (int) Math.round((Double) row.get(col));
            }
            arr = new int[1][][];
            arr[0] = plane;
        }
        // 返回结果
        return arr;
    }

    // 核心方法：toDoubleVec
    static double[] toDoubleVec(Object o) {
        List<Object> v = (List<Object>) o;
        double[] a = new double[v.size()];
        // 枚举位置 i
        for (int i = 0; i < v.size(); i++) a[i] = (Double) v.get(i);
        // 返回结果
        return a;
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String imageLine = nextLine();
        String kernelLine = nextLine();
        String paramsLine = nextLine();
        src = imageLine; pos = 0;
        int[][][] image = toInt3D(parseValue());
        src = kernelLine; pos = 0;
        int[][][] kernel = toInt3D(parseValue());
        src = paramsLine; pos = 0;
        double[] params = toDoubleVec(parseValue());
        int i0 = (int) params[0];
        int j0 = (int) params[1];
        int k = (int) params[2];
        int p = (int) params[4];
        int s = (int) params[5];
        int n = image[0].length;
        int C = image.length;
        int padSize = n + 2 * p;
        long[][][] padded = new long[C][padSize][padSize];
        // 循环处理
        for (int ci = 0; ci < C; ci++)
            // 循环处理
            for (int r = 0; r < n; r++)
                // 循环处理
                for (int col = 0; col < n; col++)
                    padded[ci][r + p][col + p] = image[ci][r][col];
        long sum = 0;
        // 循环处理
        for (int ci = 0; ci < C; ci++) {
            int kc = (kernel.length == 1) ? 0 : ci;
            // 循环处理
            for (int a = 0; a < k; a++)
                // 枚举分割点 b
                for (int b = 0; b < k; b++)
                    sum += padded[ci][i0 + a][j0 + b] * (long) kernel[kc][a][b];
        }
        long feature = (long) (n + 2 * p - k) / s + 1;
        System.out.println(sum + " " + feature);
    }
}

