public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static String nextLine() throws IOException { return br.readLine(); }

    // 核心方法：parseCards
    static List<String> parseCards(String s) {
        List<String> cards = new ArrayList<>();
        int i = 0;
        // 循环处理
        while (i < s.length()) {
            // 条件判断
            if (s.charAt(i) == '1') {
                cards.add("10");
                i += 2;
            } else {
                cards.add(String.valueOf(s.charAt(i)));
                i += 1;
            }
        }
        // 返回结果
        return cards;
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        String line = nextLine();
        // 条件判断
        if (line == null) return;
        List<String> cards = parseCards(line.trim());
        List<ArrayDeque<String>> hands = new ArrayList<>();
        hands.add(new ArrayDeque<String>());
        hands.add(new ArrayDeque<String>());
        // 枚举位置 i
        for (int i = 0; i < cards.size(); i++) hands.get(i % 2).addLast(cards.get(i));
        ArrayList<String> table = new ArrayList<>();
        int current = 0;
        // 循环处理
        while (!hands.get(0).isEmpty() && !hands.get(1).isEmpty()) {
            String card = hands.get(current).pollFirst();
            boolean collected = false;
            // 条件判断
            if (card.equals("J") && !table.isEmpty()) {
                table.add(card);
                // 循环处理
                while (!table.isEmpty()) hands.get(current).addLast(table.remove(table.size() - 1));
                collected = true;
            } else if (!card.equals("J") && table.contains(card)) {
                int position = table.indexOf(card);
                table.add(card);
                // 循环处理
                while (table.size() > position) hands.get(current).addLast(table.remove(table.size() - 1));
                collected = true;
            } else {
                table.add(card);
            }
            // 条件判断
            if (!collected) current = 1 - current;
        }
        int winner = hands.get(0).isEmpty() ? 1 : 0;
        String[] names = {"sanqiu", "xiran"};
        System.out.println(names[winner]);
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        // 循环处理
        for (String c : hands.get(winner)) {
            // 条件判断
            if (!first) sb.append(' ');
            sb.append(c);
            first = false;
        }
        System.out.println(sb.toString());
    }
}

items.books/ai-exam/ai-2026/美团/120-动态维护两两绝对差之和:
// 题目：动态维护两两绝对差之和
// 算法：排序 + 扫描
// 模式：ACM（stdin/stdout）
// 复杂度：时间 O((n+m)(n+m))；空间 O(n+m)，用于保存操作、离散值和两棵树状数组

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    // 核心方法：bitAdd
    static void bitAdd(long[] countBit, long[] sumBit, int index, long countDelta, long sumDelta) {
        int size = countBit.length - 1;
        // 循环处理
        while (index <= size) {
            countBit[index] += countDelta;
            sumBit[index] += sumDelta;
            index += index & -index;
        }
    }

    // 核心方法：bitPrefix
    static long[] bitPrefix(long[] countBit, long[] sumBit, int index) {
        long count = 0, total = 0;
        // 循环处理
        while (index > 0) {
            count += countBit[index];
            total += sumBit[index];
            index -= index & -index;
        }
        // 返回结果
        return new long[]{count, total};
    }

    // 核心方法：contribution
    static long contribution(long[] countBit, long[] sumBit, int index, long value, long totalCount, long totalSum) {
        long[] lp = bitPrefix(countBit, sumBit, index);
        long leftCount = lp[0], leftSum = lp[1];
        long leftPart = value * leftCount - leftSum;
        long rightPart = (totalSum - leftSum) - value * (totalCount - leftCount);
        // 返回结果
        return leftPart + rightPart;
    }

    // 核心方法：initialPairSum
    static long initialPairSum(long[] values) {
        long[] sorted = values.clone();
        Arrays.sort(sorted);
        long prefixSum = 0, answer = 0;
        // 枚举位置 i
        for (int i = 0; i < sorted.length; i++) {
            answer += (long) i * sorted[i] - prefixSum;
            prefixSum += sorted[i];
        }
        // 返回结果
        return answer;
    }

    // 核心方法：lowerBound
    static int lowerBound(long[] arr, long key) {
        int lo = 0, hi = arr.length;
        // 循环处理
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            // 条件判断
            if (arr[mid] < key) lo = mid + 1;
            else hi = mid;
        }
        // 返回结果
        return lo;
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        int testCases = nextInt();
        // 循环处理
        for (int tc = 0; tc < testCases; tc++) {
            int n = nextInt();
            int operationCount = nextInt();
            long[] values = new long[n];
            // 枚举位置 i
            for (int i = 0; i < n; i++) values[i] = nextLong();
            int[] opType = new int[operationCount];
            long[] opIndex = new long[operationCount];
            long[] opNew = new long[operationCount];
            TreeSet<Long> allValues = new TreeSet<>();
            // 循环处理
            for (long v : values) allValues.add(v);
            // 循环处理
            for (int o = 0; o < operationCount; o++) {
                opType[o] = nextInt();
                // 条件判断
                if (opType[o] == 1) {
                    opIndex[o] = nextLong();
                    opNew[o] = nextLong();
                    allValues.add(opNew[o]);
                }
            }
            long[] coordinates = new long[allValues.size()];
            int ci = 0;
            // 循环处理
            for (long v : allValues) coordinates[ci++] = v;
            int size = coordinates.length;
            long[] countBit = new long[size + 1];
            long[] sumBit = new long[size + 1];
            long answer = initialPairSum(values);
            long totalCount = n;
            long totalSum = 0;
            // 循环处理
            for (long v : values) totalSum += v;
            // 循环处理
            for (long v : values) {
                int position = lowerBound(coordinates, v) + 1;
                bitAdd(countBit, sumBit, position, 1, v);
            }
            // 循环处理
            for (int o = 0; o < operationCount; o++) {
                // 条件判断
                if (opType[o] != 1) { System.out.println(answer); continue; }
                int index = (int) opIndex[o];
                long newValue = opNew[o];
                long oldValue = values[index - 1];
                // 条件判断
                if (oldValue == newValue) continue;
                int oldPosition = lowerBound(coordinates, oldValue) + 1;
                int newPosition = lowerBound(coordinates, newValue) + 1;
                bitAdd(countBit, sumBit, oldPosition, -1, -oldValue);
                totalCount -= 1;
                totalSum -= oldValue;
                answer -= contribution(countBit, sumBit, oldPosition, oldValue, totalCount, totalSum);
                answer += contribution(countBit, sumBit, newPosition, newValue, totalCount, totalSum);
                bitAdd(countBit, sumBit, newPosition, 1, newValue);
                totalCount += 1;
                totalSum += newValue;
                values[index - 1] = newValue;
            }
        }
    }
}

items.books/ai-exam/ai-2026/美团/121-公约数区间和.md:
// 题目：公约数区间和
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）
// 复杂度：时间 预处理欧拉函数表需要 O(A A)；每组询问需要 O( b-a)，当 a=b 时为 O(1)；空间 O(A)，用于存储欧拉函数表

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    static final long MOD = 1000000007L;
    static final int MAX_VALUE = 100000;
    static final long INV_TWO = (MOD + 1) / 2;

    // 核心方法：buildTotients
    static long[] buildTotients(int limit) {
        long[] phi = new long[limit + 1];
        // 枚举位置 i
        for (int i = 0; i <= limit; i++) phi[i] = i;
        // 循环处理
        for (int prime = 2; prime <= limit; prime++) {
            // 条件判断
            if (phi[prime] == prime) {
                // 循环处理
                for (int multiple = prime; multiple <= limit; multiple += prime) {
                    phi[multiple] = phi[multiple] / prime * (prime - 1);
                }
            }
        }
        // 返回结果
        return phi;
    }

    // 核心方法：gcdRangeSum
    static long gcdRangeSum(long[] phi, long difference, long left, long right) {
        long answer = 0;
        long divisor = 1;
        // 循环处理
        while (divisor * divisor <= difference) {
            // 条件判断
            if (difference % divisor == 0) {
                long count = right / divisor - (left - 1) / divisor;
                answer = (answer + phi[(int) divisor] * (count % MOD)) % MOD;
                long paired = difference / divisor;
                // 条件判断
                if (paired != divisor) {
                    count = right / paired - (left - 1) / paired;
                    answer = (answer + phi[(int) paired] * (count % MOD)) % MOD;
                }
            }
            divisor++;
        }
        // 返回结果
        return answer;
    }

    // 主函数：读取输入并输出答案
    public static void main(String[] args) throws IOException {
        long[] phi = buildTotients(MAX_VALUE);
        // 循环处理
        int testCases = nextInt();
        // 循环处理
        for (int tc = 0; tc < testCases; tc++) {
            // 循环处理
            long a = nextLong();
            long b = nextLong();
            long leftIndex = nextLong();
            long rightIndex = nextLong();
            long answer;
            // 条件判断
            if (a == b) {
                long count = (rightIndex - leftIndex + 1) % MOD;
                long endpoints = ((a + leftIndex) % MOD + (a + rightIndex) % MOD) % MOD;
                answer = count * endpoints % MOD * INV_TWO % MOD;
            } else {
                long difference = Math.abs(b - a);
                long leftValue = a + leftIndex;
                long rightValue = a + rightIndex;
                answer = gcdRangeSum(phi, difference, leftValue, rightValue);
            }
            System.out.println(answer);
        }
    }
}

