    static long nextLong() throws IOException { return Long.parseLong(next()); }
    public static void main(String[] args) throws IOException {
        int t = nextInt();
        StringBuilder out = new StringBuilder();
        for (int tc = 0; tc < t; tc++) {
            int n = nextInt();
            long[] a = new long[n];
