// 题目：电商购物记录商品关联分析
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int Q = sc.nextInt();
        HashMap<Long, Integer> pairCount = new HashMap<>();
        for (int u = 0; u < N; u++) {
            int k = sc.nextInt();
            HashSet<Integer> set = new HashSet<>();
            for (int i = 0; i < k; i++) set.add(sc.nextInt());
            int[] ids = new int[set.size()];
            int idx = 0;
            for (int v : set) ids[idx++] = v;
            Arrays.sort(ids);
            for (int i = 0; i < ids.length; i++) {
                for (int j = i + 1; j < ids.length; j++) {
                    long key = (long) ids[i] * 2001L + ids[j];
                    pairCount.merge(key, 1, Integer::sum);
                }
            }
        }
        int[] counts = new int[pairCount.size()];
        int idx = 0;
        for (int v : pairCount.values()) counts[idx++] = v;
        Arrays.sort(counts);
        StringBuilder out = new StringBuilder();
        for (int q = 0; q < Q; q++) {
            int T = sc.nextInt();
            int pos = lowerBound(counts, T);
            out.append(counts.length - pos).append('\n');
        }
        System.out.print(out);
    }

    static int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
}

