// 题目：无人机的安全距离检测
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static long nextLong() throws IOException { return Long.parseLong(next()); }
    static String nextLine() throws IOException { return br.readLine(); }
    static class Pt {
        long x, y;
        Pt(long x, long y) { this.x = x; this.y = y; }
    }

    static Pt[] ps;
    static long best;

    public static void main(String[] args) throws IOException {
        String line = nextLine();
        if (line == null) return;
        int n = Integer.parseInt(line.trim());
        ps = new Pt[n];
        for (int i = 0; i < n; i++) {
            ps[i] = new Pt(nextLong(), nextLong());
        }
        if (n < 2) { System.out.println("0.0000"); return; }
        Arrays.sort(ps, (a, b) -> a.x != b.x ? Long.compare(a.x, b.x) : Long.compare(a.y, b.y));
        best = Long.MAX_VALUE;
        rec(0, n - 1);
        System.out.printf(Locale.ROOT, "%.4f%n", Math.sqrt((double) best));
    }

    static long d2(Pt a, Pt b) {
        long dx = a.x - b.x, dy = a.y - b.y;
        return dx * dx + dy * dy;
    }

    static void rec(int l, int r) {
        if (r - l <= 3) {
            for (int i = l; i <= r; i++)
                for (int j = i + 1; j <= r; j++) {
                    long d = d2(ps[i], ps[j]);
                    if (d < best) best = d;
                }
            Arrays.sort(ps, l, r + 1, (a, b) -> Long.compare(a.y, b.y));
            return;
        }
        int mid = (l + r) >>> 1;
        long midx = ps[mid].x;
        rec(l, mid);
        rec(mid + 1, r);
        ArrayList<Pt> strip = new ArrayList<>();
        for (int i = l; i <= r; i++) {
            long dx = ps[i].x - midx;
            if (dx * dx < best) strip.add(ps[i]);
        }
        strip.sort((a, b) -> Long.compare(a.y, b.y));
        for (int i = 0; i < strip.size(); i++) {
            for (int j = i + 1; j < strip.size(); j++) {
                long dy = strip.get(j).y - strip.get(i).y;
                if (dy * dy >= best) break;
                long d = d2(strip.get(i), strip.get(j));
                if (d < best) best = d;
            }
        }
        Pt[] merged = new Pt[r - l + 1];
        int i = l, j = mid + 1, k = 0;
        while (i <= mid && j <= r) {
            if (ps[i].y <= ps[j].y) merged[k++] = ps[i++]; else merged[k++] = ps[j++];
        }
        while (i <= mid) merged[k++] = ps[i++];
        while (j <= r) merged[k++] = ps[j++];
        System.arraycopy(merged, 0, ps, l, merged.length);
    }
}

