// 题目：子集合
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int T = sc.nextInt();
        StringBuilder out = new StringBuilder();
        for (int tc = 0; tc < T; tc++) {
            int n = sc.nextInt();
            long[] a = new long[n + 1];
            for (int i = 1; i <= n; i++) { a[i] = sc.nextLong(); }
            int q = sc.nextInt();
            int[] Ks = new int[q];
            int maxK = 0;
            for (int i = 0; i < q; i++) { Ks[i] = sc.nextInt(); if (Ks[i] > maxK) maxK = Ks[i]; }
            int size = 1;
            int need = Math.max(n, maxK) + 1;
            while (size < need) size <<= 1;
            long[] f = new long[size];
            for (int i = 1; i <= n && i < size; i++) f[i] = a[i];
            for (int b = 0; (1 << b) < size; b++) {
                int bit = 1 << b;
                for (int mask = 0; mask < size; mask++) {
                    if ((mask & bit) != 0) f[mask] += f[mask ^ bit];
                }
            }
            for (int i = 0; i < q; i++) out.append(f[Ks[i]]).append('\n');
        }
        System.out.print(out);
    }
}

