// 题目：第1题
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }
    static long nextLong() throws IOException { return Long.parseLong(next()); }

    public static void main(String[] args) throws IOException {
        int P = nextInt();
        StringBuilder out = new StringBuilder();
        for (int tc = 0; tc < P; tc++) {
            long T = nextLong();
            long C = nextLong();
            int N = nextInt();
            int M = nextInt();
            long[] rel = new long[N];
            for (int i = 0; i < N; i++) { rel[i] = nextLong(); }
            long[] kill = new long[M];
            for (int i = 0; i < M; i++) { kill[i] = nextLong(); }
            int best = 0;
            for (long r : rel) {
                int lo = lowerBound(kill, r);
                int hi = lowerBound(kill, r + T);
                if (hi - lo > best) best = hi - lo;
            }
            out.append(best).append('\n');
        }
        System.out.print(out);
    }

    static int lowerBound(long[] arr, long target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
}

