// 题目：第2题
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {

    static double[][] p = new double[3][2];

    static double cross(double px, double py, double[] a, double[] b) {
        return (px - b[0]) * (a[1] - b[1]) - (a[0] - b[0]) * (py - b[1]);
    }

    static boolean inside(double x, double y) {
        double d1 = cross(x, y, p[0], p[1]);
        double d2 = cross(x, y, p[1], p[2]);
        double d3 = cross(x, y, p[2], p[0]);
        boolean neg = d1 < -1e-12 || d2 < -1e-12 || d3 < -1e-12;
        boolean pos = d1 > 1e-12 || d2 > 1e-12 || d3 > 1e-12;
        return !(neg && pos);
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), M = sc.nextInt(), S = sc.nextInt();
        for (int i = 0; i < 3; i++) { p[i][0] = Double.parseDouble(sc.next()); p[i][1] = Double.parseDouble(sc.next()); }
        double area2 = Math.abs(cross(p[2][0], p[2][1], p[0], p[1]));
        long[] hist = new long[S * S + 1];
        if (area2 < 1e-12) {
            hist[0] = (long) N * M;
        } else {
            double minx = Math.min(p[0][0], Math.min(p[1][0], p[2][0]));
            double maxx = Math.max(p[0][0], Math.max(p[1][0], p[2][0]));
            double miny = Math.min(p[0][1], Math.min(p[1][1], p[2][1]));
            double maxy = Math.max(p[0][1], Math.max(p[1][1], p[2][1]));
            int i0 = Math.max(0, (int) Math.floor(minx));
            int i1 = Math.min(N - 1, (int) Math.floor(maxx));
            int j0 = Math.max(0, (int) Math.floor(miny));
            int j1 = Math.min(M - 1, (int) Math.floor(maxy));
            long bbox = 0;
            if (i0 <= i1 && j0 <= j1) {
                for (int i = i0; i <= i1; i++) {
                    for (int j = j0; j <= j1; j++) {
                        int cnt = 0;
                        boolean allIn = inside(i, j) && inside(i + 1, j) && inside(i, j + 1) && inside(i + 1, j + 1);
                        if (allIn) {
                            cnt = S * S;
                        } else {
