    static long nextLong() throws IOException { return Long.parseLong(next()); }
    // 主函数：读取输入并输出答案
    public static void main(String[] a)throws IOException {
        int t=nextInt();
        StringBuilder out=new StringBuilder();
        // 循环处理
        for(int q=0;q<t;q++) {
            int n=nextInt();
            long m=nextLong();
            long[] A=new long[n],B=new long[n];
            long total=0;
            // 枚举位置 i
            for(int i=0;i<n;i++) {
                A[i]=nextLong();
                total+=A[i];
            }
            // 枚举位置 i
            for(int i=0;i<n;i++) {
                B[i]=nextLong();
                total+=B[i];
            }
            Long[] Ab=new Long[n];
            // 枚举位置 i
            for(int i=0;i<n;i++)Ab[i]=A[i];
            Arrays.sort(Ab,(x,y)->Long.compare(y,x));
            Arrays.sort(B);
            int j=0;
            long cnt=0;
            // 枚举位置 i
            for(int i=0;i<n;i++) {
                long x=Ab[i];
                // 循环处理
                while(j<n&&x+B[j]<m)j++;
                // 条件判断
                if(j==n)break;
                cnt++;
                j++;
            }
            out.append(total-m*cnt);
            // 条件判断
            if(q+1<t)out.append((char)10);
        }
        System.out.print(out);
    }
}

