// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;
public class Main{
 // 核心方法：minimumIncrement
 static long minimumIncrement(int n,int m,int length,int[] b){
  long[][] cost=new long[length][m];
  ArrayList<ArrayList<Integer>> groups=new ArrayList<>();
  // 枚举阶段 j
  for(int j=0;j<length;j++){
   ArrayList<Integer> values=new ArrayList<>();
   // 循环处理
   for(int idx=j;idx<n;idx+=length)values.add(b[idx]);
   groups.add(values);
   // 循环处理
   for(int value:values)for(int r=0;r<m;r++)cost[j][r]+=Math.floorMod(r-value,m);
  }
  int freeGroup=0,minLen=Integer.MAX_VALUE;
  // 枚举阶段 j
  for(int j=0;j<length;j++)if(groups.get(j).size()<minLen){minLen=groups.get(j).size();freeGroup=j;}
  long inf=Long.MAX_VALUE/4;
  long[] dp=new long[m];Arrays.fill(dp,inf);dp[0]=0;
  // 枚举阶段 j
  for(int j=0;j<length;j++){
   // 条件判断
   if(j==freeGroup)continue;
   long[] nd=new long[m];Arrays.fill(nd,inf);
   HashSet<Integer> distinct=new HashSet<>(groups.get(j));
   // 循环处理
   for(int r:distinct){
    long add=cost[j][r];
    // 循环处理
    for(int s=0;s<m;s++){
     long old=dp[s];
     // 条件判断
     if(old<inf){int nsi=(s+r)%m;long cand=old+add;if(cand<nd[nsi])nd[nsi]=cand;}
    }
   }
   dp=nd;
  }
  long best=inf;
  // 循环处理
  for(int s=0;s<m;s++){long v=dp[s]+cost[freeGroup][Math.floorMod(-s,m)];if(v<best)best=v;}
  // 返回结果
  return best;
 }
 // 主函数：读取输入并输出答案
    public static void main(String[] args)throws IOException{
        Scanner sc = new Scanner(System.in);
  int n=sc.nextInt(),m=sc.nextInt(),length=sc.nextInt();
  int[] b=new int[n];
  // 枚举位置 i
  for(int i=0;i<n;i++)b[i]=sc.nextInt();
  System.out.println(minimumIncrement(n,m,length,b));
 }
}
